function escapeHtml(str) {
    if (!str) return '';
    return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function escapeJsString(value) {
    return String(value ?? '')
        .replace(/\\/g, '\\\\')
        .replace(/'/g, "\\'")
        .replace(/\r/g, '')
        .replace(/\n/g, '\\n');
}

function normalizeProfessionKey(value) {
    return String(value || '')
        .trim()
        .toLowerCase()
        .replace(/\s+/g, '_')
        .replace(/[^a-z0-9_:-]/g, '')
        .slice(0, 64);
}

function normalizeProfessionList(value, exclude = []) {
    const source = Array.isArray(value)
        ? value
        : (typeof value === 'string'
            ? (() => {
                try {
                    const parsed = JSON.parse(value);
                    return Array.isArray(parsed) ? parsed : value.split(/[\n,;]+/);
                } catch {
                    return value.split(/[\n,;]+/);
                }
            })()
            : []);
    const blocked = new Set(exclude.map(normalizeProfessionKey).filter(Boolean));
    const seen = new Set();
    const result = [];
    source.forEach(item => {
        const key = normalizeProfessionKey(item);
        if (!key || blocked.has(key) || seen.has(key)) return;
        seen.add(key);
        result.push(key);
    });
    return result;
}

function professionTitle(key) {
    const normalized = normalizeProfessionKey(key);
    const profession = hrProfessions.find(item => normalizeProfessionKey(item.key) === normalized);
    return profession?.title || ROLE_LABELS[normalized] || normalized;
}

function staffSecondaryProfessions(staff = {}) {
    return normalizeProfessionList(staff.secondary_professions || staff.secondaryProfessions, [staff.role_type]);
}

function staffProfessionKeys(staff = {}) {
    return normalizeProfessionList([
        staff.role_type,
        ...staffSecondaryProfessions(staff)
    ]);
}

function staffHasProfession(staff = {}, key = '') {
    const normalized = normalizeProfessionKey(key);
    if (!normalized) return true;
    return normalizeProfessionKey(staff.role_type) === normalized || staffSecondaryProfessions(staff).includes(normalized);
}

function staffProfessionOptions(staff = {}, current = '') {
    const selected = normalizeProfessionKey(current);
    const keys = normalizeProfessionList([
        staff.role_type,
        ...staffSecondaryProfessions(staff),
        selected
    ]);
    return keys.map(key => ({
        value: key,
        label: professionTitle(key),
        selected: selected ? key === selected : key === normalizeProfessionKey(staff.role_type)
    }));
}

function normalizeSearchText(value) {
    return String(value || '')
        .toLowerCase()
        .normalize('NFKD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/['`\u2019\u02bc]/g, '')
        .replace(/\s+/g, ' ')
        .trim();
}

const APPROVED_COMPANY_STRUCTURE_SUBDIVISION_TITLES = Object.freeze([
    'Керівництво',
    'Адміністративно-операційний відділ',
    'Відділ продажів / CRM',
    'Арт-відділ',
    'Ігрові зони',
    'Кухня',
    'Кондитерський цех',
    'Технічний відділ',
    'Бухгалтерія',
    'HR',
    'Маркетинг',
    'IT'
]);

const APPROVED_COMPANY_STRUCTURE_SUBDIVISION_TITLE_KEYS = Object.freeze(
    APPROVED_COMPANY_STRUCTURE_SUBDIVISION_TITLES.map(normalizeSearchText)
);

const APPROVED_COMPANY_STRUCTURE_SUBDIVISION_TITLE_SET = new Set(
    APPROVED_COMPANY_STRUCTURE_SUBDIVISION_TITLE_KEYS
);

function approvedCompanyStructureSubdivisionOrder(node = {}) {
    const title = normalizeSearchText(node.title || node.label || node.name);
    const index = APPROVED_COMPANY_STRUCTURE_SUBDIVISION_TITLE_KEYS.indexOf(title);
    return index >= 0 ? index : APPROVED_COMPANY_STRUCTURE_SUBDIVISION_TITLE_KEYS.length;
}

function sortApprovedCompanyStructureSubdivisionNodes(nodes = []) {
    return [...(nodes || [])].sort((a, b) => {
        const approvedDelta = approvedCompanyStructureSubdivisionOrder(a) - approvedCompanyStructureSubdivisionOrder(b);
        if (approvedDelta) return approvedDelta;
        return (Number(a?.order) || 0) - (Number(b?.order) || 0)
            || String(a?.title || '').localeCompare(String(b?.title || ''), 'uk');
    });
}

function companyStructureNodeIsArchivedOrInactive(node = {}) {
    return node.archived === true
        || node.is_archived === true
        || node.isArchived === true
        || node.active === false
        || node.is_active === false
        || node.isActive === false
        || Boolean(node.archived_at || node.archivedAt);
}

function isApprovedCompanyStructureSubdivisionNode(node = {}) {
    const title = normalizeSearchText(node.title || node.label || node.name);
    return Boolean(
        title
        && APPROVED_COMPANY_STRUCTURE_SUBDIVISION_TITLE_SET.has(title)
        && !companyStructureNodeIsArchivedOrInactive(node)
    );
}

function visibleCompanyStructureSubdivisionNodes(nodes = []) {
    const seenTitles = new Set();
    return sortApprovedCompanyStructureSubdivisionNodes((Array.isArray(nodes) ? nodes : [])
        .filter(isApprovedCompanyStructureSubdivisionNode)
        .filter(node => {
            const title = normalizeSearchText(node.title || node.label || node.name);
            if (!title || seenTitles.has(title)) return false;
            seenTitles.add(title);
            return true;
        }));
}

function normalizeDepartmentKey(value) {
    const normalized = String(value || '').trim().toLowerCase().replace(/\s+/g, '_');
    return normalized ? normalized.slice(0, 80) : 'none';
}

function normalizeStaffDisplayGroupKey(value) {
    const key = String(value || '').trim().toLowerCase().replace(/\s+/g, '_');
    return STAFF_DISPLAY_GROUP_ORDER.includes(key) ? key : '';
}

function normalizeStaffDisplayGroups(groups = []) {
    if (!Array.isArray(groups)) return [];
    return groups
        .map((group, index) => {
            const source = group && typeof group === 'object' ? group : {};
            const key = normalizeStaffDisplayGroupKey(source.key || source.value || source.id);
            if (!key) return null;
            return {
                key,
                label: String(source.label || source.name || STAFF_DISPLAY_GROUP_LABELS[key] || key).trim(),
                order: Number.isFinite(Number(source.order)) ? Number(source.order) : index
            };
        })
        .filter(Boolean)
        .sort((a, b) => a.order - b.order || STAFF_DISPLAY_GROUP_ORDER.indexOf(a.key) - STAFF_DISPLAY_GROUP_ORDER.indexOf(b.key));
}

function setStaffDisplayGroupsContract(groups = [], options = {}) {
    const normalized = normalizeStaffDisplayGroups(groups);
    if (normalized.length || options.clear) {
        staffDisplayGroupsContract = normalized;
        todayDisplayGroups = normalized;
    }
    return staffDisplayGroupsContract;
}

function activeStaffDisplayGroups(groups = staffDisplayGroupsContract) {
    const normalized = normalizeStaffDisplayGroups(groups);
    if (normalized.length) return normalized;
    if (staffDisplayGroupsContract.length) return staffDisplayGroupsContract;
    return STAFF_DISPLAY_GROUP_ORDER.map((key, index) => ({
        key,
        label: STAFF_DISPLAY_GROUP_LABELS[key] || key,
        order: index
    }));
}

function staffDisplayGroupLabel(key, groups = staffDisplayGroupsContract) {
    const normalized = normalizeStaffDisplayGroupKey(key);
    const apiGroup = activeStaffDisplayGroups(groups).find(group => group.key === normalized);
    return apiGroup?.label || STAFF_DISPLAY_GROUP_LABELS[normalized] || normalized || '';
}

function departmentLabel(value) {
    const raw = String(value || '').trim();
    if (!raw) return 'Без відділу';
    const key = normalizeDepartmentKey(raw);
    if (STAFF_DEPARTMENT_LABELS[key]) return STAFF_DEPARTMENT_LABELS[key];
    return raw
        .split(/[_-]+/)
        .filter(Boolean)
        .map(part => part.charAt(0).toUpperCase() + part.slice(1))
        .join(' ');
}

function companyStructureApprovedFallbackNode(nodeId = '') {
    const selected = String(nodeId || '').trim();
    if (!selected) return null;
    const fromLoaded = companyStructureNodeById(selected);
    if (fromLoaded && isApprovedCompanyStructureSubdivisionNode(fromLoaded)) return fromLoaded;
    return DEFAULT_COMPANY_STRUCTURE_NODES.find(node => String(node.id || '') === selected) || null;
}

function staffCardApprovedCompanyStructureSelectNodes() {
    const byTitle = new Map();
    visibleCompanyStructureSubdivisionNodes(DEFAULT_COMPANY_STRUCTURE_NODES)
        .forEach(node => {
            const title = normalizeSearchText(node.title || node.label || node.name);
            if (title) byTitle.set(title, node);
        });
    visibleCompanyStructureSubdivisionNodes(companyStructureNodes || [])
        .forEach(node => {
            const title = normalizeSearchText(node.title || node.label || node.name);
            if (!title || !APPROVED_COMPANY_STRUCTURE_SUBDIVISION_TITLE_SET.has(title)) return;
            const fallback = byTitle.get(title) || {};
            byTitle.set(title, {
                ...fallback,
                ...node,
                title: node.title || fallback.title,
                meta: node.meta ?? fallback.meta ?? null
            });
        });
    return APPROVED_COMPANY_STRUCTURE_SUBDIVISION_TITLE_KEYS
        .map(title => byTitle.get(title))
        .filter(Boolean);
}

function staffCardCompanyStructureSelectNodes(current = '') {
    const selected = String(current || '').trim();
    const candidates = [...staffCardApprovedCompanyStructureSelectNodes()];
    const currentNode = companyStructureApprovedFallbackNode(selected);
    if (currentNode && !candidates.some(node => String(node.id || '') === selected)) {
        candidates.push(currentNode);
    }
    const seenIds = new Set();
    const seenTitles = new Set();
    return sortApprovedCompanyStructureSubdivisionNodes(candidates.filter(node => {
        const id = String(node.id || '').trim();
        const title = normalizeSearchText(node.title || node.label || node.name);
        if (!id || !title) return false;
        if (seenIds.has(id) || seenTitles.has(title)) return false;
        seenIds.add(id);
        seenTitles.add(title);
        return true;
    }));
}

function companyStructureSelectOptions(current = '') {
    const selected = String(current || '').trim();
    const visibleNodes = staffCardCompanyStructureSelectNodes(selected);
    const options = visibleNodes.map(node => ({
        value: node.id,
        label: `${node.title}${node.meta ? ' - ' + node.meta : ''}`,
        selected: node.id === selected
    }));
    return [{ value: '', label: 'Без привʼязки', selected: !selected }, ...options];
}

function renderSelectOptions(options = [], selected = '') {
    const selectedValue = String(selected || '');
    return options.map(option => {
        const value = String(option.value ?? '');
        const isSelected = option.selected || value === selectedValue;
        return `<option value="${escapeHtml(value)}"${isSelected ? ' selected' : ''}>${escapeHtml(option.label ?? value)}</option>`;
    }).join('');
}

function companyStructureNodeTitle(nodeId = '') {
    const normalized = String(nodeId || '').trim();
    if (!normalized) return '';
    const node = companyStructureNodeById(normalized);
    return node?.title || normalized;
}

function professionStructureNodeId(professionKey = '') {
    const key = normalizeProfessionKey(professionKey);
    const profession = hrProfessions.find(item => normalizeProfessionKey(item.key) === key);
    return profession?.structure_node_id || profession?.structureNodeId || '';
}

function staffStructureNodeId(staff = {}) {
    return staff.company_structure_node_id || staff.companyStructureNodeId || professionStructureNodeId(staff.role_type);
}

function staffStructureNodeTitle(staff = {}) {
    return companyStructureNodeTitle(staffStructureNodeId(staff));
}

function staffProfessionRateRows(staff = {}) {
    return Array.isArray(staff.profession_rates || staff.professionRates)
        ? (staff.profession_rates || staff.professionRates)
        : [];
}

function normalizeStaffRateUnit(value) {
    const unit = String(value || '').trim().toLowerCase();
    if (['day', 'daily', 'per_day', 'per-day'].includes(unit)) return 'day';
    if (['month', 'monthly', 'per_month', 'per-month'].includes(unit)) return 'month';
    return 'hour';
}

function staffRateUnit(staff = {}) {
    return normalizeStaffRateUnit(staff.rate_unit || staff.rateUnit);
}

function currentEditRateUnit(staff = {}) {
    return normalizeStaffRateUnit(document.getElementById('editRateUnit')?.value || staffRateUnit(staff));
}

function staffRateUnitSuffix(unit = 'hour') {
    const normalized = normalizeStaffRateUnit(unit);
    if (normalized === 'day') return 'день';
    if (normalized === 'month') return 'міс';
    return 'год';
}

function formatStaffRate(rate, unit = 'hour') {
    return `${Number(rate || 0)} ₴/${staffRateUnitSuffix(unit)}`;
}

function staffProfessionRateMap(staff = {}) {
    const map = new Map();
    staffProfessionRateRows(staff).forEach(row => {
        const key = normalizeProfessionKey(row.profession_key || row.professionKey || row.key);
        const rate = Number(row.hourly_rate ?? row.hourlyRate ?? row.rate);
        if (key && Number.isFinite(rate) && rate > 0) map.set(key, rate);
    });
    return map;
}

function staffProfessionRateFor(staff = {}, professionKey = '') {
    const key = normalizeProfessionKey(professionKey);
    const override = staffProfessionRateMap(staff).get(key);
    return Number.isFinite(override) && override > 0 ? override : Number(staff.hourly_rate || 0);
}

function staffProfileCompleteness(staff = {}) {
    const checks = [
        staff.name,
        staff.role_type,
        staff.phone,
        staff.emergency_contact || staff.emergency_phone,
        staff.birth_date,
        staff.address,
        Number(staff.hourly_rate || 0) > 0 || staffProfessionRateRows(staff).length > 0
    ];
    const done = checks.filter(Boolean).length;
    return { done, total: checks.length, percent: Math.round((done / checks.length) * 100) };
}

function staffHasProfilePhoto(staff = {}) {
    return Boolean(String(staff.photo_url || staff.photoUrl || '').trim());
}

function staffHasFaceDescriptor(staff = {}) {
    return staffUiBoolean(staff.has_face_descriptor ?? staff.hasFaceDescriptor, false);
}

function staffHasCrmAccount(staff = {}) {
    return staffUiBoolean(staff.has_account ?? staff.hasAccount, false);
}

function staffHasStructureLink(staff = {}) {
    return Boolean(
        staff.company_structure_node_id ||
        staff.companyStructureNodeId ||
        staff.structure_node_id ||
        staff.structureNodeId ||
        staffStructureNodeTitle(staff)
    );
}

function renderStaffReadinessBadges(staff = {}) {
    const training = staffTrainingReadiness(staff);
    const profile = staffProfileCompleteness(staff);
    const structureTitle = staffStructureNodeTitle(staff);
    const badge = (state, title, value, label) => `
        <span class="hr-ready-badge ${state}" title="${escapeHtml(title)}" aria-label="${escapeHtml(title)}">
            <b>${escapeHtml(value)}</b><small>${escapeHtml(label)}</small>
        </span>`;
    return `<div class="hr-ready-badges">
        ${badge(staffHasProfilePhoto(staff) ? 'is-ok' : 'is-warn', staffHasProfilePhoto(staff) ? 'Фото профілю додано у photo_url' : 'Фото профілю не додано у photo_url', 'Фото профілю', staffHasProfilePhoto(staff) ? 'є' : 'нема')}
        ${badge(staffHasFaceDescriptor(staff) ? 'is-ok' : 'is-warn', staffHasFaceDescriptor(staff) ? 'Камера / Face ID налаштована' : 'Камера / Face ID не налаштована. Реєструється через модуль Камера / check-in.', 'Face ID', staffHasFaceDescriptor(staff) ? 'є' : 'нема')}
        ${badge(staffHasCrmAccount(staff) ? 'is-ok' : 'is-info', staffHasCrmAccount(staff) ? 'CRM-акаунт привʼязано' : 'CRM-акаунт не привʼязано. Це setup-ознака, не критичний блокер без окремого бізнес-правила.', 'CRM', staffHasCrmAccount(staff) ? 'є' : 'не прив.')}
        ${badge(profile.percent >= 85 ? 'is-ok' : profile.percent >= 55 ? 'is-info' : 'is-warn', `Заповнення профілю: ${profile.percent}% (${profile.done}/${profile.total} полів)`, 'Заповнення', `${profile.done}/${profile.total}`)}
        ${badge(trainingTone(training.percent, training.total), training.total ? `Навчання: ${training.completed}/${training.total} пунктів, ${training.percent}%` : 'Навчальні чеклісти ще не створені', 'Навчання', training.total ? `${training.percent}%` : 'нема')}
        ${badge(structureTitle ? 'is-info' : 'is-muted', structureTitle ? `Структура: ${structureTitle}` : 'Не привʼязано до структури', 'Структ.', structureTitle ? 'є' : 'нема')}
    </div>`;
}

function renderStaffRateSummary(staff = {}) {
    const professionKeys = normalizeProfessionList([staff.role_type, ...staffSecondaryProfessions(staff)]);
    if (!professionKeys.length) return '';
    const unit = staffRateUnit(staff);
    const rates = professionKeys
        .map(key => ({ key, label: professionTitle(key), rate: staffProfessionRateFor(staff, key) }))
        .filter(item => Number(item.rate) > 0);
    if (!rates.length) return '';
    const baseRate = Number(staff.hourly_rate || 0);
    const hasOverrides = staffProfessionRateRows(staff).length > 0;
    if (!hasOverrides && baseRate > 0) return formatStaffRate(baseRate, unit);
    return rates.slice(0, 3).map(item => `${item.label}: ${formatStaffRate(item.rate, unit)}`).join(' · ');
}

function syncStaffProfileHeaderName(value, staff = null) {
    const header = document.getElementById('editStaffHeaderName');
    if (header) header.textContent = String(value || '').trim() || 'ПІБ';
    const mainName = document.getElementById('editStaffMainName');
    if (mainName) mainName.textContent = String(value || '').trim() || 'ПІБ';
    const role = document.getElementById('editStaffHeaderRole');
    if (role && staff) role.textContent = staffTeamPrimaryProfessionLabel(staff);
    const status = document.getElementById('editStaffHeaderStatus');
    if (status && staff) {
        const pool = staff.is_active === false ? 'Звільнений' : HR_POOL_LABELS[staffPoolStatus(staff)] || 'Основна команда';
        status.textContent = pool;
    }
}

function teamSearchHaystack(staff = {}) {
    const professionTexts = normalizeProfessionList([staff.role_type, ...staffSecondaryProfessions(staff)])
        .flatMap(key => [key, professionTitle(key)]);
    return normalizeSearchText([
        staff.name,
        staff.phone,
        staff.position,
        staff.department,
        staff.address,
        staff.telegram_username,
        staffStructureNodeTitle(staff),
        HR_POOL_LABELS[staffPoolStatus(staff)],
        ...professionTexts
    ].filter(Boolean).join(' '));
}

function staffPoolStatus(staff = {}) {
    return String(staff.hr_pool_status || staff.hrPoolStatus || 'core').trim().toLowerCase() || 'core';
}

function staffUiBoolean(value, fallback = false) {
    if (value === true || value === 1 || value === '1') return true;
    if (value === false || value === 0 || value === '0') return false;
    const text = String(value ?? '').trim().toLowerCase();
    if (['true', 'yes', 'y'].includes(text)) return true;
    if (['false', 'no', 'n'].includes(text)) return false;
    return fallback;
}

function staffUiDate(value) {
    if (!value) return '';
    if (value instanceof Date) return formatDate(value);
    const match = String(value).match(/^\d{4}-\d{2}-\d{2}/);
    return match ? match[0] : '';
}

function isHrScheduleableStaffForDate(staff = {}, date = '') {
    if (!staff) return false;
    if (!staffUiBoolean(staff.is_active ?? staff.isActive, true)) return false;
    if (staffPoolStatus(staff) !== 'core') return false;
    if (staffUiBoolean(staff.is_freelance ?? staff.isFreelance, false)) return false;
    const targetDate = staffUiDate(date) || todayStr();
    const terminationDate = staffUiDate(staff.termination_date || staff.terminationDate);
    if (terminationDate && targetDate && terminationDate <= targetDate) return false;
    return true;
}

function hrScheduleableStaffForUi(staffList = [], date = '') {
    return (Array.isArray(staffList) ? staffList : [])
        .filter(staff => isHrScheduleableStaffForDate(staff, date));
}

function hrScheduleableStaffErrorMessage(result = {}, fallback = 'Помилка') {
    const code = String(result?.code || '').trim();
    if (code === 'STAFF_INACTIVE') return 'Працівник неактивний і не може бути доданий в активний графік.';
    if (code === 'STAFF_BLACKLISTED') return 'Працівник у чорному списку і не може бути доданий в активний графік.';
    if (code === 'STAFF_NOT_CORE_POOL') return 'Працівник не в основній команді і не може бути доданий в активний графік.';
    if (code === 'STAFF_FREELANCE_NOT_ALLOWED') return 'Фріланс-працівник не може бути доданий без explicit режиму.';
    if (code === 'STAFF_TERMINATED') return 'Працівник звільнений на дату цієї зміни.';
    if (code === 'STAFF_NOT_SCHEDULEABLE') return 'Працівник не доступний для активного графіка на цю дату.';
    return result?.error || fallback;
}

async function refreshHrOperationalViews() {
    const jobs = [];
    if (!hasHrStaffScheduleModule() && scheduleWeekStart instanceof Date && !Number.isNaN(scheduleWeekStart.getTime())) {
        jobs.push(loadSchedule().catch(err => console.warn('refresh schedule after staff lifecycle failed', err)));
    }
    if (todayData) {
        jobs.push(loadToday().catch(err => console.warn('refresh today after staff lifecycle failed', err)));
    }
    await Promise.all(jobs);
}

function isInternStaff(staff = {}) {
    return normalizeProfessionKey(staff.role_type) === 'intern' || staffSecondaryProfessions(staff).includes('intern');
}

function bucketForStaff(staff = {}) {
    if (staff.is_active === false) return 'dismissed';
    const pool = staffPoolStatus(staff);
    if (pool === 'blacklisted') return 'blacklist';
    if (pool === 'reserve') return 'reserve';
    return isInternStaff(staff) ? 'interns' : 'workers';
}

function monthOptionLabel(date) {
    return `${MONTHS_SHORT[date.getMonth()]} ${date.getFullYear()}`;
}

function professionOptionsFromCatalog(current = '') {
    const currentKey = normalizeProfessionKey(current);
    const active = hrProfessions.filter(item => item.is_active !== false || normalizeProfessionKey(item.key) === currentKey);
    const catalogOptions = active.map(item => ({
        value: item.key,
        label: `${item.title}${item.department ? ' · ' + item.department : ''}`
    }));
    const known = new Set(catalogOptions.map(item => item.value));
    if (currentKey && !known.has(currentKey)) {
        catalogOptions.push({ value: currentKey, label: ROLE_LABELS[currentKey] || currentKey });
    }
    return catalogOptions.sort((a, b) => a.label.localeCompare(b.label, 'uk'));
}

function renderProfessionChips(keys = []) {
    const normalized = normalizeProfessionList(keys);
    if (!normalized.length) return '';
    return `<div class="hr-secondary-profession-row">${normalized.map(key => `<span class="hr-secondary-profession-chip">${escapeHtml(professionTitle(key))}</span>`).join('')}</div>`;
}

function staffTeamPrimaryProfessionLabel(staff = {}) {
    const roleKey = normalizeProfessionKey(staff.role_type);
    const roleLabel = ROLE_LABELS[roleKey] || staff.role_type || '';
    return professionTitle(roleKey) || roleLabel || 'Професія не задана';
}

function staffTeamLegacyPositionMeta(staff = {}) {
    const position = String(staff.position || '').trim();
    if (!position) return '';
    return normalizeProfessionKey(staff.role_type) ? '' : position;
}

function staffTrainingReadiness(staff = {}) {
    const readiness = staff.training_readiness || staff.trainingReadiness || {};
    const total = Number(readiness.total || 0);
    const completed = Number(readiness.completed || 0);
    const percent = total ? Math.max(0, Math.min(100, Number(readiness.percent || Math.round((completed / total) * 100)))) : 0;
    return {
        ...readiness,
        total,
        completed,
        percent,
        professions: Array.isArray(readiness.professions) ? readiness.professions : []
    };
}

function trainingTone(percent, total = 0) {
    if (!total) return 'is-muted';
    if (percent >= 85) return 'is-ok';
    if (percent >= 45) return 'is-info';
    return 'is-warn';
}

function onboardingStatusLabel(status) {
    const labels = {
        not_started: 'не стартував',
        in_progress: 'у процесі',
        blocked: 'блок',
        ready: 'готовий',
        completed: 'завершено'
    };
    return labels[status] || labels.in_progress;
}

function staffOnboardingAssignment(staff = {}) {
    const assignment = staff.onboarding_assignment || staff.onboardingAssignment || null;
    if (!assignment || typeof assignment !== 'object') return null;
    const taskSummary = assignment.task_summary || assignment.taskSummary || {};
    const total = Number(assignment.total_items || assignment.totalItems || 0);
    const completed = Number(assignment.completed_items || assignment.completedItems || 0);
    const percent = total > 0
        ? Math.max(0, Math.min(100, Number(assignment.percent || Math.round((completed / total) * 100))))
        : 0;
    return {
        ...assignment,
        responsibleUserId: Number(assignment.responsible_user_id || assignment.responsibleUserId || 0) || null,
        responsibleName: assignment.responsible_name
            || assignment.responsibleName
            || assignment.responsible?.name
            || assignment.responsible_username
            || assignment.responsible?.username
            || null,
        trainingStatus: assignment.training_status || assignment.trainingStatus || assignment.status || 'in_progress',
        total,
        completed,
        percent,
        taskSummary: {
            total: Number(taskSummary.total || assignment.generated_task_count || 0),
            active: Number(taskSummary.active || assignment.active_task_count || 0),
            completed: Number(taskSummary.completed || assignment.completed_task_count || 0)
        }
    };
}

function staffProfessionOnboardingSummary(staff = {}) {
    const summary = staff.profession_onboarding_summary || staff.professionOnboardingSummary || {};
    return {
        activeCount: Math.max(0, Number(summary.active_count ?? summary.activeCount ?? 0) || 0)
    };
}

function activeProfessionOnboardingLabel(count = 0) {
    const value = Math.max(0, Number(count) || 0);
    return `Професійні процеси: ${value} ${value === 1 ? 'активний' : 'активних'}`;
}

function renderStaffOnboardingAssignment(staff = {}) {
    const assignment = staffOnboardingAssignment(staff);
    const hasResponsible = Boolean(assignment?.responsibleUserId);
    const tone = !assignment ? 'is-empty' : (assignment.trainingStatus === 'completed' ? 'is-ok' : (hasResponsible ? 'is-active' : 'is-empty'));
    const status = assignment ? onboardingStatusLabel(assignment.trainingStatus) : 'не призначено';
    const responsible = hasResponsible ? assignment.responsibleName : 'Відповідального немає';
    const percent = assignment ? assignment.percent : 0;
    const taskText = assignment
        ? `${assignment.taskSummary.active}/${assignment.taskSummary.total} активних задач`
        : 'задачі не створені';
    const action = hasResponsible ? 'Змінити' : 'Призначити';
    return `<div class="hr-team-onboarding-assignment ${tone}">
        <div class="hr-team-onboarding-assignment-head">
            <div>
                <b>Корпоративний онбординг</b>
                <span>${escapeHtml(responsible)}</span>
            </div>
            ${canManage ? `<button type="button" onclick="openStaffOnboardingAssignment(${Number(staff.id)})">${action}</button>` : ''}
        </div>
        <div class="hr-team-onboarding-meta">
            <span>${escapeHtml(status)}</span>
            <span>${assignment ? `${assignment.completed}/${assignment.total} чек-лист` : 'чек-лист не стартував'}</span>
            <span>${escapeHtml(taskText)}</span>
        </div>
        <div class="hr-team-onboarding-meter" aria-hidden="true"><i style="width:${percent}%"></i></div>
    </div>`;
}

let staffOnboardingDialogState = null;
let staffOnboardingReturnFocus = null;

function onboardingAdmissionLabel(value) {
    const labels = {
        pending: 'Допуск очікує',
        approved: 'Допущено',
        blocked: 'Допуск заблоковано',
        rejected: 'Допуск відхилено',
        suspended: 'Допуск призупинено'
    };
    return labels[value] || 'Допуск не задано';
}

function onboardingInternshipLabel(value) {
    const labels = {
        none: 'Без стажування',
        planned: 'Стажування заплановано',
        in_progress: 'Стажування триває',
        completed: 'Стажування завершено',
        failed: 'Стажування не пройдено'
    };
    return labels[value] || 'Стажування не задано';
}

function staffProfessionChecklistReadiness(staff = {}, professionKey = '') {
    const entry = staffTrainingReadiness(staff).professions.find(item => normalizeProfessionKey(item.key) === normalizeProfessionKey(professionKey));
    const checklist = Array.isArray(entry?.checklist) ? entry.checklist : [];
    const completed = checklist.filter(item => item.completed_at).length;
    return {
        completed,
        total: checklist.length,
        percent: checklist.length ? Math.round((completed / checklist.length) * 100) : 0
    };
}

function renderStaffOnboardingScopeCard(staff, assignment = null, process = null) {
    const professionKey = normalizeProfessionKey(assignment?.profession_key || process?.profession_key);
    const isGeneral = !professionKey;
    const readiness = isGeneral
        ? {
            completed: Number(process?.completed_items || 0),
            total: Number(process?.total_items || 0),
            percent: Number(process?.percent || 0)
        }
        : (process?.readiness || staffProfessionChecklistReadiness(staff, professionKey));
    const percent = Math.max(0, Math.min(100, Number(readiness.percent || 0)));
    const responsible = process?.responsible_name || process?.responsible_username || 'Відповідального не призначено';
    const tasks = process?.task_summary || {};
    const status = process ? onboardingStatusLabel(process.training_status || process.status) : 'не стартував';
    const completed = process?.status === 'completed' || process?.training_status === 'completed';
    const assignmentActive = isGeneral || assignment?.status === 'active';
    const title = isGeneral
        ? 'Загальний корпоративний онбординг'
        : (assignment?.profession_title || process?.profession_title || professionTitle(professionKey));
    const roleType = isGeneral ? 'Корпоративний setup' : (assignment?.is_primary ? 'Основна професія' : 'Додаткова професія');
    const actionLabel = completed ? 'Процес завершено' : (process ? 'Змінити відповідального' : (isGeneral ? 'Запустити загальний онбординг' : 'Запустити онбординг професії'));
    const canAct = assignmentActive && !completed;
    const professionArg = professionKey ? `'${escapeJsString(professionKey)}'` : "''";
    return `<article class="hr-onboarding-scope-card ${completed ? 'is-completed' : ''} ${process ? 'is-active' : 'is-empty'}">
        <div class="hr-onboarding-scope-head">
            <div>
                <span class="hr-onboarding-scope-kicker">${escapeHtml(roleType)}</span>
                <h4>${escapeHtml(title)}</h4>
            </div>
            <strong>${percent}%</strong>
        </div>
        <div class="hr-onboarding-scope-meta">
            <span>${escapeHtml(status)}</span>
            <span>Відповідальний: ${escapeHtml(responsible)}</span>
            <span>Чекліст: ${Number(readiness.completed || 0)}/${Number(readiness.total || 0)}</span>
            ${isGeneral ? '' : `<span>${escapeHtml(onboardingInternshipLabel(assignment?.internship_status || process?.internship_status))}</span>
                <span>${escapeHtml(onboardingAdmissionLabel(assignment?.admission_status || process?.admission_status))}</span>`}
            <span>Задачі: ${Number(tasks.active || 0)} активні · ${Number(tasks.completed || 0)} виконано</span>
        </div>
        <div class="hr-onboarding-scope-meter" role="progressbar" aria-label="${escapeHtml(title)}: ${percent}%" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent}"><i style="width:${percent}%"></i></div>
        <button type="button" class="btn-secondary hr-onboarding-scope-action" onclick="editStaffOnboardingScope(${Number(staff.id)}, ${professionArg}, this)" ${canAct ? '' : 'disabled aria-disabled="true"'}>
            ${escapeHtml(assignmentActive ? actionLabel : 'Професія неактивна')}
        </button>
    </article>`;
}

function closeStaffOnboardingDialog() {
    document.getElementById('staffOnboardingScopeOverlay')?.remove();
    const focusTarget = staffOnboardingReturnFocus;
    staffOnboardingDialogState = null;
    staffOnboardingReturnFocus = null;
    if (focusTarget?.isConnected && typeof focusTarget.focus === 'function') focusTarget.focus();
}

function renderStaffOnboardingDialog() {
    const root = document.getElementById('staffOnboardingScopeBody');
    const state = staffOnboardingDialogState;
    if (!root || !state) return;
    const { staff, processes, assignments } = state;
    const professionProcesses = new Map((processes.professions || []).map(item => [normalizeProfessionKey(item.profession_key), item]));
    root.setAttribute('aria-busy', 'false');
    root.innerHTML = `
        <div class="hr-onboarding-scope-explainer" role="note">
            Корпоративний setup не впливає на професійний допуск. Кожна професія має власний чекліст, відповідального і статус готовності.
        </div>
        <div class="hr-onboarding-scope-grid">
            ${renderStaffOnboardingScopeCard(staff, null, processes.general || processes.history?.[0] || null)}
            ${assignments.length
                ? assignments.map(assignment => renderStaffOnboardingScopeCard(staff, assignment, professionProcesses.get(normalizeProfessionKey(assignment.profession_key)) || null)).join('')
                : '<div class="hr-onboarding-scope-empty">Працівнику ще не призначено жодної професії.</div>'}
        </div>`;
}

async function refreshStaffOnboardingDialog(staffId) {
    const root = document.getElementById('staffOnboardingScopeBody');
    if (root) {
        root.setAttribute('aria-busy', 'true');
        root.innerHTML = '<div class="hr-onboarding-scope-empty">Завантаження процесів онбордингу...</div>';
    }
    const [processesResponse, assignmentsResponse] = await Promise.all([
        hrFetch(`/staff/${staffId}/onboarding-processes`),
        hrFetch(`/staff/${staffId}/role-assignments`)
    ]);
    if (!processesResponse?.success || !assignmentsResponse?.success) {
        if (root) {
            root.setAttribute('aria-busy', 'false');
            root.innerHTML = `<div class="hr-onboarding-scope-empty is-error" role="alert">${escapeHtml(processesResponse?.error || assignmentsResponse?.error || 'Не вдалося завантажити онбординг.')}<button type="button" class="btn-secondary" onclick="refreshStaffOnboardingDialog(${Number(staffId)})">Повторити</button></div>`;
        }
        return;
    }
    const staff = teamStaff.find(item => Number(item.id) === Number(staffId)) || processesResponse.staff || { id: staffId };
    staffOnboardingDialogState = {
        staff,
        processes: processesResponse.data || { general: null, professions: [] },
        assignments: Array.isArray(assignmentsResponse.data) ? assignmentsResponse.data : []
    };
    renderStaffOnboardingDialog();
}

async function ensureOnboardingResponsibleCandidates(force = false) {
    if (Array.isArray(onboardingResponsibleCandidates) && !force) return onboardingResponsibleCandidates;
    const data = await hrFetch('/onboarding/responsible-candidates');
    onboardingResponsibleCandidates = Array.isArray(data?.data) ? data.data : [];
    return onboardingResponsibleCandidates;
}

function responsibleCandidateOptions(currentId = null) {
    const current = currentId ? String(currentId) : '';
    return (onboardingResponsibleCandidates || []).map(user => ({
        value: String(user.id),
        label: `${user.label || user.name || user.username || `User #${user.id}`}${user.role ? ` · ${ROLE_LABELS[user.role] || user.role}` : ''}`,
        selected: current && String(user.id) === current
    }));
}

window.openStaffOnboardingAssignment = async function(staffId) {
    if (!canManage) {
        showNotification('Призначати відповідальних можуть тільки HR/керівники', 'error');
        return;
    }
    const id = Number(staffId);
    const staff = teamStaff.find(item => Number(item.id) === id) || { id, name: 'Працівник' };
    closeStaffOnboardingDialog();
    staffOnboardingReturnFocus = document.activeElement;
    const overlay = document.createElement('div');
    overlay.id = 'staffOnboardingScopeOverlay';
    overlay.className = 'candidate-detail-overlay';
    overlay.innerHTML = `<div class="candidate-detail-modal hr-onboarding-scope-modal" role="dialog" aria-modal="true" aria-labelledby="staffOnboardingScopeTitle">
        <div class="candidate-detail-head">
            <div>
                <div class="candidate-detail-kicker">Онбординг і професійна готовність</div>
                <h3 id="staffOnboardingScopeTitle">${escapeHtml(staff.name || 'Працівник')}</h3>
                <p>Незалежні процеси без спільного агрегованого відсотка.</p>
            </div>
            <button type="button" class="candidate-detail-close" onclick="closeStaffOnboardingDialog()" aria-label="Закрити">×</button>
        </div>
        <div id="staffOnboardingScopeBody" class="hr-onboarding-scope-body" aria-live="polite" aria-busy="true">
            <div class="hr-onboarding-scope-empty">Завантаження процесів онбордингу...</div>
        </div>
    </div>`;
    document.body.appendChild(overlay);
    overlay.addEventListener('click', event => { if (event.target === overlay) closeStaffOnboardingDialog(); });
    overlay.addEventListener('keydown', event => { if (event.key === 'Escape') closeStaffOnboardingDialog(); });
    overlay.querySelector('.candidate-detail-close')?.focus();
    try {
        await Promise.all([ensureOnboardingResponsibleCandidates(true), refreshStaffOnboardingDialog(id)]);
    } catch (error) {
        console.error('Onboarding dialog error', error);
        const root = document.getElementById('staffOnboardingScopeBody');
        if (root) root.innerHTML = `<div class="hr-onboarding-scope-empty is-error" role="alert">${escapeHtml(error.message || 'Не вдалося завантажити онбординг.')}</div>`;
    }
};

window.closeStaffOnboardingDialog = closeStaffOnboardingDialog;
window.refreshStaffOnboardingDialog = refreshStaffOnboardingDialog;

window.editStaffOnboardingScope = async function(staffId, professionKey = '', button = null) {
    const state = staffOnboardingDialogState;
    const key = normalizeProfessionKey(professionKey);
    const process = key
        ? state?.processes?.professions?.find(item => normalizeProfessionKey(item.profession_key) === key)
        : (state?.processes?.general || state?.processes?.history?.[0] || null);
    if (button) button.disabled = true;
    try {
        const candidates = await ensureOnboardingResponsibleCandidates();
        if (!candidates.length) {
            showNotification('Немає активних користувачів, яких можна призначити відповідальними', 'warning');
            return;
        }
        const currentId = process?.responsible_user_id || candidates[0]?.id;
        const result = await formModal(`${process ? 'Відповідальний' : 'Запустити онбординг'} · ${key ? professionTitle(key) : 'корпоративний setup'}`, [{
            key: 'responsibleUserId',
            label: 'Відповідальний',
            type: 'select',
            options: responsibleCandidateOptions(currentId),
            defaultValue: String(currentId || ''),
            required: true,
            hint: 'Повторне збереження синхронізує той самий процес і не створить дубль.'
        }], { icon: key ? '🎓' : '🎯', okText: process ? 'Зберегти' : 'Запустити', type: 'info' });
        if (!result) return;
        const payload = { responsible_user_id: Number(result.responsibleUserId) };
        if (key) payload.profession_key = key;
        const saved = await hrFetch(`/staff/${Number(staffId)}/onboarding-assignment`, 'PUT', payload);
        if (!saved?.success) {
            showNotification(saved?.error || 'Не вдалося запустити онбординг', 'error');
            return;
        }
        showNotification(saved.action === 'reassigned' ? 'Відповідального оновлено' : 'Онбординг синхронізовано', 'success');
        await Promise.all([loadTeam(), refreshStaffOnboardingDialog(staffId)]);
        if (document.getElementById('onboardingList')) loadOnboarding();
    } catch (error) {
        console.error('Scoped onboarding assignment error', error);
        showNotification(error.message || 'Не вдалося оновити онбординг', 'error');
    } finally {
        if (button?.isConnected) button.disabled = false;
    }
};

function selectedSecondaryProfessionKeys() {
    const picker = document.getElementById('editSecondaryProfessionPicker');
    if (!picker) return [];
    try {
        return normalizeProfessionList(JSON.parse(picker.dataset.selected || '[]'), [document.getElementById('editRoleType')?.value]);
    } catch {
        return [];
    }
}

function setSelectedSecondaryProfessionKeys(keys = [], primaryRole = '') {
    const picker = document.getElementById('editSecondaryProfessionPicker');
    if (!picker) return;
    picker.dataset.selected = JSON.stringify(normalizeProfessionList(keys, [primaryRole]));
}

function staffMoveTargetOptions(currentBucket = 'workers') {
    return HR_TEAM_MOVE_TARGETS
        .filter(target => target.id !== currentBucket && target.id !== 'dismissed' && canSeeHrTeamBucket(target.id))
        .map(target => ({
            value: target.id,
            label: `${target.label} - ${target.hint}`
        }));
}

function preferredWorkerRoleForStaff(staff = {}) {
    const currentPrimary = normalizeProfessionKey(staff.role_type);
    if (currentPrimary && currentPrimary !== 'intern') return currentPrimary;
    const secondary = staffSecondaryProfessions(staff).filter(key => key !== 'intern');
    return secondary[0] || 'animator';
}

function professionSelectOptionsForStaffMove(staff = {}) {
    const preferred = preferredWorkerRoleForStaff(staff);
    return professionOptionsFromCatalog(preferred)
        .filter(option => normalizeProfessionKey(option.value) !== 'intern')
        .map(option => ({ ...option, selected: normalizeProfessionKey(option.value) === preferred }));
}

function formatDate(d) {
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

function getMonday(d) {
    const date = new Date(d);
    const day = date.getDay();
    const diff = date.getDate() - day + (day === 0 ? -6 : 1);
    date.setDate(diff);
    date.setHours(0, 0, 0, 0);
    return date;
}

function getWeekDates(monday) {
    const dates = [];
    for (let i = 0; i < 7; i++) {
        const d = new Date(monday);
        d.setDate(monday.getDate() + i);
        dates.push(d);
    }
    return dates;
}

function getMonthDates(year, month) {
    const dates = [];
    const d = new Date(year, month, 1);
    while (d.getMonth() === month) {
        dates.push(new Date(d));
        d.setDate(d.getDate() + 1);
    }
    return dates;
}

function todayStr() { return formatDate(new Date()); }

function fmtTime(t) {
    if (!t) return '';
    return String(t).substring(0, 5);
}

function fmtTimeFromISO(iso) {
    if (!iso) return '';
    const d = new Date(iso);
    return d.toLocaleTimeString('uk-UA', { hour: '2-digit', minute: '2-digit', timeZone: 'Europe/Kyiv' });
}

function fmtMinutes(min) {
    if (!min || min <= 0) return '';
    const h = Math.floor(min / 60);
    const m = min % 60;
    if (h === 0) return `${m}хв`;
    return m > 0 ? `${h}г ${m}хв` : `${h}г`;
}

function fmtMoney(n) {
    return new Intl.NumberFormat('uk-UA').format(n) + ' ₴';
}

function formatResumeFileSize(bytes) {
    const value = Number(bytes) || 0;
    if (value < 1024) return `${value} Б`;
    if (value < 1024 * 1024) return `${Math.round(value / 1024)} КБ`;
    return `${(value / 1024 / 1024).toFixed(1)} МБ`;
}

async function hrFetch(path, options = {}, legacyBody = undefined) {
    let allowForbiddenResponse = false;
    if (options && typeof options === 'object' && !(options instanceof String)) {
        allowForbiddenResponse = options.allowForbiddenResponse === true;
        if (Object.prototype.hasOwnProperty.call(options, 'allowForbiddenResponse')) {
            const { allowForbiddenResponse: _allowForbiddenResponse, ...cleanOptions } = options;
            options = cleanOptions;
        }
    }
    const isFormData = typeof FormData !== 'undefined' && options?.body instanceof FormData;
    const headers = isFormData ? {} : { 'Content-Type': 'application/json' };
    if (typeof options === 'string') {
        options = {
            method: options,
            body: legacyBody !== undefined ? JSON.stringify(legacyBody) : undefined
        };
    } else if (options && options.body && typeof options.body !== 'string' && !(typeof FormData !== 'undefined' && options.body instanceof FormData)) {
        options = { ...options, body: JSON.stringify(options.body) };
    }
    const request = { ...options, headers: { ...headers, ...(options.headers || {}) } };
    const resp = typeof apiFetchWithAuthRetry === 'function'
        ? await apiFetchWithAuthRetry(`/api/hr${path}`, request)
        : await fetch(`/api/hr${path}`, request);
    if (!resp) return null;
    if (resp.status === 401) {
        localStorage.removeItem('pzp_token');
        location.href = '/';
        return null;
    }
    const data = await resp.json().catch(() => ({}));
    if (!resp.ok) return { ...data, success: false, status: resp.status, error: data.error || `HTTP ${resp.status}` };
    return data;
}

async function crmApiFetch(path, options = {}) {
    const headers = { 'Content-Type': 'application/json' };
    if (options && options.body && typeof options.body !== 'string') {
        options = { ...options, body: JSON.stringify(options.body) };
    }
    const request = { ...options, headers: { ...headers, ...(options.headers || {}) } };
    const resp = typeof apiFetchWithAuthRetry === 'function'
        ? await apiFetchWithAuthRetry(path, request)
        : await fetch(path, request);
    if (!resp) return null;
    if (resp.status === 401) {
        localStorage.removeItem('pzp_token');
        location.href = '/';
        return null;
    }
    const data = await resp.json().catch(() => ({}));
    if (!resp.ok) return { ...data, success: false, status: resp.status, error: data.error || `HTTP ${resp.status}` };
    return data;
}

async function confirmHrAction(message, options = {}) {
    if (typeof confirmModal === 'function') {
        return confirmModal(message, {
            type: options.type || 'warning',
            okText: options.okText || 'Підтвердити',
            cancelText: options.cancelText || 'Скасувати'
        });
    }
    showNotification('Підтвердження дії недоступне. Оновіть сторінку і повторіть дію.', 'error');
    return false;
}

// ==========================================
// HR ATTENDANCE DOCUMENTS V27
// ==========================================

function hrPrintTemplateId() {
    return document.querySelector('input[name="hrPrintTemplate"]:checked')?.value || 'arrival_inout';
}

function hrPrintSelectedCategories() {
    return HR_PRINT_CATEGORIES.filter(item => hrPrintDocumentsState.selectedCategoryIds.has(item.id));
}

function hrPrintFocusableElements() {
    const modal = document.querySelector('#hrPrintDocumentsModal .hr-print-documents-modal');
    if (!modal) return [];
    return Array.from(modal.querySelectorAll(
        'button:not([disabled]), input:not([disabled]):not([type="hidden"]), select:not([disabled]), textarea:not([disabled]), iframe:not(.hidden), [tabindex]:not([tabindex="-1"])'
    )).filter(element => !element.closest('.hidden') && element.getClientRects().length > 0);
}

function setHrPrintStatus(message = '', tone = '') {
    const status = document.getElementById('hrPrintDocumentsStatus');
    if (!status) return;
    status.textContent = message;
    status.dataset.tone = tone;
}

function releaseHrPrintPreview({ clearFrame = true } = {}) {
    const frame = document.getElementById('hrPrintPreviewFrame');
    if (frame && clearFrame) {
        frame.classList.add('hidden');
        frame.removeAttribute('src');
    }
    if (hrPrintDocumentsState.previewUrl) URL.revokeObjectURL(hrPrintDocumentsState.previewUrl);
    hrPrintDocumentsState.previewUrl = '';
    hrPrintDocumentsState.previewBlob = null;
    hrPrintDocumentsState.previewFileName = '';
    document.getElementById('hrPrintDownloadButton')?.setAttribute('disabled', '');
    document.getElementById('hrPrintPrintButton')?.setAttribute('disabled', '');
    document.getElementById('hrPrintOpenButton')?.setAttribute('disabled', '');
}

function isHrPrintPreviewRequestCurrent(requestSeq, objectUrl = '') {
    return hrPrintDocumentsState.open
        && requestSeq === hrPrintDocumentsState.requestSeq
        && (!objectUrl || objectUrl === hrPrintDocumentsState.previewUrl);
}

function waitForHrPrintPreviewFrame(frame, objectUrl, requestSeq) {
    if (navigator.pdfViewerEnabled === false) {
        frame.classList.add('hidden');
        frame.removeAttribute('src');
        return Promise.resolve({ ready: isHrPrintPreviewRequestCurrent(requestSeq, objectUrl), embedded: false });
    }
    return new Promise(resolve => {
        let settled = false;
        let timeoutId;
        let staleCheckId;
        const finish = loaded => {
            if (settled) return;
            settled = true;
            clearTimeout(timeoutId);
            clearInterval(staleCheckId);
            frame.removeEventListener('load', handleLoad);
            resolve({
                ready: Boolean(loaded
                && frame.getAttribute('src') === objectUrl
                && isHrPrintPreviewRequestCurrent(requestSeq, objectUrl)),
                embedded: true
            });
        };
        const handleLoad = () => finish(true);
        timeoutId = setTimeout(() => finish(false), 20000);
        staleCheckId = setInterval(() => {
            if (!isHrPrintPreviewRequestCurrent(requestSeq, objectUrl)) finish(false);
        }, 50);
        frame.addEventListener('load', handleLoad, { once: true });
        frame.classList.remove('hidden');
        frame.src = objectUrl;
    });
}

function scrollHrPrintPreviewIntoView() {
    if (!window.matchMedia?.('(max-width: 980px)').matches) return;
    const body = document.querySelector('.hr-print-documents-body');
    const panel = document.querySelector('.hr-print-preview-panel');
    if (!body || !panel) return;
    const bodyRect = body.getBoundingClientRect();
    const panelRect = panel.getBoundingClientRect();
    const top = body.scrollTop + panelRect.top - bodyRect.top;
    const reducedMotion = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
    body.scrollTo({ top: Math.max(0, top), behavior: reducedMotion ? 'auto' : 'smooth' });
}

async function showHrPrintPreview({ blob, filename, requestSeq, badgeText, statusMessage }) {
    if (!isHrPrintPreviewRequestCurrent(requestSeq)) return false;
    if (!(blob instanceof Blob) || (blob.type && !blob.type.includes('pdf'))) {
        throw new Error('Сервер повернув не PDF-документ.');
    }

    releaseHrPrintPreview({ clearFrame: false });
    if (!isHrPrintPreviewRequestCurrent(requestSeq)) return false;

    const objectUrl = URL.createObjectURL(blob);
    hrPrintDocumentsState.previewBlob = blob;
    hrPrintDocumentsState.previewUrl = objectUrl;
    hrPrintDocumentsState.previewFileName = filename || '';

    const frame = document.getElementById('hrPrintPreviewFrame');
    if (!frame) {
        releaseHrPrintPreview();
        throw new Error('Область попереднього перегляду недоступна.');
    }

    const preview = await waitForHrPrintPreviewFrame(frame, objectUrl, requestSeq);
    if (!preview.ready) {
        if (isHrPrintPreviewRequestCurrent(requestSeq, objectUrl)) {
            releaseHrPrintPreview();
            throw new Error('PDF отримано, але вбудований перегляд не завантажився.');
        }
        return false;
    }

    const previewState = document.getElementById('hrPrintPreviewState');
    if (preview.embedded) {
        previewState?.classList.add('hidden');
    } else if (previewState) {
        previewState.textContent = 'Вбудований перегляд PDF недоступний у цьому браузері. Відкрийте документ в окремій вкладці.';
        previewState.classList.remove('hidden');
    }
    previewState?.classList.remove('is-loading');
    document.getElementById('hrPrintDownloadButton')?.removeAttribute('disabled');
    document.getElementById('hrPrintPrintButton')?.removeAttribute('disabled');
    document.getElementById('hrPrintOpenButton')?.removeAttribute('disabled');
    const badge = document.getElementById('hrPrintPreviewBadge');
    if (badge) {
        badge.textContent = badgeText;
        badge.className = 'hr-print-preview-badge is-ready';
    }
    setHrPrintStatus(statusMessage, 'success');
    scrollHrPrintPreviewIntoView();
    return true;
}

function invalidateHrPrintPreview(message = 'Налаштування змінено. Сформуйте preview ще раз.') {
    hrPrintDocumentsState.requestSeq += 1;
    releaseHrPrintPreview();
    const state = document.getElementById('hrPrintPreviewState');
    const badge = document.getElementById('hrPrintPreviewBadge');
    if (state) {
        state.textContent = message;
        state.classList.remove('hidden', 'is-loading');
    }
    if (badge) {
        badge.textContent = 'Потрібне оновлення';
        badge.className = 'hr-print-preview-badge is-stale';
    }
}

function hrPrintEstimatedEmployeeIds() {
    const ids = new Set();
    for (const category of hrPrintSelectedCategories()) {
        for (const professionKey of category.professionKeys) {
            const profession = hrProfessions.find(item => normalizeProfessionKey(item.key) === professionKey);
            for (const person of profession?.people || []) {
                const id = Number(person.id);
                if (person.isActive !== false && Number.isFinite(id)) ids.add(id);
            }
        }
    }
    return ids;
}

function syncHrPrintEmployeeCount() {
    const count = document.getElementById('hrPrintEmployeeCount');
    if (!count) return;
    const categoryCount = hrPrintDocumentsState.selectedCategoryIds.size;
    if (professionCatalogLoadState === 'loading') {
        count.textContent = `${categoryCount} кат. · завантажуємо актуальний склад…`;
        return;
    }
    if (professionCatalogLoadState === 'error') {
        count.textContent = `${categoryCount} кат. · склад уточнить сервер під час preview`;
        return;
    }
    const employeeCount = hrPrintEstimatedEmployeeIds().size;
    count.textContent = `${categoryCount} кат. · попередньо ${employeeCount} унік. працівн.`;
}

function syncHrPrintSelectAllButton() {
    const button = document.getElementById('hrPrintSelectAll');
    if (!button) return;
    const allSelected = hrPrintDocumentsState.selectedCategoryIds.size === HR_PRINT_CATEGORIES.length;
    button.textContent = allSelected ? 'Скасувати вибір' : 'Вибрати всі';
    button.setAttribute('aria-pressed', allSelected ? 'true' : 'false');
}

function renderHrPrintProfessionList() {
    const list = document.getElementById('hrPrintProfessionList');
    const empty = document.getElementById('hrPrintProfessionEmpty');
    if (!list) return;
    const query = String(hrPrintDocumentsState.professionQuery || '').trim().toLocaleLowerCase('uk-UA');
    const visible = HR_PRINT_CATEGORIES.filter(item => !query || item.label.toLocaleLowerCase('uk-UA').includes(query));
    list.innerHTML = visible.map(item => `
        <label class="hr-print-profession-option">
            <input type="checkbox" value="${escapeHtml(item.id)}" data-hr-print-category${hrPrintDocumentsState.selectedCategoryIds.has(item.id) ? ' checked' : ''}>
            <span>${escapeHtml(item.label)}</span>
        </label>
    `).join('');
    empty?.classList.toggle('hidden', visible.length > 0);
    syncHrPrintSelectAllButton();
    syncHrPrintEmployeeCount();
}

function renderHrPrintFontControls() {
    const root = document.getElementById('hrPrintFontControls');
    if (!root) return;
    const fields = HR_PRINT_FONT_FIELDS[hrPrintTemplateId()] || HR_PRINT_FONT_FIELDS.arrival_inout;
    root.innerHTML = fields.map(field => `
        <label class="hr-print-font-control">
            <span>${escapeHtml(field.label)}</span>
            <span class="hr-print-font-control-row">
                <input type="range" min="${field.min}" max="${field.max}" step="0.5" value="${field.value}" data-hr-print-font="${escapeHtml(field.key)}" data-default-value="${field.value}">
                <output class="hr-print-font-value" data-hr-print-font-output="${escapeHtml(field.key)}">${field.value} pt</output>
            </span>
        </label>
    `).join('');
    syncHrPrintPresetWarning();
}

function hrPrintFontPreset() {
    const values = {};
    document.querySelectorAll('[data-hr-print-font]').forEach(input => {
        values[input.dataset.hrPrintFont] = Number(input.value);
    });
    return values;
}

function syncHrPrintFontOutput(input) {
    if (!input?.dataset.hrPrintFont) return;
    const output = document.querySelector(`[data-hr-print-font-output="${input.dataset.hrPrintFont}"]`);
    if (output) output.textContent = `${Number(input.value)} pt`;
}

function syncHrPrintPresetWarning() {
    const customizedFonts = Array.from(document.querySelectorAll('[data-hr-print-font]'))
        .some(input => Number(input.value) !== Number(input.dataset.defaultValue));
    const customizedText = Boolean(
        document.getElementById('hrPrintCustomTitle')?.value.trim()
        || document.getElementById('hrPrintCustomFooter')?.value.trim()
        || hrPrintDocumentsState.editingAutomationMonthlyInstruction
    );
    document.getElementById('hrPrintPresetWarning')?.classList.toggle('hidden', !(customizedFonts || customizedText));
}

function syncHrPrintTemplateFields() {
    const isDaily = hrPrintTemplateId() === 'arrival_inout';
    const dateField = document.getElementById('hrPrintDateField');
    const monthField = document.getElementById('hrPrintMonthField');
    const dailyModeField = document.getElementById('hrPrintDailyModeField');
    dateField?.classList.toggle('hidden', !isDaily);
    monthField?.classList.toggle('hidden', isDaily);
    dailyModeField?.classList.toggle('hidden', !isDaily);
    const dateInput = document.getElementById('hrPrintDocumentDate');
    const monthInput = document.getElementById('hrPrintDocumentMonth');
    if (dateInput) dateInput.required = isDaily;
    if (monthInput) monthInput.required = !isDaily;
    document.getElementById('hrPrintAutomationWeekdays')?.classList.toggle('hidden', !isDaily);
    const scheduleNote = document.getElementById('hrPrintAutomationScheduleNote');
    if (scheduleNote) {
        scheduleNote.textContent = isDaily
            ? 'Після перезапуску CRM ранковий документ буде створено лише в межах 120 хвилин, не ввечері.'
            : 'Місячний табель формується першого дня місяця у вибраний час.';
    }
    renderHrPrintFontControls();
}

function resetHrPrintPreset() {
    document.getElementById('hrPrintCustomTitle').value = '';
    document.getElementById('hrPrintCustomFooter').value = '';
    hrPrintDocumentsState.editingAutomationMonthlyInstruction = '';
    renderHrPrintFontControls();
    invalidateHrPrintPreview('Еталон v27 відновлено. Сформуйте preview.');
    setHrPrintStatus('Налаштування шрифтів і текстів повернуто до еталону v27.', 'success');
}

function hrPrintRequestPayload() {
    const templateId = hrPrintTemplateId();
    const categoryIds = hrPrintSelectedCategories().map(item => item.id);
    if (!categoryIds.length) throw new Error('Оберіть хоча б одну категорію працівників.');
    const date = document.getElementById('hrPrintDocumentDate')?.value;
    const month = document.getElementById('hrPrintDocumentMonth')?.value;
    if (templateId === 'arrival_inout' && !date) throw new Error('Оберіть дату документа.');
    if (templateId === 'month_grid' && !month) throw new Error('Оберіть місяць документа.');
    const title = document.getElementById('hrPrintCustomTitle')?.value.trim() || '';
    const footerNote = document.getElementById('hrPrintCustomFooter')?.value.trim() || '';
    const texts = {};
    if (title) texts.title = title;
    if (footerNote) texts.footerNote = footerNote;
    return {
        templateId,
        ...(templateId === 'arrival_inout' ? { documentDate: date } : { month }),
        categoryIds,
        dailyMode: templateId === 'arrival_inout'
            ? (document.getElementById('hrPrintDailyMode')?.value || 'manual_blank')
            : 'manual_blank',
        rosterMode: 'all_eligible',
        locationShift: document.getElementById('hrPrintLocationShift')?.value.trim() || '',
        markedBy: document.getElementById('hrPrintMarkedBy')?.value.trim() || '',
        texts,
        fontPreset: hrPrintFontPreset()
    };
}

function hrPrintResponseError(response) {
    return response.text().then(text => {
        try {
            const body = text ? JSON.parse(text) : {};
            return body.error || body.message || `HTTP ${response.status}`;
        } catch {
            return text || `HTTP ${response.status}`;
        }
    });
}

async function hrPrintFetchJson(path, options = {}) {
    const request = {
        ...options,
        headers: { Accept: 'application/json', ...(options.headers || {}) }
    };
    const response = typeof apiFetchWithAuthRetry === 'function'
        ? await apiFetchWithAuthRetry(path, request)
        : await fetch(path, request);
    if (!response) throw new Error('Сервер не повернув відповідь.');
    if (!response.ok) throw new Error(await hrPrintResponseError(response));
    return response.json();
}

function hrPrintJobStatusLabel(status) {
    return ({
        building: 'Формується', queued: 'PDF готовий', failed: 'Помилка', cancelled: 'Скасовано',
        expired: 'Протерміновано', claimed: 'Отримано агентом', printing: 'Друкується',
        completed: 'Надруковано', unknown_outcome: 'Невідомий результат'
    })[status] || status || 'Невідомо';
}

function hrPrintFormatDateTime(value) {
    if (!value) return '—';
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) return String(value);
    return new Intl.DateTimeFormat('uk-UA', {
        timeZone: 'Europe/Kyiv', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit'
    }).format(date);
}

function renderHrPrintOperations() {
    const automationsRoot = document.getElementById('hrPrintAutomationList');
    const jobsRoot = document.getElementById('hrPrintJobList');
    if (automationsRoot) {
        automationsRoot.innerHTML = hrPrintDocumentsState.automations.length
            ? hrPrintDocumentsState.automations.map(item => `
                <article class="hr-print-operation-item">
                    <div class="hr-print-operation-item-head">
                        <strong>${escapeHtml(item.name)}</strong>
                        <span class="hr-print-operation-status${item.enabled ? ' is-enabled' : ''}">${item.enabled ? 'Увімкнено' : 'Вимкнено'}</span>
                    </div>
                    <div class="hr-print-operation-meta">${item.documentType === 'arrival_inout' ? 'Лист приходу/уходу' : 'Місячний табель'} · ${escapeHtml(item.localTime || '08:00')} · ${item.categoryIds.length} кат.</div>
                    <div class="hr-print-operation-actions">
                        ${canManage ? `<button type="button" class="btn-page-toolbar" data-hr-print-operation="edit-automation" data-id="${item.id}">Редагувати</button>
                        <button type="button" class="btn-page-primary" data-hr-print-operation="run-automation" data-id="${item.id}">Сформувати зараз</button>
                        ${item.enabled ? `<button type="button" class="btn-page-toolbar" data-hr-print-operation="disable-automation" data-id="${item.id}">Вимкнути</button>` : ''}` : ''}
                    </div>
                </article>
            `).join('')
            : '<div class="hr-print-operation-item">Збережених автоматизацій ще немає.</div>';
    }
    if (jobsRoot) {
        jobsRoot.innerHTML = hrPrintDocumentsState.jobs.length
            ? hrPrintDocumentsState.jobs.map(job => `
                <article class="hr-print-operation-item">
                    <div class="hr-print-operation-item-head">
                        <strong>${escapeHtml(job.automationName || `PDF #${job.id}`)}</strong>
                        <span class="hr-print-operation-status is-${escapeHtml(job.status)}">${escapeHtml(hrPrintJobStatusLabel(job.status))}</span>
                    </div>
                    <div class="hr-print-operation-meta">${escapeHtml(String(job.localDate || ''))} · ${hrPrintFormatDateTime(job.createdAt)}${job.errorMessage ? `<br>${escapeHtml(job.errorMessage)}` : ''}</div>
                    <div class="hr-print-operation-actions">
                        ${job.pdfByteLength && job.status !== 'expired' ? `<button type="button" class="btn-page-primary" data-hr-print-operation="preview-job" data-id="${job.id}" data-filename="${escapeHtml(job.filename || '')}">Відкрити PDF</button>` : ''}
                        ${canManage && ['failed', 'cancelled', 'queued', 'expired'].includes(job.status) ? `<button type="button" class="btn-page-toolbar" data-hr-print-operation="requeue-job" data-id="${job.id}">Повторити</button>` : ''}
                        ${canManage && ['building', 'queued', 'failed'].includes(job.status) ? `<button type="button" class="btn-page-toolbar" data-hr-print-operation="cancel-job" data-id="${job.id}">Скасувати</button>` : ''}
                    </div>
                </article>
            `).join('')
            : '<div class="hr-print-operation-item">Черга PDF порожня.</div>';
    }
    if (!canExportHrReports()) {
        jobsRoot?.querySelectorAll('[data-hr-print-operation="preview-job"]').forEach(button => button.remove());
    }
}

async function loadHrPrintOperations({ silent = false } = {}) {
    if (hrPrintDocumentsState.operationsLoading) return;
    hrPrintDocumentsState.operationsLoading = true;
    if (!silent) {
        const automationRoot = document.getElementById('hrPrintAutomationList');
        const jobsRoot = document.getElementById('hrPrintJobList');
        if (automationRoot) automationRoot.textContent = 'Завантажуємо…';
        if (jobsRoot) jobsRoot.textContent = 'Завантажуємо…';
    }
    try {
        const [automationResponse, jobsResponse] = await Promise.all([
            hrPrintFetchJson('/api/hr/attendance-document-automations'),
            hrPrintFetchJson('/api/hr/attendance-document-jobs?limit=30')
        ]);
        hrPrintDocumentsState.automations = automationResponse.automations || [];
        hrPrintDocumentsState.jobs = jobsResponse.jobs || [];
        renderHrPrintOperations();
    } catch (error) {
        setHrPrintStatus(error.message || 'Не вдалося завантажити автоматизації.', 'error');
        const root = document.getElementById('hrPrintAutomationList');
        if (root) root.textContent = error.message || 'Помилка завантаження.';
    } finally {
        hrPrintDocumentsState.operationsLoading = false;
    }
}

function hrPrintAutomationPayload() {
    const request = hrPrintRequestPayload();
    const texts = { ...request.texts };
    if (hrPrintDocumentsState.editingAutomationMonthlyInstruction) {
        texts.monthlyInstruction = hrPrintDocumentsState.editingAutomationMonthlyInstruction;
    }
    const weekdays = Array.from(document.querySelectorAll('#hrPrintAutomationWeekdays input:checked')).map(input => Number(input.value));
    const name = document.getElementById('hrPrintAutomationName')?.value.trim() || '';
    if (!name) throw new Error('Вкажіть назву автоматизації.');
    if (request.templateId === 'arrival_inout' && !weekdays.length) throw new Error('Оберіть хоча б один день формування.');
    return {
        name,
        documentType: request.templateId,
        categoryIds: request.categoryIds,
        weekdays,
        localTime: document.getElementById('hrPrintAutomationTime')?.value || '08:00',
        copies: Number(document.getElementById('hrPrintAutomationCopies')?.value || 1),
        artifactTtlHours: Number(document.getElementById('hrPrintAutomationTtl')?.value || 168),
        catchUpMinutes: 120,
        enabled: document.getElementById('hrPrintAutomationEnabled')?.checked === true,
        settings: {
            dailyMode: request.dailyMode,
            rosterMode: request.rosterMode,
            locationShift: request.locationShift,
            markedBy: request.markedBy,
            texts,
            fontPreset: request.fontPreset
        }
    };
}

function resetHrPrintAutomationEditor() {
    hrPrintDocumentsState.editingAutomationId = null;
    hrPrintDocumentsState.editingAutomationMonthlyInstruction = '';
    const name = document.getElementById('hrPrintAutomationName');
    const enabled = document.getElementById('hrPrintAutomationEnabled');
    const save = document.getElementById('hrPrintAutomationSave');
    if (name) name.value = '';
    if (enabled) enabled.checked = false;
    if (save) save.textContent = 'Зберегти автоматизацію';
    document.getElementById('hrPrintAutomationCancelEdit')?.classList.add('hidden');
}

function editHrPrintAutomation(id) {
    const item = hrPrintDocumentsState.automations.find(entry => Number(entry.id) === Number(id));
    if (!item) return;
    hrPrintDocumentsState.editingAutomationId = item.id;
    const radio = document.querySelector(`input[name="hrPrintTemplate"][value="${item.documentType}"]`);
    if (radio) radio.checked = true;
    hrPrintDocumentsState.selectedCategoryIds = new Set(item.categoryIds || []);
    document.getElementById('hrPrintAutomationName').value = item.name || '';
    document.getElementById('hrPrintAutomationTime').value = item.localTime || '08:00';
    document.getElementById('hrPrintAutomationCopies').value = item.copies || 1;
    document.getElementById('hrPrintAutomationTtl').value = item.artifactTtlHours || 168;
    document.getElementById('hrPrintAutomationEnabled').checked = item.enabled === true;
    document.querySelectorAll('#hrPrintAutomationWeekdays input').forEach(input => {
        input.checked = (item.weekdays || []).includes(Number(input.value));
    });
    const settings = item.settings || {};
    const monthlyInstruction = settings.texts?.monthlyInstruction || '';
    hrPrintDocumentsState.editingAutomationMonthlyInstruction = monthlyInstruction
        && !isHrPrintDefaultText(item.documentType, 'monthlyInstruction', monthlyInstruction)
        ? monthlyInstruction
        : '';
    document.getElementById('hrPrintDailyMode').value = settings.dailyMode || 'manual_blank';
    document.getElementById('hrPrintLocationShift').value = settings.locationShift || '';
    document.getElementById('hrPrintMarkedBy').value = settings.markedBy || '';
    document.getElementById('hrPrintCustomTitle').value = settings.texts?.title && !isHrPrintDefaultText(item.documentType, 'title', settings.texts.title)
        ? settings.texts.title
        : '';
    document.getElementById('hrPrintCustomFooter').value = settings.texts?.footerNote && !isHrPrintDefaultText(item.documentType, 'footerNote', settings.texts.footerNote)
        ? settings.texts.footerNote
        : '';
    renderHrPrintProfessionList();
    syncHrPrintTemplateFields();
    document.querySelectorAll('[data-hr-print-font]').forEach(input => {
        const value = Number(settings.fontPreset?.[input.dataset.hrPrintFont]);
        if (Number.isFinite(value)) input.value = value;
        syncHrPrintFontOutput(input);
    });
    syncHrPrintPresetWarning();
    document.getElementById('hrPrintAutomationSave').textContent = 'Оновити автоматизацію';
    document.getElementById('hrPrintAutomationCancelEdit')?.classList.remove('hidden');
    invalidateHrPrintPreview('Налаштування автоматизації завантажено. Сформуйте preview для перевірки.');
    document.getElementById('hrPrintAutomationName')?.focus();
}

async function saveHrPrintAutomation() {
    let payload;
    try {
        payload = hrPrintAutomationPayload();
    } catch (error) {
        setHrPrintStatus(error.message, 'error');
        return;
    }
    const button = document.getElementById('hrPrintAutomationSave');
    if (button) { button.disabled = true; button.textContent = 'Зберігаємо…'; }
    try {
        const id = hrPrintDocumentsState.editingAutomationId;
        await hrPrintFetchJson(id
            ? `/api/hr/attendance-document-automations/${id}`
            : '/api/hr/attendance-document-automations', {
            method: id ? 'PATCH' : 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });
        resetHrPrintAutomationEditor();
        await loadHrPrintOperations({ silent: true });
        setHrPrintStatus(id ? 'Автоматизацію оновлено.' : 'Автоматизацію збережено.', 'success');
    } catch (error) {
        setHrPrintStatus(error.message || 'Не вдалося зберегти автоматизацію.', 'error');
    } finally {
        if (button) { button.disabled = false; button.textContent = hrPrintDocumentsState.editingAutomationId ? 'Оновити автоматизацію' : 'Зберегти автоматизацію'; }
    }
}

async function previewHrPrintJob(id, filename = '') {
    if (!canExportHrReports()) {
        showNotification('HR export permission required', 'error');
        return;
    }
    invalidateHrPrintPreview('Завантажуємо збережений PDF із черги…');
    const requestSeq = hrPrintDocumentsState.requestSeq;
    const state = document.getElementById('hrPrintPreviewState');
    const badge = document.getElementById('hrPrintPreviewBadge');
    state?.classList.add('is-loading');
    if (badge) {
        badge.textContent = 'Завантажується';
        badge.className = 'hr-print-preview-badge';
    }
    try {
        const response = typeof apiFetchWithAuthRetry === 'function'
            ? await apiFetchWithAuthRetry(`/api/hr/attendance-document-jobs/${id}/pdf`, { headers: { Accept: 'application/pdf' } })
            : await fetch(`/api/hr/attendance-document-jobs/${id}/pdf`, { headers: { Accept: 'application/pdf' } });
        if (!response?.ok) throw new Error(response ? await hrPrintResponseError(response) : 'Сервер не повернув відповідь.');
        const blob = await response.blob();
        if (!isHrPrintPreviewRequestCurrent(requestSeq)) return;
        await showHrPrintPreview({
            blob,
            filename: filename || `event-genix-hr-job-${id}.pdf`,
            requestSeq,
            badgeText: 'З черги',
            statusMessage: 'Відкрито той самий незмінний PDF, який збережений у черзі.'
        });
    } catch (error) {
        if (!isHrPrintPreviewRequestCurrent(requestSeq)) return;
        releaseHrPrintPreview();
        if (state) {
            state.textContent = error.message || 'Не вдалося відкрити PDF.';
            state.classList.remove('hidden', 'is-loading');
        }
        if (badge) {
            badge.textContent = 'Помилка';
            badge.className = 'hr-print-preview-badge is-stale';
        }
        setHrPrintStatus(error.message || 'Не вдалося відкрити PDF.', 'error');
    }
}

async function handleHrPrintOperation(event) {
    const button = event.target.closest('[data-hr-print-operation]');
    if (!button) return;
    const id = Number(button.dataset.id);
    const action = button.dataset.hrPrintOperation;
    if (action === 'edit-automation') return editHrPrintAutomation(id);
    if (action === 'preview-job') return previewHrPrintJob(id, button.dataset.filename || '');
    button.disabled = true;
    try {
        if (action === 'run-automation') {
            const response = await hrPrintFetchJson(`/api/hr/attendance-document-automations/${id}/run`, { method: 'POST' });
            await loadHrPrintOperations({ silent: true });
            if (response.job?.status === 'queued') await previewHrPrintJob(response.job.id, response.job.filename || '');
            setHrPrintStatus('PDF сформовано один раз і додано до черги.', 'success');
        } else if (action === 'disable-automation') {
            await hrPrintFetchJson(`/api/hr/attendance-document-automations/${id}/disable`, { method: 'POST' });
            await loadHrPrintOperations({ silent: true });
            setHrPrintStatus('Автоматизацію вимкнено.', 'success');
        } else if (action === 'cancel-job') {
            await hrPrintFetchJson(`/api/hr/attendance-document-jobs/${id}/cancel`, { method: 'POST' });
            await loadHrPrintOperations({ silent: true });
            setHrPrintStatus('Завдання скасовано.', 'success');
        } else if (action === 'requeue-job') {
            const response = await hrPrintFetchJson(`/api/hr/attendance-document-jobs/${id}/requeue`, { method: 'POST' });
            await loadHrPrintOperations({ silent: true });
            if (response.job?.status === 'queued') await previewHrPrintJob(response.job.id, response.job.filename || '');
            setHrPrintStatus('Завдання повернуто до черги без створення дубля.', 'success');
        }
    } catch (error) {
        setHrPrintStatus(error.message || 'Операція не виконана.', 'error');
    } finally {
        button.disabled = false;
    }
}

async function generateHrPrintPreview() {
    if (hrPrintDocumentsState.generating) return;
    if (!canExportHrReports()) {
        showNotification('HR export permission required', 'error');
        return;
    }
    let payload;
    try {
        payload = hrPrintRequestPayload();
    } catch (error) {
        setHrPrintStatus(error.message, 'error');
        document.querySelector('[data-hr-print-category]')?.focus();
        return;
    }
    invalidateHrPrintPreview('Формуємо документ із актуального server snapshot…');
    const requestSeq = hrPrintDocumentsState.requestSeq;
    hrPrintDocumentsState.generating = true;
    const previewButton = document.getElementById('hrPrintPreviewButton');
    const state = document.getElementById('hrPrintPreviewState');
    const badge = document.getElementById('hrPrintPreviewBadge');
    if (previewButton) {
        previewButton.disabled = true;
        previewButton.setAttribute('aria-busy', 'true');
        previewButton.textContent = 'Формуємо…';
    }
    if (state) state.classList.add('is-loading');
    if (badge) {
        badge.textContent = 'Формується';
        badge.className = 'hr-print-preview-badge';
    }
    setHrPrintStatus('Завантажуємо актуальний roster і будуємо PDF…');
    try {
        const request = {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', Accept: 'application/pdf' },
            body: JSON.stringify(payload)
        };
        const response = typeof apiFetchWithAuthRetry === 'function'
            ? await apiFetchWithAuthRetry('/api/hr/attendance-documents/pdf', request)
            : await fetch('/api/hr/attendance-documents/pdf', request);
        if (!response) throw new Error('Сервер не повернув відповідь.');
        if (!response.ok) throw new Error(await hrPrintResponseError(response));
        const blob = await response.blob();
        if (!isHrPrintPreviewRequestCurrent(requestSeq)) return;
        await showHrPrintPreview({
            blob,
            filename: hrPrintFileName(),
            requestSeq,
            badgeText: 'Готово',
            statusMessage: 'Preview готовий. Завантаження і друк використають цей самий server snapshot.'
        });
    } catch (error) {
        if (requestSeq !== hrPrintDocumentsState.requestSeq) return;
        releaseHrPrintPreview();
        if (state) {
            state.textContent = error.message || 'Не вдалося сформувати PDF.';
            state.classList.remove('hidden', 'is-loading');
        }
        if (badge) {
            badge.textContent = 'Помилка';
            badge.className = 'hr-print-preview-badge is-stale';
        }
        setHrPrintStatus(error.message || 'Не вдалося сформувати PDF.', 'error');
    } finally {
        hrPrintDocumentsState.generating = false;
        if (previewButton) {
            previewButton.disabled = false;
            previewButton.removeAttribute('aria-busy');
            previewButton.textContent = 'Сформувати preview';
        }
    }
}

function hrPrintFileName() {
    if (hrPrintDocumentsState.previewFileName) return hrPrintDocumentsState.previewFileName;
    const isDaily = hrPrintTemplateId() === 'arrival_inout';
    const period = isDaily
        ? document.getElementById('hrPrintDocumentDate')?.value
        : document.getElementById('hrPrintDocumentMonth')?.value;
    return `event-genix-${isDaily ? 'arrival-inout' : 'month-grid'}-${period || 'v27'}.pdf`;
}

function downloadHrPrintPdf() {
    if (!hrPrintDocumentsState.previewUrl || !hrPrintDocumentsState.previewBlob) return;
    const link = document.createElement('a');
    link.href = hrPrintDocumentsState.previewUrl;
    link.download = hrPrintFileName();
    document.body.appendChild(link);
    link.click();
    link.remove();
}

function printHrPrintPdf() {
    if (!hrPrintDocumentsState.previewUrl || !hrPrintDocumentsState.previewBlob) return;
    const frame = document.getElementById('hrPrintPreviewFrame');
    if (navigator.pdfViewerEnabled === false || !frame || frame.classList.contains('hidden')) {
        openHrPrintPdf();
        return;
    }
    try {
        frame?.contentWindow?.focus();
        frame?.contentWindow?.print();
    } catch {
        openHrPrintPdf();
    }
}

function openHrPrintPdf() {
    if (!hrPrintDocumentsState.previewUrl || !hrPrintDocumentsState.previewBlob) return;
    window.open(hrPrintDocumentsState.previewUrl, '_blank', 'noopener');
}

function closeHrPrintDocuments() {
    const overlay = document.getElementById('hrPrintDocumentsModal');
    if (!overlay || !hrPrintDocumentsState.open) return;
    hrPrintDocumentsState.open = false;
    hrPrintDocumentsState.requestSeq += 1;
    overlay.classList.add('hidden');
    overlay.setAttribute('aria-hidden', 'true');
    document.body.classList.remove('hr-print-documents-open');
    releaseHrPrintPreview();
    hrPrintDocumentsState.generating = false;
    const opener = hrPrintDocumentsState.opener;
    hrPrintDocumentsState.opener = null;
    if (opener?.isConnected) opener.focus();
}

async function openHrPrintDocuments(event) {
    const overlay = document.getElementById('hrPrintDocumentsModal');
    if (!canExportHrReports()) {
        showNotification('HR export permission required', 'error');
        return;
    }
    if (!overlay) return;
    hrPrintDocumentsState.open = true;
    hrPrintDocumentsState.opener = event?.currentTarget || document.activeElement;
    overlay.classList.remove('hidden');
    overlay.setAttribute('aria-hidden', 'false');
    document.body.classList.add('hr-print-documents-open');
    setHrPrintStatus('');
    renderHrPrintProfessionList();
    syncHrPrintTemplateFields();
    document.getElementById('hrPrintDocumentsClose')?.focus();
    professionCatalogLoadState = professionCatalogLoadState === 'ready' ? 'ready' : 'loading';
    syncHrPrintEmployeeCount();
    const saveAutomation = document.getElementById('hrPrintAutomationSave');
    if (saveAutomation) {
        saveAutomation.disabled = !canManage;
        saveAutomation.title = canManage ? '' : 'Потрібне право керування працівниками';
    }
    try {
        await Promise.all([
            ensureProfessionsLoaded({ silent: true }),
            loadHrPrintOperations()
        ]);
    } finally {
        if (hrPrintDocumentsState.open) syncHrPrintEmployeeCount();
    }
}

function handleHrPrintModalKeydown(event) {
    if (!hrPrintDocumentsState.open) return;
    if (event.key === 'Escape') {
        event.preventDefault();
        closeHrPrintDocuments();
        return;
    }
    if (event.key !== 'Tab') return;
    const focusable = hrPrintFocusableElements();
    if (!focusable.length) return;
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
    } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
    }
}

function initHrPrintDocuments() {
    if (hrPrintDocumentsState.initialized) return;
    const overlay = document.getElementById('hrPrintDocumentsModal');
    if (!overlay) return;
    hrPrintDocumentsState.initialized = true;
    const today = todayStr();
    const dateInput = document.getElementById('hrPrintDocumentDate');
    const monthInput = document.getElementById('hrPrintDocumentMonth');
    if (dateInput) dateInput.value = today;
    if (monthInput) monthInput.value = today.slice(0, 7);
    const printDocumentsButton = document.getElementById('btnHrPrintDocuments');
    if (printDocumentsButton) {
        const canExport = canExportHrReports();
        printDocumentsButton.hidden = !canExport;
        printDocumentsButton.disabled = !canExport;
    }
    printDocumentsButton?.addEventListener('click', openHrPrintDocuments);
    document.getElementById('hrPrintDocumentsClose')?.addEventListener('click', closeHrPrintDocuments);
    document.getElementById('hrPrintPreviewButton')?.addEventListener('click', generateHrPrintPreview);
    document.getElementById('hrPrintDownloadButton')?.addEventListener('click', downloadHrPrintPdf);
    document.getElementById('hrPrintPrintButton')?.addEventListener('click', printHrPrintPdf);
    document.getElementById('hrPrintOpenButton')?.addEventListener('click', openHrPrintPdf);
    document.getElementById('hrPrintResetPreset')?.addEventListener('click', resetHrPrintPreset);
    document.getElementById('hrPrintAutomationRefresh')?.addEventListener('click', () => loadHrPrintOperations());
    document.getElementById('hrPrintAutomationSave')?.addEventListener('click', saveHrPrintAutomation);
    document.getElementById('hrPrintAutomationCancelEdit')?.addEventListener('click', resetHrPrintAutomationEditor);
    document.getElementById('hrPrintAutomationList')?.addEventListener('click', handleHrPrintOperation);
    document.getElementById('hrPrintJobList')?.addEventListener('click', handleHrPrintOperation);
    document.getElementById('hrPrintSelectAll')?.addEventListener('click', () => {
        const allSelected = hrPrintDocumentsState.selectedCategoryIds.size === HR_PRINT_CATEGORIES.length;
        hrPrintDocumentsState.selectedCategoryIds = new Set(allSelected ? [] : HR_PRINT_CATEGORIES.map(item => item.id));
        renderHrPrintProfessionList();
        invalidateHrPrintPreview();
    });
    document.getElementById('hrPrintProfessionSearch')?.addEventListener('input', event => {
        hrPrintDocumentsState.professionQuery = event.target.value || '';
        renderHrPrintProfessionList();
    });
    document.getElementById('hrPrintProfessionList')?.addEventListener('change', event => {
        const input = event.target.closest('[data-hr-print-category]');
        if (!input) return;
        if (input.checked) hrPrintDocumentsState.selectedCategoryIds.add(input.value);
        else hrPrintDocumentsState.selectedCategoryIds.delete(input.value);
        syncHrPrintSelectAllButton();
        syncHrPrintEmployeeCount();
        invalidateHrPrintPreview();
    });
    document.getElementById('hrPrintDocumentsForm')?.addEventListener('input', event => {
        if (event.target.id === 'hrPrintProfessionSearch' || event.target.matches('[data-hr-print-category]')) return;
        if (event.target.closest('[aria-labelledby="hrPrintAutomationTitle"]')) return;
        if (event.target.matches('[data-hr-print-font]')) syncHrPrintFontOutput(event.target);
        syncHrPrintPresetWarning();
        invalidateHrPrintPreview();
    });
    document.getElementById('hrPrintDocumentsForm')?.addEventListener('change', event => {
        if (event.target.name === 'hrPrintTemplate') syncHrPrintTemplateFields();
    });
    overlay.addEventListener('click', event => {
        if (event.target === overlay) closeHrPrintDocuments();
    });
    overlay.addEventListener('keydown', handleHrPrintModalKeydown);
    window.addEventListener('beforeunload', releaseHrPrintPreview);
    renderHrPrintProfessionList();
    syncHrPrintTemplateFields();
}

