function formatStaffHistoryTime(value) {
    if (!value) return 'без дати';
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) return String(value);
    return date.toLocaleString('uk-UA', { day: '2-digit', month: '2-digit', year: '2-digit', hour: '2-digit', minute: '2-digit' });
}

function staffHistoryChangedFields(details = {}) {
    const changes = details?.changes && typeof details.changes === 'object' ? details.changes : null;
    const fields = changes ? Object.keys(changes) : (Array.isArray(details?.changed_fields) ? details.changed_fields : []);
    return fields.map(field => STAFF_HISTORY_FIELD_LABELS[field] || field).slice(0, 8);
}

function staffHistoryValueText(value, field = '') {
    if (value == null || value === '') return '—';
    if (typeof value === 'boolean') return value ? 'Так' : 'Ні';
    const normalizedField = String(field || '');
    if (normalizedField === 'role_type' || normalizedField === 'professionKey' || normalizedField === 'profession_key') {
        return professionTitle(value) || String(value);
    }
    if (normalizedField === 'secondary_professions' && Array.isArray(value)) {
        return value.map(item => professionTitle(item) || String(item)).join(', ') || '—';
    }
    if (normalizedField === 'profession_rates' && Array.isArray(value)) {
        return value.map(item => {
            const key = item?.profession_key || item?.professionKey || '';
            const rate = Number(item?.hourly_rate ?? item?.hourlyRate);
            const label = professionTitle(key) || key || 'Професія';
            return `${label}: ${Number.isFinite(rate) ? `${rate.toLocaleString('uk-UA')} ₴` : '—'}`;
        }).join(', ') || '—';
    }
    if (normalizedField === 'rate_unit') return payrollProfileRateUnitLabel(value);
    if ((normalizedField === 'hourly_rate' || normalizedField.endsWith('_rate')) && Number.isFinite(Number(value))) {
        return `${Number(value).toLocaleString('uk-UA')} ₴`;
    }
    if (Array.isArray(value)) {
        const text = value.map(item => staffHistoryValueText(item)).join(', ');
        return text || '—';
    }
    if (typeof value === 'object') {
        let text = '';
        try {
            text = JSON.stringify(value);
        } catch {
            text = String(value);
        }
        return text.length > 180 ? `${text.slice(0, 177)}…` : text;
    }
    const text = String(value);
    return text.length > 180 ? `${text.slice(0, 177)}…` : text;
}

function staffHistoryChangeEntries(details = {}) {
    const changes = details?.changes && typeof details.changes === 'object' && !Array.isArray(details.changes)
        ? details.changes
        : null;
    if (!changes) return [];
    return Object.entries(changes).map(([field, change]) => {
        const hasShape = change && typeof change === 'object' && !Array.isArray(change)
            && (Object.prototype.hasOwnProperty.call(change, 'from') || Object.prototype.hasOwnProperty.call(change, 'to'));
        return {
            field,
            label: STAFF_HISTORY_FIELD_LABELS[field] || field,
            from: hasShape ? change.from : null,
            to: hasShape ? change.to : change
        };
    });
}

function renderStaffHistoryChanges(details = {}) {
    const entries = staffHistoryChangeEntries(details);
    if (!entries.length) {
        const fields = staffHistoryChangedFields(details);
        return fields.length
            ? `<div class="hr-staff-history-fields">${fields.map(field => `<i>${escapeHtml(field)}</i>`).join('')}</div>`
            : '';
    }
    const visibleEntries = entries.slice(0, 8);
    const remainder = Math.max(0, entries.length - visibleEntries.length);
    return `<div class="hr-staff-history-changes">
        ${visibleEntries.map(entry => `<div class="hr-staff-history-change">
            <strong>${escapeHtml(entry.label)}</strong>
            <span><em>Було:</em> ${escapeHtml(staffHistoryValueText(entry.from, entry.field))}</span>
            <span><em>Стало:</em> ${escapeHtml(staffHistoryValueText(entry.to, entry.field))}</span>
        </div>`).join('')}
        ${remainder ? `<small>Ще змін: ${remainder}</small>` : ''}
    </div>`;
}

function renderStaffHistoryRows(rows = []) {
    if (!rows.length) return '<div class="hr-staff-history-empty">Змін профілю ще немає.</div>';
    return rows.map(row => {
        const details = row.details || {};
        return `<article class="hr-staff-history-item">
            <b>${escapeHtml(STAFF_HISTORY_ACTION_LABELS[row.action] || row.action || 'Подія')}</b>
            <span>${escapeHtml(formatStaffHistoryTime(row.created_at))} · Хто: ${escapeHtml(row.performed_by || 'система')}</span>
            ${renderStaffHistoryChanges(details)}
        </article>`;
    }).join('');
}

async function loadStaffProfileHistory(staffId) {
    const root = document.getElementById('editStaffHistory');
    const numericStaffId = Number(staffId);
    if (!root || !Number.isFinite(numericStaffId) || numericStaffId <= 0) return;
    const seq = ++staffProfileHistoryLoadSeq;
    root.innerHTML = 'Історія завантажується...';
    const data = await hrFetch(`/staff/${numericStaffId}/history?limit=30`).catch(() => null);
    if (seq !== staffProfileHistoryLoadSeq || Number(activeEditStaffId()) !== numericStaffId) return data;
    if (!data?.success) {
        root.innerHTML = '<div class="hr-staff-history-empty">Не вдалося завантажити історію.</div>';
        return data;
    }
    root.innerHTML = renderStaffHistoryRows(data.data || []);
    return data;
}

function activeEditStaffId() {
    return document.getElementById('editStaffId')?.value;
}

function isActiveStaffEditLoad(staffId) {
    const numericStaffId = Number(staffId);
    return Number.isFinite(numericStaffId) && Number(activeEditStaffId()) === numericStaffId;
}

function mergeFreshStaffProfile(staff = {}) {
    const id = Number(staff?.id);
    if (!Number.isFinite(id) || id <= 0) return staff || {};
    const index = teamStaff.findIndex(item => Number(item.id) === id);
    const merged = { ...(index >= 0 ? teamStaff[index] : {}), ...staff, id };
    if (index >= 0) teamStaff[index] = merged;
    else teamStaff.push(merged);
    return merged;
}

function updateStaffPhotoPreview(urlOverride) {
    const preview = document.getElementById('editPhotoPreview');
    if (!preview) return;
    const rawUrl = urlOverride !== undefined
        ? urlOverride
        : document.getElementById('editPhotoUrl')?.value;
    const photoUrl = String(rawUrl || '').trim();
    preview.replaceChildren();
    preview.classList.toggle('has-photo', Boolean(photoUrl));
    if (!photoUrl) {
        preview.textContent = '!';
        return;
    }
    const img = document.createElement('img');
    img.src = photoUrl;
    img.alt = '';
    img.loading = 'lazy';
    img.decoding = 'async';
    img.addEventListener('error', () => {
        preview.classList.remove('has-photo');
        preview.replaceChildren();
        preview.textContent = '!';
    }, { once: true });
    preview.appendChild(img);
}

function clearStaffPhotoUrl() {
    const input = document.getElementById('editPhotoUrl');
    if (input) {
        input.value = '';
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.focus();
    }
    updateStaffPhotoPreview('');
    const button = decorateStaffProfileActionButton(document.querySelector('#staffEditModal .hr-staff-photo-actions .btn-secondary'));
    if (button) {
        setStaffProfileActionState(button, 'success', 'Очищено');
        scheduleStaffProfileActionReset(button);
    }
}

function formatStaffDateValue(value) {
    if (!value) return 'без дати';
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) return String(value).slice(0, 10);
    return date.toLocaleDateString('uk-UA');
}

function formatStaffFileSize(bytes) {
    return formatResumeFileSize(bytes);
}

function staffDateTone(value) {
    if (!value) return '';
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) return '';
    const days = Math.ceil((date.getTime() - Date.now()) / 86400000);
    if (days < 0) return 'hr-staff-foundation-danger';
    if (days <= 30) return 'hr-staff-foundation-warning';
    return '';
}

function renderStaffFoundationEmpty(text) {
    return `<div class="hr-staff-foundation-empty">${escapeHtml(text)}</div>`;
}

function staffDateInputValue(value) {
    if (!value) return '';
    if (typeof value === 'string') return value.slice(0, 10);
    const date = new Date(value);
    return Number.isNaN(date.getTime()) ? '' : date.toISOString().slice(0, 10);
}

function payrollSchemeAmount(scheme = {}, fallbackRate = 0) {
    const config = scheme.config || {};
    const type = scheme.scheme_type || scheme.schemeType || 'hourly';
    if (type === 'per_shift') return Number(config.perShiftRate ?? config.rate ?? config.amount ?? 0);
    if (type === 'monthly_fixed') return Number(config.monthlyAmount ?? config.fixedAmount ?? config.amount ?? 0);
    if (type === 'percent') return Number(config.percentRate ?? config.rate ?? 0);
    if (type === 'manual') return Number(config.manualAmount ?? config.amount ?? 0);
    if (type === 'piece') return Number(config.pieceRate ?? config.rate ?? config.amount ?? 0);
    if (type === 'hybrid') return Number(config.base?.rate ?? config.baseRate ?? fallbackRate ?? 0);
    return Number(config.hourlyRate ?? config.rate ?? fallbackRate ?? 0);
}

function payrollSchemeAmountLabel(type = 'hourly') {
    return {
        per_shift: 'Сума за вихід',
        hourly: 'Ставка за годину',
        monthly_fixed: 'Фікс за місяць',
        percent: 'Відсоток',
        hybrid: 'Базова ставка',
        manual: 'Ручна сума',
        piece: 'Ставка за одиницю'
    }[type] || 'Ставка';
}

function updatePayrollSchemeAmountLabel() {
    const type = document.getElementById('editPayrollSchemeType')?.value || 'hourly';
    const label = document.getElementById('editPayrollSchemeAmountLabel');
    if (label) label.textContent = payrollSchemeAmountLabel(type);
}

function updatePayrollAdvancedVisibility() {
    updatePayrollSchemeAmountLabel();
    const type = document.getElementById('editPayrollSchemeType')?.value || 'hourly';
    const baseKind = document.getElementById('editPayrollBaseKind')?.value || 'hourly';
    const hybridConfig = document.getElementById('editPayrollHybridConfig');
    const monthlyNormConfig = document.getElementById('editPayrollMonthlyNormConfig');
    if (hybridConfig) hybridConfig.hidden = type !== 'hybrid';
    if (monthlyNormConfig) monthlyNormConfig.hidden = !(type === 'monthly_fixed' || (type === 'hybrid' && baseKind === 'monthly_fixed'));
}

function numberFromInput(id, fallback = 0) {
    const value = Number(document.getElementById(id)?.value || fallback || 0);
    return Number.isFinite(value) && value > 0 ? value : 0;
}

function textFromInput(id, fallback = '') {
    return (document.getElementById(id)?.value || fallback || '').trim();
}

function setInputValue(id, value = '') {
    const el = document.getElementById(id);
    if (el) el.value = value === null || value === undefined ? '' : String(value);
}

function setPayrollHybridForm(config = {}, fallbackRate = 0) {
    const base = config.base || {};
    const bonus = (Array.isArray(config.bonusRules) && config.bonusRules[0]) || {};
    const percent = (Array.isArray(config.percentRules) && config.percentRules[0]) || {};
    const deduction = (Array.isArray(config.deductions) && config.deductions[0]) || {};
    const advance = (Array.isArray(config.zrsRules) && config.zrsRules[0])
        || (Array.isArray(config.zrs) && config.zrs[0])
        || (Array.isArray(config.advances) && config.advances[0])
        || {};
    setInputValue('editPayrollBaseKind', base.kind || config.baseKind || 'hourly');
    setInputValue('editPayrollBaseQuantity', base.quantity ?? config.baseQuantity ?? '');
    setInputValue('editPayrollHybridPercentRate', percent.rate ?? percent.percentRate ?? '');
    setInputValue('editPayrollHybridPercentBase', percent.baseAmount ?? percent.percentBase ?? '');
    setInputValue('editPayrollBonusLabel', bonus.label || 'Премія');
    setInputValue('editPayrollBonusAmount', bonus.amount ?? config.bonusAmount ?? '');
    setInputValue('editPayrollDeductionLabel', deduction.label || 'Утримання');
    setInputValue('editPayrollDeductionAmount', deduction.amount ?? config.deductionAmount ?? '');
    setInputValue('editPayrollAdvanceLabel', advance.label || 'ЗРС');
    setInputValue('editPayrollAdvanceAmount', advance.amount ?? config.advanceAmount ?? '');
    const amount = document.getElementById('editPayrollSchemeAmount');
    if (amount && amount.value === '') amount.value = String(base.rate ?? base.amount ?? config.baseRate ?? fallbackRate ?? 0);
}

function payrollMonthlyNormConfig(config = {}, type = 'monthly_fixed') {
    const source = type === 'hybrid' ? (config.base || {}) : config;
    return {
        month: source.monthlyNormMonth || source.monthly_norm_month || '',
        hours: Number(source.monthlyNormMinutes ?? source.monthly_norm_minutes ?? 0) / 60,
        source: source.monthlyNormSource || source.monthly_norm_source || '',
        confirmed: (source.monthlyNormConfirmed ?? source.monthly_norm_confirmed) === true
    };
}

function setPayrollMonthlyNormForm(config = {}, type = 'monthly_fixed') {
    const norm = payrollMonthlyNormConfig(config, type);
    setInputValue('editPayrollMonthlyNormMonth', norm.month);
    setInputValue('editPayrollMonthlyNormHours', norm.hours || '');
    setInputValue('editPayrollMonthlyNormSource', norm.source);
    const confirmed = document.getElementById('editPayrollMonthlyNormConfirmed');
    if (confirmed) confirmed.checked = norm.confirmed;
}

function collectPayrollMonthlyNormFromForm() {
    return {
        monthlyNormMinutes: Math.round(numberFromInput('editPayrollMonthlyNormHours') * 60),
        monthlyNormMonth: textFromInput('editPayrollMonthlyNormMonth') || null,
        monthlyNormSource: textFromInput('editPayrollMonthlyNormSource') || null,
        monthlyNormConfirmed: document.getElementById('editPayrollMonthlyNormConfirmed')?.checked === true
    };
}

function collectPayrollSchemeConfigFromForm(type, amount) {
    if (type === 'monthly_fixed') return collectPayrollMonthlyNormFromForm();
    if (type !== 'hybrid') return {};
    const bonusAmount = numberFromInput('editPayrollBonusAmount');
    const percentRate = numberFromInput('editPayrollHybridPercentRate');
    const deductionAmount = numberFromInput('editPayrollDeductionAmount');
    const advanceAmount = numberFromInput('editPayrollAdvanceAmount');
    const baseKind = document.getElementById('editPayrollBaseKind')?.value || 'hourly';
    return {
        base: {
            ...(baseKind === 'monthly_fixed' ? collectPayrollMonthlyNormFromForm() : {}),
            kind: baseKind,
            rate: amount,
            amount,
            quantity: numberFromInput('editPayrollBaseQuantity')
        },
        bonusRules: bonusAmount ? [{ kind: 'fixed', label: textFromInput('editPayrollBonusLabel', 'Премія'), amount: bonusAmount }] : [],
        percentRules: percentRate ? [{ kind: 'percent', label: 'Відсоток', rate: percentRate, baseAmount: numberFromInput('editPayrollHybridPercentBase') }] : [],
        deductions: deductionAmount ? [{ kind: 'fixed', label: textFromInput('editPayrollDeductionLabel', 'Утримання'), amount: deductionAmount }] : [],
        zrsRules: advanceAmount ? [{ kind: 'fixed', label: textFromInput('editPayrollAdvanceLabel', 'ЗРС'), amount: advanceAmount }] : []
    };
}

function renderStaffRoleAssignments(rows = []) {
    if (!rows.length) return renderStaffFoundationEmpty('Ролі ще не синхронізовані.');
    const optionHtml = (labels, selected) => Object.entries(labels).map(([value, label]) =>
        `<option value="${escapeHtml(value)}"${value === selected ? ' selected' : ''}>${escapeHtml(label)}</option>`
    ).join('');
    return rows.map(row => {
        const key = normalizeProfessionKey(row.profession_key || row.professionKey);
        const primary = row.is_primary || row.isPrimary;
        const title = row.profession_title || row.professionTitle || professionTitle(key);
        return `<article class="hr-staff-role-assignment-row" data-role-assignment="${escapeHtml(key)}" data-primary="${primary ? 'true' : 'false'}">
            <div class="hr-staff-role-assignment-title">
                <b>${escapeHtml(title)}</b>
                <small>${primary ? 'Основна роль' : 'Додаткова роль'}</small>
            </div>
            <select data-role-field="status" aria-label="Статус ролі ${escapeHtml(title)}">${optionHtml(STAFF_ROLE_STATUS_LABELS, row.status || 'active')}</select>
            <select data-role-field="admission_status" aria-label="Допуск ${escapeHtml(title)}">${optionHtml(STAFF_ROLE_ADMISSION_LABELS, row.admission_status || row.admissionStatus || 'pending')}</select>
            <select data-role-field="internship_status" aria-label="Стажування ${escapeHtml(title)}">${optionHtml(STAFF_ROLE_INTERNSHIP_LABELS, row.internship_status || row.internshipStatus || 'none')}</select>
        </article>`;
    }).join('');
}

function readStaffRoleAssignmentRows() {
    const explicitRates = new Map(readStaffProfessionRates().map(row => [normalizeProfessionKey(row.profession_key), Number(row.hourly_rate || 0)]));
    const baseRate = Number(document.getElementById('editHourlyRate')?.value || 0);
    return Array.from(document.querySelectorAll('[data-role-assignment]')).map(row => {
        const key = normalizeProfessionKey(row.dataset.roleAssignment);
        const isPrimary = row.dataset.primary === 'true';
        return {
            profession_key: key,
            is_primary: isPrimary,
            status: row.querySelector('[data-role-field="status"]')?.value || 'active',
            admission_status: row.querySelector('[data-role-field="admission_status"]')?.value || 'pending',
            internship_status: row.querySelector('[data-role-field="internship_status"]')?.value || 'none',
            hourly_rate: explicitRates.get(key) || (isPrimary && baseRate > 0 ? baseRate : null)
        };
    }).filter(row => row.profession_key);
}

function refreshStaffRoleAssignmentsFromCurrentForm() {
    const root = document.getElementById('editStaffRoleAssignments');
    if (!root) return;
    const existing = new Map(readStaffRoleAssignmentRows().map(row => [row.profession_key, row]));
    const primary = normalizeProfessionKey(document.getElementById('editRoleType')?.value);
    const keys = normalizeProfessionList([primary, ...readStaffSecondaryProfessionSelection()]);
    if (!keys.length) {
        root.innerHTML = renderStaffFoundationEmpty('Спочатку виберіть професію.');
        return;
    }
    const rows = keys.map(key => ({
        profession_key: key,
        profession_title: professionTitle(key),
        is_primary: key === primary,
        status: existing.get(key)?.status || 'active',
        admission_status: existing.get(key)?.admission_status || (key === primary ? 'approved' : 'pending'),
        internship_status: existing.get(key)?.internship_status || (key === 'intern' ? 'in_progress' : 'none')
    }));
    root.innerHTML = renderStaffRoleAssignments(rows);
}

const STAFF_WORKSPACE_SECTION_CONFIG = {
    documents: {
        rootId: 'editStaffDocuments',
        feedbackId: 'editStaffDocumentsFeedback',
        loading: 'Завантажуємо документи та скани…',
        empty: 'Документи ще не додані.',
        restricted: 'Документи та скани доступні тільки HR/керівнику.',
        error: 'Не вдалося завантажити документи.'
    },
    medical: {
        rootId: 'editMedicalBookList',
        feedbackId: 'editMedicalBookFeedback',
        loading: 'Завантажуємо медкнижку…',
        empty: 'Медкнижка ще не зафіксована.',
        restricted: 'Медкнижка доступна тільки HR/керівнику.',
        error: 'Не вдалося завантажити медкнижку.'
    },
    resources: {
        rootId: 'editStaffResources',
        feedbackId: 'editStaffResourcesFeedback',
        loading: 'Завантажуємо видані ресурси…',
        empty: 'Немає активних виданих ресурсів.',
        restricted: 'Видані ресурси доступні тільки HR/керівнику.',
        error: 'Не вдалося завантажити ресурси.'
    }
};

function getStaffWorkspaceSectionConfig(section) {
    return STAFF_WORKSPACE_SECTION_CONFIG[section] || null;
}

function getStaffWorkspaceRoot(section) {
    const config = getStaffWorkspaceSectionConfig(section);
    return config ? document.getElementById(config.rootId) : null;
}

function renderStaffWorkspaceState(section, state, message = '') {
    const config = getStaffWorkspaceSectionConfig(section);
    if (!config) return '';
    const fallback = config[state] || config.empty;
    const text = escapeHtml(message || fallback);
    if (state === 'loading') {
        return `<div class="hr-staff-workspace-state" data-state="loading" role="status">
            <span class="hr-staff-workspace-skeleton" aria-hidden="true"><span></span><span></span><span></span></span>
            <span class="hr-staff-workspace-state__message">${text}</span>
        </div>`;
    }
    const retry = state === 'error'
        ? `<button type="button" class="hr-staff-action hr-staff-action--secondary" onclick="retryStaffWorkspaceSection('${section}', this)">Повторити</button>`
        : '';
    return `<div class="hr-staff-workspace-state" data-state="${escapeHtml(state)}" role="${state === 'error' ? 'alert' : 'status'}">
        <span class="hr-staff-workspace-state__message">${text}</span>${retry}
    </div>`;
}

function setStaffWorkspaceState(section, state, message = '') {
    const root = getStaffWorkspaceRoot(section);
    if (!root) return;
    root.dataset.state = state;
    root.setAttribute('aria-busy', state === 'loading' ? 'true' : 'false');
    root.innerHTML = renderStaffWorkspaceState(section, state, message);
}

function setStaffWorkspaceContent(section, html) {
    const root = getStaffWorkspaceRoot(section);
    if (!root) return;
    root.dataset.state = 'ready';
    root.setAttribute('aria-busy', 'false');
    root.innerHTML = html;
}

function setStaffWorkspaceFeedback(section, state = '', message = '') {
    const config = getStaffWorkspaceSectionConfig(section);
    const root = config ? document.getElementById(config.feedbackId) : null;
    if (!root) return;
    root.hidden = !state || !message;
    root.dataset.state = state || '';
    root.setAttribute('role', state === 'error' ? 'alert' : 'status');
    root.textContent = message || '';
}

function setStaffResourceOptionsState(state = '', message = '') {
    const root = document.getElementById('editResourceOptionsState');
    if (!root) return;
    root.hidden = !state || !message;
    root.dataset.state = state || '';
    root.setAttribute('role', state === 'error' ? 'alert' : 'status');
    if (!state || !message) {
        root.textContent = '';
        return;
    }
    const retry = state === 'error'
        ? `<button type="button" class="hr-staff-action hr-staff-action--secondary" onclick="retryStaffResourceOptions(this)">Повторити</button>`
        : '';
    root.innerHTML = `<span class="hr-staff-resource-options-state__message">${escapeHtml(message)}</span>${retry}`;
}

function renderStaffResourceOptions(items = [], selected = '') {
    if (!items.length) return '<option value="">Немає доступних позицій</option>';
    return [
        '<option value="">Виберіть позицію</option>',
        ...items.map(item => {
            const label = item.subtitle ? `${item.label} · ${item.subtitle}` : item.label;
            return `<option value="${escapeHtml(item.id)}" data-title="${escapeHtml(item.label || '')}"${String(item.id) === String(selected) ? ' selected' : ''}>${escapeHtml(label)}</option>`;
        })
    ].join('');
}

function selectedStaffResourceOption() {
    const select = document.getElementById('editResourceSourceId');
    const option = select?.selectedOptions?.[0];
    if (!select || !option || !option.value) return null;
    return {
        id: option.value,
        title: option.dataset.title || option.textContent || ''
    };
}

function syncResourceTitleFromOption() {
    const kind = document.getElementById('editResourceKind')?.value || 'custom';
    const title = document.getElementById('editResourceTitle');
    const selected = selectedStaffResourceOption();
    if (kind !== 'custom' && title && selected?.title) title.value = selected.title;
}

function updateResourcePickerVisibility() {
    const kind = document.getElementById('editResourceKind')?.value || 'custom';
    const sourceGroup = document.getElementById('editResourceSourceGroup');
    const titleGroup = document.getElementById('editResourceTitleGroup');
    if (sourceGroup) sourceGroup.hidden = kind === 'custom';
    if (titleGroup) titleGroup.hidden = false;
}

const STAFF_WORKSPACE_VIEW_STORAGE_KEYS = {
    documents: 'eventgenix.hr.staff.documents.view',
    resources: 'eventgenix.hr.staff.resources.view'
};
const staffWorkspaceViewMemory = new Map();

function readStaffWorkspaceStoredView(section, fallback = 'active') {
    try {
        const value = window.sessionStorage?.getItem(STAFF_WORKSPACE_VIEW_STORAGE_KEYS[section]);
        if (section === 'documents' && ['active', 'archive'].includes(value)) return value;
        if (section === 'resources' && ['active', 'history'].includes(value)) return value;
    } catch (_) { /* session storage may be unavailable */ }
    const memoryValue = staffWorkspaceViewMemory.get(section);
    if (section === 'documents' && ['active', 'archive'].includes(memoryValue)) return memoryValue;
    if (section === 'resources' && ['active', 'history'].includes(memoryValue)) return memoryValue;
    return fallback;
}

function currentStaffWorkspaceView(section) {
    return section === 'documents' ? staffDocumentListView : section === 'resources' ? staffResourceListView : 'active';
}

function syncStaffWorkspaceViewControls(section) {
    const activeView = currentStaffWorkspaceView(section);
    document.querySelectorAll(`[data-staff-workspace-view^="${section}:"]`).forEach(button => {
        const view = String(button.dataset.staffWorkspaceView || '').split(':')[1];
        button.setAttribute('aria-pressed', view === activeView ? 'true' : 'false');
    });
}

async function setStaffWorkspaceView(section, view, button = null) {
    const allowed = section === 'documents' ? ['active', 'archive'] : section === 'resources' ? ['active', 'history'] : [];
    if (!allowed.includes(view)) return { success: false, error: 'invalid_workspace_view' };
    if (section === 'documents') staffDocumentListView = view;
    if (section === 'resources') staffResourceListView = view;
    staffWorkspaceViewMemory.set(section, view);
    try { window.sessionStorage?.setItem(STAFF_WORKSPACE_VIEW_STORAGE_KEYS[section], view); } catch (_) { /* optional persistence */ }
    syncStaffWorkspaceViewControls(section);
    return retryStaffWorkspaceSection(section, button);
}

function restoreStaffWorkspaceViews() {
    staffDocumentListView = readStaffWorkspaceStoredView('documents');
    staffResourceListView = readStaffWorkspaceStoredView('resources');
    syncStaffWorkspaceViewControls('documents');
    syncStaffWorkspaceViewControls('resources');
}

function syncStaffDocumentPermissionState(allowed = canManage) {
    const permitted = Boolean(allowed);
    const upload = document.getElementById('editDocumentUpload');
    const form = document.getElementById('editStaffDocumentsForm');
    const restricted = document.getElementById('editStaffDocumentsRestricted');
    if (upload) {
        upload.hidden = !permitted;
        upload.disabled = !permitted;
    }
    if (form) form.hidden = !permitted;
    if (restricted) restricted.hidden = permitted;
}

function syncStaffMedicalBookPermissionState(allowed = canManage) {
    const permitted = Boolean(allowed);
    const form = document.getElementById('editStaffMedicalForm');
    const restricted = document.getElementById('editStaffMedicalRestricted');
    const save = document.getElementById('editMedicalSave');
    const cancel = document.getElementById('editMedicalCancel');
    const editing = Boolean(document.getElementById('editMedicalCertificationId')?.value);
    if (form) form.hidden = !permitted;
    if (restricted) restricted.hidden = permitted;
    if (save) {
        save.hidden = !permitted;
        if (!permitted) save.disabled = true;
        else if (save.dataset.staffActionPending !== 'true') save.disabled = false;
    }
    if (cancel) cancel.hidden = !permitted || !editing;
}

function syncStaffMedicalDocumentOptions(rows = []) {
    const select = document.getElementById('editMedicalDocumentId');
    if (!select) return;
    const currentValue = String(select.value || '');
    const currentLabel = select.selectedOptions?.[0]?.textContent || '';
    const available = rows.filter(item => item.status !== 'archived');
    const options = available.map(item => {
        const type = STAFF_DOCUMENT_TYPE_LABELS[item.document_type] || item.document_type || 'Документ';
        const label = `${type} · ${item.title || item.original_name || `#${item.id}`}`;
        return `<option value="${Number(item.id)}">${escapeHtml(label)}</option>`;
    });
    if (currentValue && !available.some(item => String(item.id) === currentValue)) {
        options.push(`<option value="${escapeHtml(currentValue)}">${escapeHtml(currentLabel || `Документ #${currentValue}`)}</option>`);
    }
    select.innerHTML = `<option value="">Без привʼязаного документа</option>${options.join('')}`;
    if (currentValue) select.value = currentValue;
}

function syncStaffMedicalBookDuplicateWarning() {
    const warning = document.getElementById('editMedicalDuplicateWarning');
    if (!warning) return false;
    const editingId = Number(document.getElementById('editMedicalCertificationId')?.value || 0);
    const issuedAt = document.getElementById('editMedicalIssuedAt')?.value || '';
    const expiresAt = document.getElementById('editMedicalExpiresAt')?.value || '';
    const duplicate = staffMedicalBookRows.find(item => item.status === 'active'
        && Number(item.id) !== editingId
        && String(item.issued_at || '').slice(0, 10) === issuedAt
        && String(item.expires_at || '').slice(0, 10) === expiresAt);
    warning.hidden = !duplicate;
    warning.textContent = duplicate
        ? `Уже є активна медкнижка з такими датами (запис #${duplicate.id}). Повторне створення буде заблоковано.`
        : '';
    return Boolean(duplicate);
}

function setStaffMedicalBookEditMode(item = null) {
    const certificationId = document.getElementById('editMedicalCertificationId');
    const issuedAt = document.getElementById('editMedicalIssuedAt');
    const expiresAt = document.getElementById('editMedicalExpiresAt');
    const documentId = document.getElementById('editMedicalDocumentId');
    const notes = document.getElementById('editMedicalNotes');
    const save = document.getElementById('editMedicalSave');
    const cancel = document.getElementById('editMedicalCancel');
    const editing = Boolean(item?.id);
    if (certificationId) certificationId.value = editing ? String(item.id) : '';
    if (issuedAt) issuedAt.value = editing ? String(item.issued_at || '').slice(0, 10) : '';
    if (expiresAt) expiresAt.value = editing ? String(item.expires_at || '').slice(0, 10) : '';
    if (documentId) {
        const value = editing && item.document_id ? String(item.document_id) : '';
        if (value && !Array.from(documentId.options).some(option => option.value === value)) {
            const option = document.createElement('option');
            option.value = value;
            option.textContent = item.document_title || `Документ #${value}`;
            documentId.appendChild(option);
        }
        documentId.value = value;
    }
    if (notes) notes.value = editing ? item.notes || '' : '';
    if (save) {
        const label = editing ? 'Зберегти зміни' : 'Додати медкнижку';
        save.textContent = label;
        save.dataset.staffActionLabel = label;
    }
    if (cancel) cancel.hidden = !editing || !canManage;
    syncStaffMedicalBookDuplicateWarning();
}

function editStaffMedicalBook(certificationId) {
    const item = staffMedicalBookById.get(Number(certificationId));
    if (!item || item.status === 'revoked') return false;
    setStaffMedicalBookEditMode(item);
    markStaffProfileScopesClean(['medical']);
    document.getElementById('editMedicalIssuedAt')?.focus({ preventScroll: true });
    setStaffWorkspaceFeedback('medical', 'success', `Редагування запису #${item.id}.`);
    return true;
}

function cancelStaffMedicalBookEdit() {
    setStaffMedicalBookEditMode();
    markStaffProfileScopesClean(['medical']);
    setStaffWorkspaceFeedback('medical');
}
function renderStaffDocuments(rows = []) {
    syncStaffMedicalDocumentOptions(rows);
    const view = currentStaffWorkspaceView('documents');
    rows = rows.filter(doc => view === 'archive' ? doc.status === 'archived' : doc.status !== 'archived');
    staffDocumentMetaById = new Map(rows.map(doc => [Number(doc.id), { ...doc }]));
    if (!rows.length) return renderStaffWorkspaceState('documents', 'empty', view === 'archive' ? 'Архів документів порожній.' : 'Документи ще не додані.');
    return rows.map(doc => {
        const title = doc.title || doc.original_name || 'Документ';
        const type = STAFF_DOCUMENT_TYPE_LABELS[doc.document_type] || doc.document_type || 'Документ';
        const fileFormat = String(doc.file_ext || '').replace(/^\./, '').toUpperCase();
        const status = STAFF_DOCUMENT_STATUS_LABELS[doc.status] || doc.status || 'Активний';
        const uploaded = `Завантажив: ${doc.uploaded_by || 'не вказано'}${doc.created_at ? ` · ${formatStaffDateValue(doc.created_at)}` : ''}`;
        const validity = [
            doc.issued_at ? `видано ${formatStaffDateValue(doc.issued_at)}` : '',
            doc.expires_at ? `діє до ${formatStaffDateValue(doc.expires_at)}` : ''
        ].filter(Boolean).join(' · ');
        const archiveAudit = doc.status === 'archived'
            ? `До архіву: ${doc.archived_at ? formatStaffDateValue(doc.archived_at) : 'дату не вказано'}${doc.archived_by ? ` · ${doc.archived_by}` : ''}`
            : '';
        return `<article class="hr-staff-foundation-item ${staffDateTone(doc.expires_at)}" data-document-status="${escapeHtml(doc.status || 'active')}">
            <div>
                <b>${escapeHtml(title)}</b>
                <span>${escapeHtml(type)}${fileFormat ? ` · ${escapeHtml(fileFormat)}` : ''} · ${escapeHtml(formatStaffFileSize(doc.file_size))} · ${escapeHtml(status)}</span>
                <span>${escapeHtml(uploaded)}</span>
                ${validity ? `<span>${escapeHtml(validity)}</span>` : ''}
                ${doc.notes ? `<span>${escapeHtml(doc.notes)}</span>` : ''}
                ${archiveAudit ? `<span>${escapeHtml(archiveAudit)}</span>` : ''}
            </div>
            <div class="hr-staff-foundation-actions">
                ${doc.preview_url ? `<button type="button" class="btn-secondary hr-staff-action hr-staff-action--secondary" onclick="previewStaffDocument(${Number(doc.id)}, this)">Переглянути</button>` : ''}
                <button type="button" class="btn-secondary hr-staff-action hr-staff-action--secondary" onclick="downloadStaffDocument(${Number(doc.id)}, 'staff-document', this)">Завантажити</button>
                ${doc.status === 'archived'
                    ? `<button type="button" class="btn-secondary hr-staff-action hr-staff-action--secondary" onclick="restoreStaffDocument(${Number(doc.id)}, this)">Відновити</button>`
                    : `<button type="button" class="btn-secondary hr-staff-action hr-staff-action--secondary" onclick="archiveStaffDocument(${Number(doc.id)}, this)">До архіву</button>`}
            </div>
        </article>`;
    }).join('');
}

function renderStaffMedicalBook(rows = []) {
    staffMedicalBookRows = rows.map(item => ({ ...item }));
    staffMedicalBookById = new Map(staffMedicalBookRows.map(item => [Number(item.id), item]));
    syncStaffMedicalBookDuplicateWarning();
    if (!rows.length) return renderStaffWorkspaceState('medical', 'empty');
    return rows.map(item => {
        const status = String(item.status || 'active');
        const statusLabel = STAFF_MEDICAL_BOOK_STATUS_LABELS[status] || status;
        const dates = [
            item.issued_at ? `видано ${formatStaffDateValue(item.issued_at)}` : '',
            item.expires_at ? `діє до ${formatStaffDateValue(item.expires_at)}` : ''
        ].filter(Boolean).join(' · ');
        const documentText = item.document_title ? `Документ: ${item.document_title}` : 'Документ не привʼязано';
        const actions = status === 'revoked'
            ? ''
            : `<div class="hr-staff-foundation-actions">
                <button type="button" class="btn-secondary hr-staff-action hr-staff-action--secondary" onclick="editStaffMedicalBook(${Number(item.id)})">Редагувати</button>
                <button type="button" class="btn-danger hr-staff-action hr-staff-action--danger" onclick="revokeStaffMedicalBook(${Number(item.id)}, this)">Видалити запис</button>
            </div>`;
        return `<article class="hr-staff-foundation-item ${staffDateTone(item.expires_at)} ${status === 'revoked' ? 'is-revoked' : ''}" data-medical-book-id="${Number(item.id)}" data-medical-book-status="${escapeHtml(status)}">
            <div>
                <div class="hr-medical-book-title"><b>Медкнижка</b><span class="hr-medical-book-badge is-${escapeHtml(status)}">${escapeHtml(statusLabel)}</span></div>
                <span>${escapeHtml(dates || 'Дати не вказано')}</span>
                <span>${escapeHtml(documentText)}</span>
                ${item.notes ? `<span>${escapeHtml(item.notes)}</span>` : ''}
            </div>
            ${actions}
        </article>`;
    }).join('');
}
function staffResourceSourceText(item = {}) {
    if (item.resource_kind === 'warehouse_stock') {
        return `Склад · ${item.warehouse_stock_name || item.title || 'Позиція'}${item.warehouse_stock_id ? ` · ID ${item.warehouse_stock_id}` : ''}`;
    }
    if (item.resource_kind === 'costume') {
        return `Костюм · ${item.costume_name || item.title || 'Позиція'}${item.costume_id ? ` · ID ${item.costume_id}` : ''}`;
    }
    return 'Ручний запис HR';
}

function staffResourceTerminalActionLabel(status) {
    if (status === 'returned') return 'Повернуто';
    if (status === 'lost') return 'Позначено втраченим';
    if (status === 'written_off') return 'Списано';
    return 'Видано';
}

function staffResourceTransitionConsequences(item = {}, targetStatus) {
    const source = item.resource_kind;
    if (targetStatus === 'returned') {
        if (source === 'warehouse_stock') return 'Кількість буде повернена на склад і буде створено один складський рух повернення.';
        if (source === 'costume') return 'Костюм буде звільнено та знову стане доступним для видачі.';
        return 'Ручний запис буде закрито як повернений.';
    }
    if (targetStatus === 'lost') {
        if (source === 'warehouse_stock') return 'Кількість не повернеться на склад і нового складського руху не буде.';
        if (source === 'costume') return 'Костюм залишиться недоступним для повторної видачі.';
        return 'Ручний запис буде закрито як втрачений.';
    }
    if (source === 'warehouse_stock') return 'Кількість не повернеться на склад і нового складського руху не буде.';
    if (source === 'costume') return 'Костюм буде переведено у стан «retired» і зникне зі списку доступних для видачі.';
    return 'Ручний запис буде закрито як списаний.';
}

function renderStaffResourceActions(item = {}, options = {}) {
    const detailAction = options.includeDetails === false
        ? ''
        : `<button type="button" class="btn-secondary hr-staff-action hr-staff-action--secondary" onclick="showStaffResourceDetails(${Number(item.id)}, this)">Деталі</button>`;
    if (item.status !== 'issued') return detailAction;
    return `${detailAction}
        <button type="button" class="btn-secondary hr-staff-action hr-staff-action--secondary" onclick="returnStaffResource(${Number(item.id)}, this)">Повернути</button>
        <button type="button" class="btn-secondary hr-staff-action hr-staff-action--warning" onclick="transitionStaffResourceStatus(${Number(item.id)}, 'lost', this)">Втрачено</button>
        <button type="button" class="btn-danger hr-staff-action hr-staff-action--danger" onclick="transitionStaffResourceStatus(${Number(item.id)}, 'written_off', this)">Списати</button>`;
}

function renderStaffResources(rows = []) {
    const view = currentStaffWorkspaceView('resources');
    const visibleRows = rows.filter(item => view === 'history'
        ? ['returned', 'lost', 'written_off'].includes(item.status)
        : item.status === 'issued');
    staffResourceById = new Map(rows.map(item => [Number(item.id), { ...item }]));
    if (!visibleRows.length) {
        return renderStaffWorkspaceState('resources', 'empty', view === 'history'
            ? 'Історія ресурсів порожня.'
            : 'Немає активних виданих ресурсів.');
    }
    return visibleRows.map(item => {
        const kind = STAFF_RESOURCE_KIND_LABELS[item.resource_kind] || item.resource_kind || 'Ресурс';
        const status = String(item.status || 'issued');
        const statusLabel = STAFF_RESOURCE_STATUS_LABELS[status] || status;
        const due = item.due_return_at ? `Повернути до ${formatStaffDateValue(item.due_return_at)}` : 'Без строку повернення';
        const terminalAudit = status === 'issued'
            ? ''
            : `${staffResourceTerminalActionLabel(status)}${item.returned_at ? ` · ${formatStaffDateValue(item.returned_at)}` : ''}${item.returned_by ? ` · ${item.returned_by}` : ''}`;
        const issueAudit = `Видано${item.issued_at ? ` · ${formatStaffDateValue(item.issued_at)}` : ''}${item.issued_by ? ` · ${item.issued_by}` : ''}`;
        const tone = status === 'issued' ? staffDateTone(item.due_return_at) : '';
        return `<article class="hr-staff-foundation-item hr-resource-card is-${escapeHtml(status)} ${tone}" data-resource-id="${Number(item.id)}" data-resource-status="${escapeHtml(status)}">
            <div class="hr-resource-card-main">
                <div class="hr-resource-card-title"><b>${escapeHtml(item.title || 'Ресурс')}</b><span class="hr-resource-status-badge is-${escapeHtml(status)}">${escapeHtml(statusLabel)}</span></div>
                <span>${escapeHtml(kind)} · ${escapeHtml(item.quantity || 1)} шт. · ${escapeHtml(staffResourceSourceText(item))}</span>
                <span>${escapeHtml(due)}</span>
                <span>${escapeHtml(issueAudit)}</span>
                ${terminalAudit ? `<span>${escapeHtml(terminalAudit)}</span>` : ''}
            </div>
            <div class="hr-staff-foundation-actions">${renderStaffResourceActions(item)}</div>
        </article>`;
    }).join('');
}

function closeStaffResourceDetails(options = {}) {
    document.getElementById('staffResourceDetailOverlay')?.remove();
    const restoreFocus = staffResourceDetailRestoreFocus;
    staffResourceDetailRestoreFocus = null;
    if (options.restoreFocus !== false && restoreFocus?.isConnected) {
        window.setTimeout(() => restoreFocus?.isConnected && restoreFocus.focus({ preventScroll: true }), 0);
    }
}

function showStaffResourceDetails(assignmentId, button = null) {
    const item = staffResourceById.get(Number(assignmentId));
    if (!item) {
        setStaffWorkspaceFeedback('resources', 'error', 'Не вдалося відкрити деталі ресурсу. Оновіть секцію.');
        return false;
    }
    closeStaffResourceDetails({ restoreFocus: false });
    staffResourceDetailRestoreFocus = button || document.activeElement || null;
    const status = String(item.status || 'issued');
    const statusLabel = STAFF_RESOURCE_STATUS_LABELS[status] || status;
    const issueMovement = item.warehouse_issue_movement_id ? `#${item.warehouse_issue_movement_id}` : '—';
    const returnMovement = item.warehouse_return_movement_id ? `#${item.warehouse_return_movement_id}` : '—';
    const overlay = document.createElement('div');
    overlay.id = 'staffResourceDetailOverlay';
    overlay.className = 'candidate-detail-overlay hr-resource-detail-overlay';
    overlay.style.zIndex = '31000';
    overlay.innerHTML = `<div class="candidate-detail-modal hr-resource-detail-modal" role="dialog" aria-modal="true" aria-labelledby="staffResourceDetailTitle">
        <div class="candidate-detail-head">
            <div>
                <div class="candidate-detail-kicker">Журнал виданого ресурсу · #${Number(item.id)}</div>
                <h3 id="staffResourceDetailTitle">${escapeHtml(item.title || 'Ресурс')}</h3>
                <p><span class="hr-resource-status-badge is-${escapeHtml(status)}">${escapeHtml(statusLabel)}</span></p>
            </div>
            <button type="button" class="candidate-detail-close" aria-label="Закрити деталі ресурсу">×</button>
        </div>
        <dl class="hr-resource-detail-grid">
            <div><dt>Тип і джерело</dt><dd>${escapeHtml(staffResourceSourceText(item))}</dd></div>
            <div><dt>Кількість</dt><dd>${escapeHtml(item.quantity || 1)} шт.</dd></div>
            <div><dt>Видано</dt><dd>${escapeHtml(item.issued_at ? formatStaffDateValue(item.issued_at) : '—')}</dd></div>
            <div><dt>Повернути до</dt><dd>${escapeHtml(item.due_return_at ? formatStaffDateValue(item.due_return_at) : '—')}</dd></div>
            <div><dt>${status === 'returned' ? 'Прийнято' : status === 'issued' ? 'Завершення' : 'Закрито'}</dt><dd>${escapeHtml(item.returned_at ? formatStaffDateValue(item.returned_at) : '—')}</dd></div>
            <div><dt>Видав</dt><dd>${escapeHtml(item.issued_by || '—')}</dd></div>
            <div><dt>${status === 'returned' ? 'Прийняв' : 'Закрив запис'}</dt><dd>${escapeHtml(item.returned_by || '—')}</dd></div>
            <div><dt>Рух видачі</dt><dd>${escapeHtml(issueMovement)}</dd></div>
            <div><dt>Рух повернення</dt><dd>${escapeHtml(returnMovement)}</dd></div>
            <div class="is-wide"><dt>Нотатки</dt><dd>${escapeHtml(item.notes || '—')}</dd></div>
        </dl>
        <div class="hr-resource-detail-actions">${renderStaffResourceActions(item, { includeDetails: false })}</div>
    </div>`;
    overlay.querySelector('.candidate-detail-close')?.addEventListener('click', () => closeStaffResourceDetails());
    overlay.addEventListener('click', event => {
        if (event.target === overlay) closeStaffResourceDetails();
    });
    overlay.addEventListener('keydown', event => {
        if (event.key === 'Escape') {
            event.preventDefault();
            closeStaffResourceDetails();
        }
    });
    document.body.appendChild(overlay);
    overlay.querySelector('.candidate-detail-close')?.focus();
    return true;
}

function renderStaffOffboarding(rows = []) {
    if (!rows.length) return renderStaffFoundationEmpty('Подій завершення співпраці ще немає.');
    return rows.slice(0, 5).map(item => {
        const account = STAFF_OFFBOARDING_ACCOUNT_LABELS[item.account_action] || item.account_action || '';
        const resources = Number(item.open_resource_count || 0);
        const resourceText = resources ? ` · неповернуті ресурси: ${resources}` : '';
        return `<article class="hr-staff-foundation-item ${resources ? 'hr-staff-foundation-warning' : ''}">
            <div>
                <b>${escapeHtml(formatStaffDateValue(item.effective_date))} · ${escapeHtml(HR_POOL_LABELS[item.target_pool_status] || item.target_pool_status || '')}</b>
                <span>${escapeHtml(item.reason || 'Без причини')} · ${escapeHtml(account)}${escapeHtml(resourceText)}</span>
            </div>
        </article>`;
    }).join('');
}

function renderStaffOffboardingReadiness(payload = {}, lifecycle = null) {
    const openResources = Number(payload.open_resource_count || 0);
    const activeAccounts = Number(payload.active_account_count || 0);
    const documentAlerts = Number(payload.document_alert_count || 0);
    const outstandingPayroll = Number(payload.outstanding_payroll_installment_count || 0);
    const outstandingPayrollAmount = Number(payload.outstanding_payroll_installment_amount || 0);
    const lifecycleMetrics = lifecycle?.metrics || null;
    const futureScheduleCount = Number(lifecycleMetrics?.future_schedule_count || 0);
    const openTimeRecordCount = Number(lifecycleMetrics?.open_time_record_count || 0);
    const activeChanges = futureScheduleCount + openTimeRecordCount;
    const hasBlockers = Array.isArray(payload.disable_blockers) && payload.disable_blockers.length > 0;
    const hasPermissionBlocker = (payload.disable_blockers || []).some(item => item.block_reason === 'requires_manage_accounts');
    const blockerAlert = hasPermissionBlocker
        ? 'Автоматичне вимкнення акаунта потребує доступу manage_accounts.'
        : 'Автоматичне вимкнення акаунта заблоковано для поточного або protected-акаунта.';
    const summaryTone = openResources || documentAlerts || outstandingPayroll || hasBlockers || activeChanges ? 'is-warning' : 'is-ok';
    const resourceList = (payload.open_resources || []).slice(0, 3).map(item => {
        const due = item.due_return_at ? ` · до ${formatStaffDateValue(item.due_return_at)}` : '';
        return `<span>${escapeHtml(item.title || 'Ресурс')} · ${escapeHtml(String(item.quantity || 1))} шт.${escapeHtml(due)}</span>`;
    }).join('');
    const accountList = (payload.active_accounts || []).slice(0, 3).map(account => {
        const role = ROLE_LABELS[account.role] || account.role || 'роль не вказана';
        const flags = account.is_current_user ? ' · поточний акаунт' : (account.is_protected ? ' · protected' : '');
        return `<span>${escapeHtml(account.username || account.name || 'CRM-акаунт')} · ${escapeHtml(role)}${escapeHtml(flags)}</span>`;
    }).join('');
    const documentList = (payload.document_alerts || []).slice(0, 3).map(item => {
        const source = STAFF_OFFBOARDING_DOC_SOURCE_LABELS[item.source] || item.source || 'Документ';
        const expires = item.expires_at ? ` · до ${formatStaffDateValue(item.expires_at)}` : '';
        return `<span>${escapeHtml(source)}: ${escapeHtml(item.title || 'без назви')}${escapeHtml(expires)}</span>`;
    }).join('');
    const changeList = lifecycleMetrics
        ? `<span>Майбутніх змін: ${futureScheduleCount}. Активних тайм-записів: ${openTimeRecordCount}.</span>`
        : '<span>Стан майбутніх і активних змін поки не завантажено.</span>';
    const payrollList = outstandingPayroll
        ? `<span>Неврегульованих payroll installments: ${outstandingPayroll} · ${outstandingPayrollAmount.toLocaleString('uk-UA')} ₴.</span>`
        : '<span>Неврегульованих payroll installments немає.</span>';
    const details = [
        resourceList || '<span>Неповернутих ресурсів немає.</span>',
        accountList || '<span>Активного CRM-акаунта не знайдено.</span>',
        documentList || '<span>Критичних строків документів на 30 днів немає.</span>',
        changeList,
        payrollList
    ].join('');
    return `<div class="hr-offboarding-readiness-card ${summaryTone}">
        <div class="hr-offboarding-readiness-grid">
            <div class="${openResources ? 'is-warning' : 'is-ok'}"><b>${openResources}</b><span>ресурси</span></div>
            <div class="${activeAccounts ? 'is-info' : 'is-muted'}"><b>${activeAccounts}</b><span>акаунти</span></div>
            <div class="${documentAlerts ? 'is-warning' : 'is-ok'}"><b>${documentAlerts}</b><span>документи</span></div>
            <div class="${outstandingPayroll ? 'is-warning' : 'is-ok'}"><b>${outstandingPayroll}</b><span>payroll борги</span></div>
            <div class="${lifecycleMetrics ? (activeChanges ? 'is-warning' : 'is-ok') : 'is-muted'}"><b>${lifecycleMetrics ? activeChanges : '—'}</b><span>активні зміни</span></div>
        </div>
        <div class="hr-offboarding-readiness-detail">${details}</div>
        ${hasBlockers ? `<div class="hr-offboarding-readiness-alert">${escapeHtml(blockerAlert)}</div>` : ''}
    </div>`;
}

function getStaffOffboardingPreview() {
    const date = document.getElementById('editOffboardingDate')?.value || '';
    const reason = document.getElementById('editOffboardingReason')?.value?.trim() || '';
    const poolStatus = document.getElementById('editOffboardingPoolStatus')?.value || 'reserve';
    const accountAction = document.getElementById('editOffboardingAccountAction')?.value || 'review';
    const readiness = staffOffboardingReadiness && typeof staffOffboardingReadiness === 'object'
        ? staffOffboardingReadiness
        : null;
    const lifecycleMetrics = staffOffboardingLifecycle?.metrics || null;
    const blockers = [];
    if (!date) blockers.push('Вкажіть дату завершення співпраці.');
    if (!reason) blockers.push('Вкажіть причину завершення співпраці.');
    if (!readiness) blockers.push('Перевірку готовності не завантажено. Оновіть readiness.');

    const activeAccounts = Number(readiness?.active_account_count || 0);
    const openResources = Number(readiness?.open_resource_count || 0);
    const documentAlerts = Number(readiness?.document_alert_count || 0);
    const outstandingPayroll = Number(readiness?.outstanding_payroll_installment_count || 0);
    const outstandingPayrollAmount = Number(readiness?.outstanding_payroll_installment_amount || 0);
    const futureScheduleCount = Number(lifecycleMetrics?.future_schedule_count || 0);
    const openTimeRecordCount = Number(lifecycleMetrics?.open_time_record_count || 0);
    const needsAccountAccess = (readiness?.disable_blockers || []).some(item => item.block_reason === 'requires_manage_accounts');
    if (accountAction === 'disable' && readiness?.disable_available === false) {
        blockers.push(needsAccountAccess
            ? 'Вимкнення CRM-акаунта потребує доступу manage_accounts.'
            : 'Вибраний CRM-акаунт захищений або є поточним користувачем.');
    }
    if (outstandingPayroll > 0) {
        blockers.push(`Спочатку врегулюйте payroll installments: ${outstandingPayroll} на суму ${outstandingPayrollAmount.toLocaleString('uk-UA')} ₴.`);
    }

    const accountText = accountAction === 'disable'
        ? activeAccounts > 0
            ? `CRM-акаунтів для вимкнення: ${activeAccounts}.`
            : 'Активних CRM-акаунтів немає — дію вимкнення буде пропущено.'
        : accountAction === 'none'
            ? 'CRM-акаунти не змінюються.'
            : 'CRM-акаунти потребують ручної перевірки.';
    const consequences = [
        date
            ? `Профіль стане неактивним з ${formatStaffDateValue(date)}.`
            : 'Дата завершення ще не вказана.',
        `HR-статус після завершення: ${HR_POOL_LABELS[poolStatus] || poolStatus}.`,
        accountText,
        lifecycleMetrics
            ? `Буде прибрано майбутніх змін: ${futureScheduleCount}; активних тайм-записів: ${openTimeRecordCount}.`
            : 'Стан майбутніх та активних змін ще перевіряється.',
        openResources || documentAlerts
            ? `Попередження не блокують серверну операцію: ресурси ${openResources}, документи ${documentAlerts}.`
            : 'Ресурсів і критичних документів у readiness не знайдено.',
        outstandingPayroll
            ? `Payroll блокує завершення: ${outstandingPayroll} installments, ${outstandingPayrollAmount.toLocaleString('uk-UA')} ₴.`
            : 'Неврегульованих payroll installments немає.'
    ];
    return {
        date,
        reason,
        poolStatus,
        accountAction,
        activeAccounts,
        openResources,
        documentAlerts,
        outstandingPayroll,
        outstandingPayrollAmount,
        futureScheduleCount,
        openTimeRecordCount,
        blockers,
        consequences,
        ready: blockers.length === 0
    };
}

function updateStaffOffboardingActionState() {
    const button = document.getElementById('editOffboardingComplete');
    const summaryRoot = document.getElementById('editOffboardingConsequenceSummary');
    const statusRoot = document.getElementById('editOffboardingActionStatus');
    const preview = getStaffOffboardingPreview();
    if (summaryRoot) {
        summaryRoot.innerHTML = `<strong>Що буде змінено</strong><ul>${preview.consequences.map(item => `<li>${escapeHtml(item)}</li>`).join('')}</ul>`;
    }
    if (statusRoot) {
        statusRoot.className = `hr-offboarding-action-status ${preview.ready ? 'is-ready' : (preview.blockers.some(item => item.includes('акаунт') || item.includes('manage_accounts')) ? 'is-blocked' : '')}`.trim();
        statusRoot.textContent = preview.ready
            ? 'Готово до фінального підтвердження. Перед submit ще раз буде показано підсумок наслідків.'
            : preview.blockers.join(' ');
    }
    if (button && button.dataset.staffActionPending !== 'true') {
        button.disabled = !preview.ready;
        button.setAttribute('aria-disabled', preview.ready ? 'false' : 'true');
        button.title = preview.ready ? 'Показати фінальне підтвердження завершення співпраці' : preview.blockers.join(' ');
    }
    return preview;
}

const LIFECYCLE_SECTION_LABELS_UK = {
    onboarding: 'Готовність онбордингу',
    offboarding: 'Закриття співпраці'
};

const LIFECYCLE_ITEM_LABELS_UK = {
    candidate_approved: 'Кандидат погоджений',
    hr_card_created: 'HR-картка створена',
    department_set: 'Відділ заданий',
    role_type_set: 'Основна роль задана',
    professions_set: 'Професії задані',
    account_linked: 'CRM-акаунт привʼязаний',
    face_descriptor_added: 'Камера / Face ID налаштована',
    documents_checked: 'Документи перевірені',
    readiness_approved: 'Готовність навчання підтверджена',
    first_shift_scheduled: 'Перша зміна запланована',
    manager_assigned: 'Відповідальний за онбординг призначений',
    removed_from_future_schedule: 'Прибрано з майбутнього графіка',
    active_shifts_closed: 'Активні зміни закриті',
    payroll_closed: 'Зарплата закрита',
    account_disabled_or_unlinked: 'CRM-акаунт вимкнений або відвʼязаний',
    access_removed: 'Доступи прибрані',
    hr_status_changed: 'HR-статус змінений',
    final_note_added: 'Фінальна нотатка додана',
    documents_archived_if_applicable: 'Документи архівовані за потреби'
};

function lifecycleUiText(value = '') {
    return String(value || '')
        .replace(/Lifecycle checklist/g, 'Чекліст життєвого циклу')
        .replace(/Onboarding readiness/g, 'Готовність онбордингу')
        .replace(/Offboarding closure/g, 'Закриття співпраці')
        .replace(/Face descriptor/g, 'Face ID')
        .replace(/Readiness/g, 'Готовність навчання')
        .replace(/Future shifts/g, 'Майбутні зміни')
        .replace(/Payroll open/g, 'Незакрита зарплата')
        .replace(/Payroll/g, 'Зарплата')
        .replace(/Account/g, 'CRM-акаунт')
        .replace(/warnings/g, 'попередження')
        .replace(/warning/g, 'попередження')
        .replace(/checklist\/training/g, 'чеклістів/навчання')
        .replace(/Linked CRM account/g, 'Привʼязаний CRM-акаунт')
        .replace(/linked account/g, 'привʼязаний акаунт')
        .replace(/active linked account/gi, 'активний привʼязаний акаунт')
        .replace(/time records/g, 'тайм-рекордів')
        .replace(/payroll reports/g, 'зарплатних звітів');
}

function lifecycleUiItem(item = {}) {
    if (item.__uiNormalized) return item;
    const view = {
        ...item,
        __uiNormalized: true,
        label: LIFECYCLE_ITEM_LABELS_UK[item.key] || lifecycleUiText(item.label || item.key || 'Пункт чекліста'),
        detail: lifecycleUiText(item.detail || '')
    };
    if (view.key === 'account_linked' && !view.complete && view.status !== 'done') {
        view.severity = 'warning';
        if (view.status === 'blocked') view.status = 'missing';
        const note = 'CRM-акаунт показано як setup-пункт, не як критичний блокер без окремого бізнес-правила.';
        view.detail = view.detail ? `${view.detail} ${note}` : note;
    }
    return view;
}

function lifecycleItemApplicable(item = {}) {
    return item.applicable !== false && item.status !== 'not_applicable';
}

function lifecycleItemComplete(item = {}) {
    return item.complete === true || item.status === 'done';
}

function lifecycleItemIncomplete(item = {}) {
    return lifecycleItemApplicable(item) && !lifecycleItemComplete(item);
}

function lifecycleUiIssueCounts(items = []) {
    const applicable = items.filter(lifecycleItemApplicable);
    const incomplete = applicable.filter(lifecycleItemIncomplete);
    const blocked = incomplete.filter(item => item.severity === 'critical' || item.status === 'blocked').length;
    const warning = incomplete.filter(item => item.severity !== 'critical' && item.status !== 'blocked').length;
    return {
        total: applicable.length,
        done: applicable.filter(lifecycleItemComplete).length,
        blocked,
        warning,
        percent: applicable.length ? Math.round((applicable.filter(lifecycleItemComplete).length / applicable.length) * 100) : 100
    };
}

function lifecycleStatusLabel(status = '') {
    return {
        done: 'Готово',
        blocked: 'Блокер',
        missing: 'Потрібно',
        unknown: 'Немає даних',
        not_applicable: 'Не актуально'
    }[status] || 'Потрібно';
}

function lifecycleStatusTone(item = {}) {
    if (item.status === 'done') return 'is-ok';
    if (item.status === 'blocked' || item.severity === 'critical') return 'is-critical';
    if (item.status === 'unknown') return 'is-unknown';
    if (item.status === 'not_applicable') return 'is-muted';
    return 'is-warning';
}

function lifecycleSummaryLabel(value) {
    return value ? 'Так' : 'Ні';
}

function lifecycleActionNode(action, staffId, item = {}) {
    const id = Number(staffId);
    if (!action || !Number.isFinite(id) || id <= 0 || item.complete || item.status === 'not_applicable') return '';
    const button = (label, handler) => `<button type="button" class="hr-lifecycle-action" onclick="${handler}">${escapeHtml(label)}</button>`;
    if (action === 'profile') return button('Профіль', "activateStaffProfileTab('main').then(() => document.getElementById('editStaffName')?.focus())");
    if (action === 'documents') return button('Документи', 'focusStaffDocumentsPanel()');
    if (action === 'training') return button('Готовність навчання', `openStaffTrainingReadiness(${id})`);
    if (action === 'onboarding' && canManage) return button('Онбординг', `openStaffOnboardingAssignment(${id})`);
    if (action === 'account' && canLinkAccounts()) {
        const handler = item.key === 'account_linked'
            ? `openAccountLinkForStaff(${id}, this)`
            : `openAccountForStaff(${id}, this)`;
        return button('Акаунт', handler);
    }
    if (action === 'face') return button('Налаштувати Face ID', "showNotification('Face ID реєструється через модуль Камера / check-in.', 'info')");
    if (action === 'schedule' || action === 'attendance') return '<a class="hr-lifecycle-action" href="/staff">Графік</a>';
    if (action === 'payroll') return '<a class="hr-lifecycle-action" href="/hr#salary">Зарплата</a>';
    if (action === 'offboarding') return button('Завершення', "activateStaffProfileTab('offboarding').then(() => document.getElementById('editOffboardingReason')?.focus())");
    return '';
}

function renderLifecycleItem(item = {}, staffId) {
    const viewItem = lifecycleUiItem(item);
    const tone = lifecycleStatusTone(viewItem);
    const detail = viewItem.detail ? `<small>${escapeHtml(viewItem.detail)}</small>` : '';
    const count = viewItem.count !== null && viewItem.count !== undefined ? `<i>${escapeHtml(String(viewItem.count))}</i>` : '';
    const action = lifecycleActionNode(viewItem.action, staffId, viewItem);
    return `<article class="hr-lifecycle-item ${tone}" data-lifecycle-item="${escapeHtml(viewItem.key || '')}">
        <div class="hr-lifecycle-item-main">
            <span class="hr-lifecycle-dot" aria-hidden="true"></span>
            <div>
                <b>${escapeHtml(viewItem.label || viewItem.key || 'Пункт чекліста')}</b>
                ${detail}
            </div>
        </div>
        <div class="hr-lifecycle-item-side">
            ${count}
            <span>${escapeHtml(lifecycleStatusLabel(viewItem.status))}</span>
            ${action}
        </div>
    </article>`;
}

function renderLifecycleSection(section = {}, staffId) {
    const items = (Array.isArray(section.items) ? section.items : []).map(lifecycleUiItem);
    const counts = lifecycleUiIssueCounts(items);
    const sectionTone = counts.blocked ? 'is-critical' : counts.warning ? 'is-warning' : counts.total ? 'is-ok' : 'is-muted';
    const sectionLabel = LIFECYCLE_SECTION_LABELS_UK[section.key] || lifecycleUiText(section.label || section.key || 'Lifecycle');
    return `<section class="hr-lifecycle-section ${sectionTone}">
        <div class="hr-lifecycle-section-head">
            <div>
                <strong>${escapeHtml(sectionLabel)}</strong>
                <span>${counts.done}/${counts.total} · ${counts.percent}%</span>
            </div>
            <em>${counts.blocked ? `${counts.blocked} блок.` : counts.warning ? `${counts.warning} увага` : counts.total ? 'ok' : 'не актуально'}</em>
        </div>
        <div class="hr-lifecycle-items">${items.map(item => renderLifecycleItem(item, staffId)).join('')}</div>
    </section>`;
}

function renderStaffLifecycleChecklist(payload = {}) {
    const staffId = Number(payload.staff?.id || activeEditStaffId() || 0);
    const summary = payload.summary || {};
    const metrics = payload.metrics || {};
    const sections = Array.isArray(payload.sections) ? payload.sections : [];
    const uiSections = sections.map(section => ({
        ...section,
        items: (Array.isArray(section.items) ? section.items : []).map(lifecycleUiItem)
    }));
    const uiItems = uiSections.flatMap(section => section.items);
    const uiCounts = lifecycleUiIssueCounts(uiItems);
    const scheduleBlockingItems = uiSections
        .filter(section => section.key !== 'offboarding')
        .flatMap(section => section.items)
        .filter(item => lifecycleItemIncomplete(item) && (item.severity === 'critical' || item.status === 'blocked'));
    const readyForSchedule = summary.ready_for_schedule === true || scheduleBlockingItems.length === 0;
    const offboardingStarted = summary.offboarding_started === true || payload.staff?.is_active === false || Boolean(payload.staff?.termination_date);
    const findingHtml = (payload.findings || []).map(finding =>
        `<div class="hr-lifecycle-finding">${escapeHtml(lifecycleUiText(finding.message || finding.key || ''))}</div>`
    ).join('');
    return `<div class="hr-lifecycle-summary">
        <div class="hr-lifecycle-summary-card ${uiCounts.blocked ? 'is-critical' : uiCounts.warning ? 'is-warning' : 'is-ok'}" title="Блокер життєвого циклу — критична операційна перешкода. CRM без окремого правила тут не рахується як блокер.">
            <b>${Number(uiCounts.blocked || 0)}</b>
            <span>блокери</span>
        </div>
        <div class="hr-lifecycle-summary-card">
            <b>${Number(uiCounts.warning || 0)}</b>
            <span>попередження</span>
        </div>
        <div class="hr-lifecycle-summary-card ${readyForSchedule ? 'is-ok' : 'is-warning'}" title="Готовність до графіка рахується окремо від заповнення профілю і прогресу навчання.">
            <b>${escapeHtml(lifecycleSummaryLabel(readyForSchedule))}</b>
            <span>готовий до графіка</span>
        </div>
        <div class="hr-lifecycle-summary-card ${offboardingStarted ? (summary.ready_for_offboarding ? 'is-ok' : 'is-warning') : 'is-muted'}" title="Для активного працівника без запущеного завершення співпраці це не поточна проблема.">
            <b>${offboardingStarted ? escapeHtml(lifecycleSummaryLabel(summary.ready_for_offboarding)) : 'Не актуально'}</b>
            <span>${offboardingStarted ? 'закриття співпраці' : 'завершення не почато'}</span>
        </div>
    </div>
    <div class="hr-lifecycle-metrics">
        <span title="Активні CRM-акаунти, привʼязані до працівника.">CRM-акаунти: ${Number(metrics.active_account_count || 0)}</span>
        <span title="Камера / Face ID: записи у staff_face_descriptors.">Face ID: ${Number(metrics.face_descriptor_count || 0)}</span>
        <span title="Готовність навчання: прогрес професійних чеклістів.">Навчання: ${Number(metrics.readiness_percent || 0)}%</span>
        <span title="Майбутні записи у staff_schedule/hr_shifts.">Майбутні зміни: ${Number(metrics.future_schedule_count || 0)}</span>
        <span title="Незакриті payroll reports.">Незакрита зарплата: ${Number(metrics.open_payroll_count || 0)}</span>
    </div>
    <details class="hr-lifecycle-metrics-help">
        <summary>Пояснення метрик готовності</summary>
        <p><b>Заповнення профілю</b> — базові поля картки. <b>Навчання</b> — відсоток чеклістів. <b>Життєвий цикл</b> — операційні кроки процесу: графік, документи, доступи, зарплата і завершення співпраці.</p>
    </details>
    <div class="hr-lifecycle-sections">${uiSections.map(section => renderLifecycleSection(section, staffId)).join('')}</div>
    ${findingHtml ? `<div class="hr-lifecycle-findings">${findingHtml}</div>` : ''}`;
}

async function loadStaffLifecycleChecklist(staffId, options = {}) {
    const root = document.getElementById('editStaffLifecycleChecklist');
    const id = Number(staffId);
    if (!root || !Number.isFinite(id) || id <= 0) return { success: false, error: 'missing_staff_id' };
    if (!canManage) {
        root.innerHTML = renderStaffFoundationEmpty('Чекліст життєвого циклу доступний тільки HR/керівнику.');
        return { success: false, error: 'restricted' };
    }
    const seq = ++staffLifecycleLoadSeq;
    root.innerHTML = 'Чекліст життєвого циклу завантажується...';
    const data = await hrFetch(`/staff/${id}/lifecycle-checklist`).catch(() => null);
    if (seq !== staffLifecycleLoadSeq || !isActiveStaffEditLoad(id)) return data || { success: false, stale: true };
    root.innerHTML = data?.success
        ? renderStaffLifecycleChecklist(data.data || {})
        : renderStaffFoundationEmpty(data?.error || 'Не вдалося завантажити чекліст життєвого циклу.');
    return data || { success: false };
}

function setStaffFoundationLoading() {
    const docs = document.getElementById('editStaffDocuments');
    const medical = document.getElementById('editMedicalBookList');
    const resources = document.getElementById('editStaffResources');
    const offboarding = document.getElementById('editStaffOffboarding');
    const readiness = document.getElementById('editOffboardingReadiness');
    const roles = document.getElementById('editStaffRoleAssignments');
    const payroll = document.getElementById('editPayrollSchemeSummary');
    const payrollProfiles = document.getElementById('editStaffPayrollProfiles');
    const payrollPreview = document.getElementById('editStaffPayrollProfilePreview');
    if (docs) docs.innerHTML = 'Документи завантажуються...';
    if (medical) medical.innerHTML = 'Медкнижка завантажується...';
    if (resources) resources.innerHTML = 'Ресурси завантажуються...';
    if (offboarding) offboarding.innerHTML = 'Завершення співпраці завантажується...';
    if (readiness) readiness.innerHTML = 'Перевірка готовності завантажується...';
    if (roles) roles.innerHTML = 'Ролі завантажуються...';
    if (payroll) payroll.textContent = 'Зарплатна схема завантажується...';
    if (payrollProfiles) payrollProfiles.innerHTML = '<div class="hr-payroll-profile-empty-state">Зарплатні профілі завантажуються...</div>';
    if (payrollPreview) payrollPreview.innerHTML = '<div class="hr-payroll-profile-empty-state">Payroll preview ще не пораховано.</div>';
}

async function loadStaffFoundation(staffId) {
    const docsRoot = document.getElementById('editStaffDocuments');
    const medicalRoot = document.getElementById('editMedicalBookList');
    const resourcesRoot = document.getElementById('editStaffResources');
    const offboardingRoot = document.getElementById('editStaffOffboarding');
    const readinessRoot = document.getElementById('editOffboardingReadiness');
    if (!docsRoot && !medicalRoot && !resourcesRoot && !offboardingRoot && !readinessRoot) return;
    const seq = ++staffFoundationLoadSeq;
    if (!canManage) {
        const restricted = renderStaffFoundationEmpty('Доступ до HR-документів і завершення співпраці має тільки HR/керівник.');
        if (docsRoot) docsRoot.innerHTML = restricted;
        if (medicalRoot) medicalRoot.innerHTML = restricted;
        if (resourcesRoot) resourcesRoot.innerHTML = restricted;
        if (offboardingRoot) offboardingRoot.innerHTML = restricted;
        if (readinessRoot) readinessRoot.innerHTML = restricted;
        return;
    }
    setStaffFoundationLoading();
    const [docs, medical, resources, offboarding, readiness] = await Promise.all([
        hrFetch(`/staff/${staffId}/documents`).catch(() => null),
        hrFetch(`/staff/${staffId}/medical-book`).catch(() => null),
        hrFetch(`/staff/${staffId}/resources?view=${currentStaffWorkspaceView('resources')}`).catch(() => null),
        hrFetch(`/staff/${staffId}/offboarding`).catch(() => null),
        hrFetch(`/staff/${staffId}/offboarding-readiness`).catch(() => null)
    ]);
    if (seq !== staffFoundationLoadSeq || !isActiveStaffEditLoad(staffId)) return;
    staffOffboardingReadiness = readiness?.success ? (readiness.data || null) : null;
    if (docsRoot) docsRoot.innerHTML = docs?.success ? renderStaffDocuments(docs.data || []) : renderStaffFoundationEmpty(docs?.error || 'Не вдалося завантажити документи.');
    if (medicalRoot) medicalRoot.innerHTML = medical?.success ? renderStaffMedicalBook(medical.data || []) : renderStaffFoundationEmpty(medical?.error || 'Не вдалося завантажити медкнижку.');
    if (resourcesRoot) resourcesRoot.innerHTML = resources?.success ? renderStaffResources(resources.data || []) : renderStaffFoundationEmpty(resources?.error || 'Не вдалося завантажити ресурси.');
    if (offboardingRoot) offboardingRoot.innerHTML = offboarding?.success ? renderStaffOffboarding(offboarding.data || []) : renderStaffFoundationEmpty(offboarding?.error || 'Не вдалося завантажити події завершення співпраці.');
    if (readinessRoot) readinessRoot.innerHTML = readiness?.success ? renderStaffOffboardingReadiness(readiness.data || {}) : renderStaffFoundationEmpty(readiness?.error || 'Не вдалося завантажити перевірку готовності.');
}

async function loadStaffRoleAssignments(staffId) {
    const root = document.getElementById('editStaffRoleAssignments');
    if (!root || !staffId) return;
    const seq = ++staffRoleAssignmentsLoadSeq;
    root.innerHTML = 'Ролі завантажуються...';
    const data = await hrFetch(`/staff/${staffId}/role-assignments`).catch(() => null);
    if (seq !== staffRoleAssignmentsLoadSeq || !isActiveStaffEditLoad(staffId)) return data;
    root.innerHTML = data?.success
        ? renderStaffRoleAssignments(data.data || [])
        : renderStaffFoundationEmpty(data?.error || 'Не вдалося завантажити ролі.');
}

async function saveStaffRoleAssignments(button = null) {
    return runStaffProfileAction(button || 'editRoleAssignmentsSave', {
        loadingLabel: 'Збереження…',
        successLabel: 'Збережено',
        errorLabel: 'Помилка'
    }, async () => {
        const staffId = activeEditStaffId();
        if (!staffId) return { success: false, error: 'missing_staff_id' };
        const assignments = readStaffRoleAssignmentRows();
        if (!assignments.length) {
            showNotification('Немає ролей для збереження', 'error');
            return { success: false, error: 'empty_role_assignments' };
        }
        const data = await hrFetch(`/staff/${staffId}/role-assignments`, {
            method: 'PUT',
            body: {
                primary_role: document.getElementById('editRoleType')?.value || assignments[0].profession_key,
                assignments
            }
        });
        if (!data?.success) {
            showNotification(data?.error || 'Не вдалося оновити ролі', 'error');
            return data || { success: false };
        }
        await loadStaffRoleAssignments(staffId);
        markStaffProfileScopesClean(['roles']);
        showNotification('Ролі та допуски оновлено', 'success');
        return data;
    });
}

function setPayrollSchemeForm(payload = {}) {
    const scheme = payload.active_scheme || payload.activeScheme || null;
    const fallbackRate = Number(payload.fallback_hourly_rate ?? payload.fallbackHourlyRate ?? document.getElementById('editHourlyRate')?.value ?? 0);
    const fallbackUnit = normalizeStaffRateUnit(payload.fallback_rate_unit ?? payload.fallbackRateUnit ?? currentEditRateUnit());
    const type = scheme?.scheme_type || scheme?.schemeType || (fallbackUnit === 'day' ? 'per_shift' : 'hourly');
    const typeSelect = document.getElementById('editPayrollSchemeType');
    const amountInput = document.getElementById('editPayrollSchemeAmount');
    const titleInput = document.getElementById('editPayrollSchemeTitle');
    const fromInput = document.getElementById('editPayrollSchemeEffectiveFrom');
    const toInput = document.getElementById('editPayrollSchemeEffectiveTo');
    const summary = document.getElementById('editPayrollSchemeSummary');
    if (typeSelect) typeSelect.value = type;
    if (amountInput) amountInput.value = String(payrollSchemeAmount(scheme || { scheme_type: type, config: {} }, fallbackRate) || 0);
    setPayrollHybridForm(scheme?.config || {}, fallbackRate);
    setPayrollMonthlyNormForm(scheme?.config || {}, type);
    updatePayrollAdvancedVisibility();
    if (titleInput) titleInput.value = scheme?.title || PAYROLL_SCHEME_LABELS[type] || '';
    if (fromInput) fromInput.value = staffDateInputValue(scheme?.effective_from || scheme?.effectiveFrom);
    if (toInput) toInput.value = staffDateInputValue(scheme?.effective_to || scheme?.effectiveTo);
    if (summary) {
        summary.textContent = scheme
            ? `Активна: ${PAYROLL_SCHEME_LABELS[type] || type} · ${scheme.title || 'без назви'}${scheme.effective_from ? ` · з ${formatStaffDateValue(scheme.effective_from)}` : ''}${scheme.effective_to ? ` · до ${formatStaffDateValue(scheme.effective_to)}` : ''}`
            : `Активної схеми немає. За замовченням використовується HR-ставка: ${fmtMoney(fallbackRate)} / ${staffRateUnitSuffix(fallbackUnit)}.`;
    }
}

async function loadStaffPayrollScheme(staffId) {
    const summary = document.getElementById('editPayrollSchemeSummary');
    if (!summary || !staffId) return;
    const seq = ++staffPayrollSchemeLoadSeq;
    summary.textContent = 'Зарплатна схема завантажується...';
    const data = await hrFetch(`/staff/${staffId}/payroll-scheme`).catch(() => null);
    if (seq !== staffPayrollSchemeLoadSeq || !isActiveStaffEditLoad(staffId)) return data;
    if (!data?.success) {
        summary.textContent = data?.error || 'Не вдалося завантажити зарплатну схему.';
        return;
    }
    setPayrollSchemeForm(data.data || {});
}

function currentStaffPayrollProfessionKeys() {
    const primary = normalizeProfessionKey(document.getElementById('editRoleType')?.value || '');
    const secondary = typeof readStaffSecondaryProfessionSelection === 'function'
        ? readStaffSecondaryProfessionSelection()
        : [];
    return normalizeProfessionList([primary, ...secondary]).filter(Boolean);
}

function refreshStaffPayrollProfilesFromCurrentForm() {
    const root = document.getElementById('editStaffPayrollProfiles');
    if (!root || Number(staffPayrollProfileState.staffId || 0) !== Number(activeEditStaffId() || 0)) return;
    renderStaffPayrollProfiles();
}

function staffPayrollProfileById(profileId, rows = staffPayrollProfileState.profiles) {
    const id = Number(profileId);
    return rows.find(profile => Number(profile.id) === id) || null;
}

function staffPayrollProfileProfessionKey(profile = {}) {
    return normalizeProfessionKey(profile.professionKey || profile.profession_key);
}

function staffPayrollAssignmentProfessionKey(assignment = {}) {
    return normalizeProfessionKey(assignment.professionKey || assignment.profession_key);
}

function staffPayrollAssignmentProfileId(assignment = {}) {
    return Number(assignment.profileId || assignment.profile_id || 0);
}

function staffPayrollAssignmentKind(assignment = {}) {
    return String(assignment.assignmentKind || assignment.assignment_kind || 'explicit');
}

function staffPayrollAssignmentFrom(assignment = {}) {
    return staffDateInputValue(assignment.effectiveFrom || assignment.effective_from);
}

function staffPayrollAssignmentTo(assignment = {}) {
    return staffDateInputValue(assignment.effectiveTo || assignment.effective_to);
}

function staffPayrollAssignmentIsActiveOn(assignment = {}, date = todayStr()) {
    const from = staffPayrollAssignmentFrom(assignment);
    const to = staffPayrollAssignmentTo(assignment);
    return (!from || from <= date) && (!to || to >= date);
}

function staffPayrollAssignmentIsFutureOrActive(assignment = {}, fromDate = todayStr()) {
    const to = staffPayrollAssignmentTo(assignment);
    return !to || to >= fromDate;
}

function previousDateString(dateStr) {
    const date = new Date(`${dateStr}T00:00:00`);
    if (Number.isNaN(date.getTime())) return '';
    date.setDate(date.getDate() - 1);
    return formatDate(date);
}

function addDaysString(dateStr, amount = 0) {
    const date = new Date(`${dateStr}T00:00:00`);
    if (Number.isNaN(date.getTime())) return dateStr;
    date.setDate(date.getDate() + Number(amount || 0));
    return formatDate(date);
}

function staffPayrollAssignmentPayloadFromExisting(assignment = {}, overrides = {}) {
    return {
        id: assignment.id,
        professionKey: overrides.professionKey || staffPayrollAssignmentProfessionKey(assignment),
        profileId: overrides.profileId || staffPayrollAssignmentProfileId(assignment),
        assignmentKind: overrides.assignmentKind || staffPayrollAssignmentKind(assignment),
        effectiveFrom: overrides.effectiveFrom || staffPayrollAssignmentFrom(assignment),
        effectiveTo: Object.prototype.hasOwnProperty.call(overrides, 'effectiveTo')
            ? overrides.effectiveTo
            : (staffPayrollAssignmentTo(assignment) || null)
    };
}

function staffPayrollPlanAssignmentReplacement(professionKey, effectiveFrom = todayStr()) {
    const key = normalizeProfessionKey(professionKey);
    const from = staffDateInputValue(effectiveFrom) || todayStr();
    const updates = [];
    const removeAssignmentIds = [];
    staffPayrollProfileState.assignments
        .filter(assignment => staffPayrollAssignmentProfessionKey(assignment) === key)
        .filter(assignment => staffPayrollAssignmentIsFutureOrActive(assignment, from))
        .forEach(assignment => {
            const currentFrom = staffPayrollAssignmentFrom(assignment);
            const previous = previousDateString(from);
            if (currentFrom && currentFrom < from && previous >= currentFrom) {
                updates.push(staffPayrollAssignmentPayloadFromExisting(assignment, { effectiveTo: previous }));
            } else if (assignment.id) {
                removeAssignmentIds.push(Number(assignment.id));
            }
        });
    return { updates, removeAssignmentIds };
}

function staffPayrollActiveAssignmentForProfession(professionKey, date = todayStr()) {
    const key = normalizeProfessionKey(professionKey);
    return staffPayrollProfileState.assignments
        .filter(assignment => staffPayrollAssignmentProfessionKey(assignment) === key)
        .filter(assignment => staffPayrollAssignmentIsActiveOn(assignment, date))
        .sort((a, b) => {
            const kindDelta = (staffPayrollAssignmentKind(b) === 'temporary' ? 1 : 0) - (staffPayrollAssignmentKind(a) === 'temporary' ? 1 : 0);
            if (kindDelta) return kindDelta;
            return staffPayrollAssignmentFrom(b).localeCompare(staffPayrollAssignmentFrom(a)) || Number(b.id || 0) - Number(a.id || 0);
        })[0] || null;
}

function staffPayrollDefaultProfileForProfession(professionKey) {
    const key = normalizeProfessionKey(professionKey);
    return staffPayrollProfileState.profiles.find(profile =>
        staffPayrollProfileProfessionKey(profile) === key
        && (profile.profileKind || profile.profile_kind) === 'shared'
        && profile.status === 'active'
        && (profile.isDefaultForProfession || profile.is_default_for_profession)
    ) || null;
}

function staffPayrollEffectiveProfileForProfession(professionKey, date = todayStr()) {
    const assignment = staffPayrollActiveAssignmentForProfession(professionKey, date);
    const assignedProfile = assignment ? staffPayrollProfileById(staffPayrollAssignmentProfileId(assignment)) : null;
    const defaultProfile = staffPayrollDefaultProfileForProfession(professionKey);
    return {
        assignment,
        profile: assignedProfile || defaultProfile,
        defaultProfile,
        source: assignment
            ? (staffPayrollAssignmentKind(assignment) === 'temporary' ? 'temporary' : 'explicit')
            : (defaultProfile ? 'inherited' : 'unresolved')
    };
}

function staffPayrollProfileSourceLabel(source = '') {
    return {
        inherited: 'успадковано default',
        explicit: 'explicit profile',
        temporary: 'тимчасове призначення',
        unresolved: 'не визначено'
    }[source] || source || '—';
}

function staffPayrollAssignableProfilesForProfession(professionKey) {
    const key = normalizeProfessionKey(professionKey);
    const staffId = Number(activeEditStaffId());
    return staffPayrollProfileState.profiles
        .filter(profile => staffPayrollProfileProfessionKey(profile) === key)
        .filter(profile => profile.status !== 'archived')
        .filter(profile => {
            const kind = profile.profileKind || profile.profile_kind;
            if (kind !== 'personal') return true;
            return Number(profile.ownerStaffId || profile.owner_staff_id || 0) === staffId;
        })
        .sort((a, b) => {
            const defaultDelta = Number(Boolean(b.isDefaultForProfession || b.is_default_for_profession)) - Number(Boolean(a.isDefaultForProfession || a.is_default_for_profession));
            if (defaultDelta) return defaultDelta;
            const kindDelta = String(a.profileKind || a.profile_kind || '').localeCompare(String(b.profileKind || b.profile_kind || ''));
            if (kindDelta) return kindDelta;
            return String(a.title || '').localeCompare(String(b.title || ''), 'uk');
        });
}

function staffPayrollProfileSelectOptions(professionKey) {
    return staffPayrollAssignableProfilesForProfession(professionKey).map(profile => {
        const version = payrollProfileCurrentVersion(profile);
        const owner = payrollProfileOwnerLabel(profile);
        const kind = profile.profileKind || profile.profile_kind || 'shared';
        const rate = version ? ` · ${payrollProfileMoney(version.defaultRate ?? version.default_rate)} ${payrollProfileRateUnitLabel(version.rateUnit || version.rate_unit)}` : '';
        return {
            value: String(profile.id),
            label: `${profile.title || `Профіль #${profile.id}`} · ${kind}${owner ? ` · ${owner}` : ''}${rate}`
        };
    });
}

function staffPayrollLegacyRateForProfession(professionKey) {
    const key = normalizeProfessionKey(professionKey);
    const primary = normalizeProfessionKey(document.getElementById('editRoleType')?.value || '');
    const unit = normalizeStaffRateUnit(currentEditRateUnit());
    const professionInput = Array.from(document.querySelectorAll('[data-profession-rate]'))
        .find(input => normalizeProfessionKey(input.dataset.professionRate) === key);
    const primaryRate = Number(document.getElementById('editHourlyRate')?.value || 0);
    const explicitRate = Number(professionInput?.value || 0);
    if (key && key !== primary && Number.isFinite(explicitRate) && explicitRate > 0) {
        return { rate: explicitRate, rateUnit: unit, source: 'staff_profession_rates' };
    }
    if (Number.isFinite(primaryRate) && primaryRate > 0) {
        return { rate: primaryRate, rateUnit: unit, source: key === primary ? 'staff.hourly_rate' : 'staff.hourly_rate fallback' };
    }
    return { rate: 0, rateUnit: unit, source: 'legacy empty' };
}

function staffPayrollProfileDayDiff(activeProfile = null, baseProfile = null) {
    const activeVersion = payrollProfileCurrentVersion(activeProfile || {});
    const baseVersion = payrollProfileCurrentVersion(baseProfile || {});
    if (!activeVersion || !baseVersion) return [];
    const activeUnit = normalizeStaffRateUnit(activeVersion.rateUnit || activeVersion.rate_unit);
    const baseUnit = normalizeStaffRateUnit(baseVersion.rateUnit || baseVersion.rate_unit);
    const diffs = [];
    if (activeUnit !== baseUnit) {
        diffs.push(`одиниця: ${payrollProfileRateUnitLabel(baseUnit)} → ${payrollProfileRateUnitLabel(activeUnit)}`);
    }
    const activeDefault = payrollProfileNumber(activeVersion.defaultRate ?? activeVersion.default_rate, 0);
    const baseDefault = payrollProfileNumber(baseVersion.defaultRate ?? baseVersion.default_rate, 0);
    if (activeDefault !== baseDefault) {
        diffs.push(`default: ${payrollProfileMoney(baseDefault)} → ${payrollProfileMoney(activeDefault)}`);
    }
    if (activeUnit !== 'month' || baseUnit !== 'month') {
        PAYROLL_PROFILE_WEEKDAYS.forEach(day => {
            const activeRate = payrollProfileRateForDay(activeVersion, day.iso);
            const baseRate = payrollProfileRateForDay(baseVersion, day.iso);
            if (activeRate !== baseRate) diffs.push(`${day.short}: ${payrollProfileMoney(baseRate)} → ${payrollProfileMoney(activeRate)}`);
        });
    }
    return diffs;
}

const STAFF_PAYROLL_RATE_PERIODS = Object.freeze([
    { key: 'weekday', label: 'Будні', daysLabel: 'Пн–Пт', isoWeekdays: [1, 2, 3, 4, 5] },
    { key: 'weekend', label: 'Вихідні', daysLabel: 'Сб–Нд', isoWeekdays: [6, 7] }
]);

function staffPayrollProfilePeriodRate(version = null, period = STAFF_PAYROLL_RATE_PERIODS[0]) {
    if (!version) return { value: '—', hint: 'Профіль не налаштовано', mixed: false };
    const unit = normalizeStaffRateUnit(version.rateUnit || version.rate_unit);
    if (unit === 'month') {
        return { value: '—', hint: 'Для місячної ставки не застосовується', mixed: false };
    }
    const rates = period.isoWeekdays.map(day => payrollProfileRateForDay(version, day));
    const uniqueRates = [...new Set(rates)];
    const mixed = uniqueRates.length > 1;
    const value = mixed
        ? `${payrollProfileMoney(Math.min(...uniqueRates))}–${payrollProfileMoney(Math.max(...uniqueRates))}`
        : payrollProfileMoney(uniqueRates[0] || 0);
    return {
        value,
        hint: `${period.daysLabel} · ${payrollProfileRateUnitLabel(unit)}${mixed ? ' · є денні винятки' : ''}`,
        mixed
    };
}

function staffPayrollProfilePeriodSummary(version = null) {
    return STAFF_PAYROLL_RATE_PERIODS.map(period => {
        const rate = staffPayrollProfilePeriodRate(version, period);
        return `<div data-payroll-rate-period="${period.key}"${rate.mixed ? ' class="is-mixed"' : ''}>
            <span>${period.label}</span>
            <strong>${escapeHtml(rate.value)}</strong>
            <small>${escapeHtml(rate.hint)}</small>
        </div>`;
    }).join('');
}

function renderStaffPayrollProfileDiff(activeProfile = null, baseProfile = null) {
    if (!activeProfile || !baseProfile || Number(activeProfile.id) === Number(baseProfile.id)) {
        return '<div class="hr-staff-payroll-profile-diff is-muted">Відмінностей від базового профілю немає.</div>';
    }
    const diffs = staffPayrollProfileDayDiff(activeProfile, baseProfile);
    if (!diffs.length) return '<div class="hr-staff-payroll-profile-diff is-muted">Профіль окремий, але умови збігаються з базовим.</div>';
    return `<div class="hr-staff-payroll-profile-diff">
        <strong>Diff із базовим профілем</strong>
        <span>${diffs.slice(0, 8).map(escapeHtml).join(' · ')}${diffs.length > 8 ? ' · …' : ''}</span>
    </div>`;
}

function renderStaffPayrollProfileCard(professionKey) {
    const key = normalizeProfessionKey(professionKey);
    const { assignment, profile, defaultProfile, source } = staffPayrollEffectiveProfileForProfession(key);
    const version = payrollProfileCurrentVersion(profile || {});
    const profileKind = profile?.profileKind || profile?.profile_kind || '';
    const effectiveDates = assignment
        ? `${formatStaffDateValue(staffPayrollAssignmentFrom(assignment))}${staffPayrollAssignmentTo(assignment) ? ` → ${formatStaffDateValue(staffPayrollAssignmentTo(assignment))}` : ' → без завершення'}`
        : (version ? payrollProfileVersionLabel(version) : '—');
    const legacy = staffPayrollLegacyRateForProfession(key);
    const legacyLabel = profile
        ? `legacy не використовується${legacy.rate > 0 ? ` · було ${formatStaffRate(legacy.rate, legacy.rateUnit)}` : ''}`
        : (legacy.rate > 0 ? `legacy fallback: ${formatStaffRate(legacy.rate, legacy.rateUnit)}` : 'legacy не задано');
    const actionDisabled = staffProfileDirtyScopes().includes('work') ? ' disabled title="Спершу збережіть робочі дані працівника"' : '';
    return `<article class="hr-staff-payroll-profile-card" data-staff-payroll-profession="${escapeHtml(key)}">
        <header class="hr-staff-payroll-profile-card-head">
            <div>
                <strong>${escapeHtml(professionTitle(key) || key)}</strong>
                <span>${escapeHtml(staffPayrollProfileSourceLabel(source))}</span>
            </div>
            <div class="hr-payroll-profile-badges">
                <span class="hr-payroll-profile-badge ${source === 'temporary' ? 'is-draft' : source === 'unresolved' ? 'is-legacy' : 'is-ready'}">${escapeHtml(staffPayrollProfileSourceLabel(source))}</span>
                ${profileKind ? `<span class="hr-payroll-profile-badge">${escapeHtml(profileKind)}</span>` : ''}
            </div>
        </header>
        <div class="hr-payroll-profile-rate-grid">
            <div><span>Active profile</span><strong>${profile ? escapeHtml(profile.title || `Профіль #${profile.id}`) : '—'}</strong><small>${profile ? `ID ${Number(profile.id)}` : 'Немає default-профілю'}</small></div>
            <div><span>Одиниця</span><strong>${version ? escapeHtml(payrollProfileRateUnitLabel(version.rateUnit || version.rate_unit)) : '—'}</strong></div>
            <div><span>Default rate</span><strong>${version ? payrollProfileMoney(version.defaultRate ?? version.default_rate) : '—'}</strong><small>${escapeHtml(legacyLabel)}</small></div>
            <div><span>Версія / дати</span><strong>${escapeHtml(version ? payrollProfileVersionLabel(version) : '—')}</strong><small>${escapeHtml(effectiveDates)}</small></div>
        </div>
        <div class="hr-payroll-profile-period-grid">${staffPayrollProfilePeriodSummary(version)}</div>
        ${renderStaffPayrollProfileDiff(profile, defaultProfile)}
        <div class="hr-staff-payroll-profile-actions">
            <button type="button" data-staff-payroll-profile-action="use-default" data-profession-key="${escapeHtml(key)}"${!assignment ? ' disabled' : actionDisabled}>Використовувати базовий</button>
            <button type="button" data-staff-payroll-profile-action="choose" data-profession-key="${escapeHtml(key)}"${actionDisabled}>Вибрати наявний</button>
            <button type="button" data-staff-payroll-profile-action="clone" data-profession-key="${escapeHtml(key)}" data-profile-id="${profile ? Number(profile.id) : ''}"${!profile ? ' disabled' : actionDisabled}>Клонувати для працівника</button>
            <button type="button" data-staff-payroll-profile-action="temporary" data-profession-key="${escapeHtml(key)}"${actionDisabled}>Тимчасове призначення</button>
            <button type="button" data-staff-payroll-profile-action="change" data-profession-key="${escapeHtml(key)}" data-profile-id="${profile ? Number(profile.id) : ''}"${!profile ? ' disabled' : actionDisabled}>Змінити з дати</button>
            <button type="button" data-staff-payroll-profile-action="history" data-profession-key="${escapeHtml(key)}">Історія</button>
        </div>
    </article>`;
}

function renderStaffPayrollLegacyPanel(professionKeys = currentStaffPayrollProfessionKeys()) {
    const rows = professionKeys.map(key => {
        const legacy = staffPayrollLegacyRateForProfession(key);
        const defaultProfile = staffPayrollDefaultProfileForProfession(key);
        const actionDisabled = staffProfileDirtyScopes().includes('work') ? ' disabled title="Спершу збережіть робочі дані працівника"' : '';
        return `<div class="hr-staff-payroll-legacy-row" data-legacy-profession="${escapeHtml(key)}">
            <div>
                <strong>${escapeHtml(professionTitle(key) || key)}</strong>
                <span>${escapeHtml(legacy.source)} · статус: ще не конвертовано</span>
            </div>
            <div>
                <b>${legacy.rate > 0 ? escapeHtml(formatStaffRate(legacy.rate, legacy.rateUnit)) : '—'}</b>
                <small>${defaultProfile ? `default profile: ${escapeHtml(defaultProfile.title || `#${defaultProfile.id}`)}` : 'default профілю немає'}</small>
            </div>
            <button type="button" data-staff-payroll-profile-action="convert-legacy" data-profession-key="${escapeHtml(key)}"${actionDisabled}>${legacy.rate > 0 ? 'Перенести у персональний профіль' : 'Створити персональний профіль'}</button>
        </div>`;
    }).join('');
    return `<section class="hr-staff-payroll-legacy-panel" aria-label="Базові fallback-ставки">
        <div class="hr-staff-payroll-legacy-head">
            <strong>Базові fallback-ставки</strong>
            <span>Резервні значення старої моделі. Персональні будні й вихідні створюються окремо для кожної професії.</span>
        </div>
        ${rows || '<div class="hr-payroll-profile-empty-state">Професії ще не вибрані.</div>'}
    </section>`;
}

function renderStaffPayrollProfiles() {
    const root = document.getElementById('editStaffPayrollProfiles');
    if (!root) return;
    const professionKeys = currentStaffPayrollProfessionKeys();
    if (!professionKeys.length) {
        root.innerHTML = '<div class="hr-payroll-profile-empty-state">Додайте професію працівнику, щоб побачити default-профіль.</div>';
        return;
    }
    root.innerHTML = [
        ...professionKeys.map(renderStaffPayrollProfileCard),
        renderStaffPayrollLegacyPanel(professionKeys)
    ].join('');
}

async function loadStaffPayrollProfiles(staffId, options = {}) {
    const root = document.getElementById('editStaffPayrollProfiles');
    if (!root || !staffId) return null;
    const seq = ++staffPayrollProfilesLoadSeq;
    root.setAttribute('aria-busy', 'true');
    root.innerHTML = '<div class="hr-payroll-profile-empty-state">Завантажуємо зарплатні профілі працівника...</div>';
    const [profilesResponse, assignmentsResponse] = await Promise.all([
        hrFetch('/payroll-profiles?include_archived=true').catch(error => ({ success: false, error: error?.message })),
        hrFetch(`/staff/${Number(staffId)}/payroll-profile-assignments?include_past=true`).catch(error => ({ success: false, error: error?.message })),
        ensureProfessionsLoaded({ silent: true })
    ]);
    if (seq !== staffPayrollProfilesLoadSeq || !isActiveStaffEditLoad(staffId)) return { success: false, stale: true };
    root.setAttribute('aria-busy', 'false');
    if (!profilesResponse?.success || !assignmentsResponse?.success) {
        const error = profilesResponse?.error || assignmentsResponse?.error || 'Не вдалося завантажити зарплатні профілі.';
        staffPayrollProfileState = { staffId: Number(staffId), profiles: [], assignments: [], history: null, preview: null, error };
        root.innerHTML = renderStaffFoundationEmpty(error);
        return { success: false, error };
    }
    staffPayrollProfileState = {
        ...staffPayrollProfileState,
        staffId: Number(staffId),
        profiles: Array.isArray(profilesResponse.data) ? profilesResponse.data : [],
        assignments: Array.isArray(assignmentsResponse.data?.assignments) ? assignmentsResponse.data.assignments : [],
        history: null,
        error: ''
    };
    renderStaffPayrollProfiles();
    return { success: true };
}

function ensureStaffPayrollProfileCanMutate() {
    if (staffProfileDirtyScopes().includes('work')) {
        showNotification('Спершу збережіть робочі дані працівника: професії змінилися, тому зарплатні призначення поки заблоковані.', 'warning');
        void activateStaffProfileTab('work');
        return false;
    }
    return true;
}

async function staffPayrollSaveAssignmentPatch(staffId, assignments = [], removeAssignmentIds = [], reason = '') {
    const response = await hrFetch(`/staff/${Number(staffId)}/payroll-profile-assignments`, {
        method: 'PUT',
        body: {
            mode: 'patch',
            assignments,
            removeAssignmentIds,
            reason: reason || 'Staff payroll profile assignment update'
        }
    });
    if (!response?.success) {
        showNotification(response?.error || 'Не вдалося оновити призначення зарплатного профілю', 'error');
        return response || { success: false };
    }
    staffPayrollProfileState.assignments = Array.isArray(response.data?.assignments) ? response.data.assignments : staffPayrollProfileState.assignments;
    await Promise.allSettled([
        loadStaffPayrollProfiles(staffId, { force: true }),
        loadStaffPayrollProfilePreview(staffId, { force: true })
    ]);
    return response;
}

async function useDefaultStaffPayrollProfile(professionKey) {
    if (!ensureStaffPayrollProfileCanMutate()) return { success: false };
    const staffId = activeEditStaffId();
    const key = normalizeProfessionKey(professionKey);
    const result = await formModal(`Використовувати базовий профіль · ${professionTitle(key) || key}`, [
        { key: 'effectiveFrom', label: 'Дата початку', type: 'date', required: true, defaultValue: todayStr() },
        { key: 'reason', label: 'Причина', required: true, defaultValue: 'Повернення до базового зарплатного профілю' }
    ], { icon: '↩️', okText: 'Перейти на базовий' });
    if (!result) return { cancelled: true };
    const plan = staffPayrollPlanAssignmentReplacement(key, result.effectiveFrom);
    const response = await staffPayrollSaveAssignmentPatch(staffId, plan.updates, plan.removeAssignmentIds, result.reason);
    if (response?.success) showNotification('Працівник успадковує базовий зарплатний профіль', 'success');
    return response;
}

async function chooseStaffPayrollProfile(professionKey, options = {}) {
    if (!ensureStaffPayrollProfileCanMutate()) return { success: false };
    const staffId = activeEditStaffId();
    const key = normalizeProfessionKey(professionKey);
    const profileOptions = staffPayrollProfileSelectOptions(key);
    if (!profileOptions.length) {
        showNotification('Для цієї професії ще немає активних зарплатних профілів.', 'warning');
        return { success: false, error: 'no_profiles' };
    }
    const isTemporary = options.assignmentKind === 'temporary';
    const result = await formModal(`${isTemporary ? 'Тимчасове призначення' : 'Вибрати зарплатний профіль'} · ${professionTitle(key) || key}`, [
        { key: 'profileId', label: 'Профіль', type: 'select', options: profileOptions, required: true },
        { key: 'effectiveFrom', label: 'Дата початку', type: 'date', required: true, defaultValue: todayStr() },
        { key: 'effectiveTo', label: 'Дата завершення', type: 'date', required: isTemporary, hint: isTemporary ? 'Для temporary завершення обовʼязкове.' : 'Порожньо = без завершення.' },
        { key: 'reason', label: 'Причина', required: true, defaultValue: isTemporary ? 'Тимчасова ставка працівника' : 'Призначення зарплатного профілю працівнику' }
    ], {
        icon: isTemporary ? '⏱️' : '💼',
        okText: isTemporary ? 'Призначити тимчасово' : 'Призначити',
        validate: values => {
            if (values.effectiveTo && values.effectiveTo < values.effectiveFrom) return { key: 'effectiveTo', message: 'Дата завершення має бути не раніше дати початку.' };
            if (isTemporary && !values.effectiveTo) return { key: 'effectiveTo', message: 'Для тимчасового призначення вкажіть дату завершення.' };
            return null;
        }
    });
    if (!result) return { cancelled: true };
    const plan = staffPayrollPlanAssignmentReplacement(key, result.effectiveFrom);
    const assignments = [
        ...plan.updates,
        {
            professionKey: key,
            profileId: Number(result.profileId),
            assignmentKind: isTemporary ? 'temporary' : 'explicit',
            effectiveFrom: result.effectiveFrom,
            effectiveTo: result.effectiveTo || null
        }
    ];
    const response = await staffPayrollSaveAssignmentPatch(staffId, assignments, plan.removeAssignmentIds, result.reason);
    if (response?.success) showNotification('Зарплатний профіль призначено', 'success');
    return response;
}

async function cloneStaffPayrollProfile(professionKey, profileId = null) {
    if (!ensureStaffPayrollProfileCanMutate()) return { success: false };
    const staffId = activeEditStaffId();
    const key = normalizeProfessionKey(professionKey);
    const source = staffPayrollProfileById(profileId) || staffPayrollEffectiveProfileForProfession(key).profile;
    if (!source) {
        showNotification('Немає профілю, який можна клонувати. Спочатку створіть базовий профіль професії.', 'warning');
        return { success: false, error: 'missing_source_profile' };
    }
    const staffName = document.getElementById('editStaffName')?.value?.trim() || `Staff #${staffId}`;
    const version = payrollProfileCurrentVersion(source);
    const copied = version
        ? `${payrollProfileMoney(version.defaultRate ?? version.default_rate)} · ${payrollProfileRateUnitLabel(version.rateUnit || version.rate_unit)} · ${payrollProfileVersionDayChips(version).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim()}`
        : 'У джерела немає активної версії.';
    const result = await formModal(`Клонувати профіль · ${professionTitle(key) || key}`, [
        { key: 'note', type: 'note', text: `Буде створено незалежний snapshot із профілю "${source.title}". Скопійовані умови: ${copied}` },
        { key: 'title', label: 'Назва клону', required: true, defaultValue: `${source.title || 'Профіль'} · ${staffName}` },
        { key: 'effectiveFrom', label: 'Дата призначення', type: 'date', required: true, defaultValue: todayStr() },
        { key: 'reason', label: 'Причина', required: true, defaultValue: 'Індивідуальні умови оплати працівника' }
    ], { icon: '👤', okText: 'Створити й призначити' });
    if (!result) return { cancelled: true };
    const cloneResponse = await hrFetch(`/payroll-profiles/${Number(source.id)}/clone`, {
        method: 'POST',
        body: {
            ownerStaffId: staffId,
            title: result.title,
            effectiveFrom: result.effectiveFrom,
            assign: false,
            reason: result.reason
        }
    });
    if (!cloneResponse?.success) {
        showNotification(cloneResponse?.error || 'Не вдалося створити персональний зарплатний профіль', 'error');
        return cloneResponse || { success: false };
    }
    const clone = cloneResponse.data?.profile || cloneResponse.data;
    const plan = staffPayrollPlanAssignmentReplacement(key, result.effectiveFrom);
    const assignmentResponse = await staffPayrollSaveAssignmentPatch(staffId, [
        ...plan.updates,
        {
            professionKey: key,
            profileId: Number(clone.id),
            assignmentKind: 'explicit',
            effectiveFrom: result.effectiveFrom,
            effectiveTo: null
        }
    ], plan.removeAssignmentIds, result.reason);
    if (assignmentResponse?.success) {
        showNotification('Персональний зарплатний профіль створено й призначено. Для зміни суботи натисніть “Змінити з дати”.', 'success');
    }
    return assignmentResponse;
}

function staffPayrollPeriodDraft(version = null, period = STAFF_PAYROLL_RATE_PERIODS[0]) {
    if (!version || normalizeStaffRateUnit(version.rateUnit || version.rate_unit) === 'month') {
        return { value: '', mixed: false };
    }
    const rates = period.isoWeekdays.map(day => payrollProfileRateForDay(version, day));
    const uniqueRates = [...new Set(rates)];
    return {
        value: uniqueRates.length === 1 && uniqueRates[0] > 0 ? String(uniqueRates[0]) : '',
        mixed: uniqueRates.length > 1
    };
}

function staffPayrollVersionPeriodFields(version = null) {
    const drafts = new Map(STAFF_PAYROLL_RATE_PERIODS.map(period => [
        period.key,
        staffPayrollPeriodDraft(version, period)
    ]));
    const mixedPeriods = STAFF_PAYROLL_RATE_PERIODS.filter(period => drafts.get(period.key)?.mixed);
    return [
        ...(mixedPeriods.length ? [{
            key: 'periodRateNotice',
            type: 'note',
            text: `Зараз у групі "${mixedPeriods.map(period => period.label).join(', ')}" є різні денні ставки. Вкажіть нову спільну ставку — після збереження вона буде однаковою для всієї групи.`
        }] : []),
        ...STAFF_PAYROLL_RATE_PERIODS.map(period => ({
            key: `${period.key}Rate`,
            label: `${period.label} (${period.daysLabel})`,
            type: 'number',
            required: true,
            hiddenWhen: values => normalizeStaffRateUnit(values.rateUnit || 'hour') === 'month',
            defaultValue: drafts.get(period.key)?.value || '',
            placeholder: 'Ставка',
            hint: `Одна ставка для ${period.daysLabel}.`
        }))
    ];
}

function validateStaffPayrollPeriodRates(values = {}) {
    const defaultRate = Number(values.defaultRate);
    if (!Number.isFinite(defaultRate) || defaultRate <= 0) {
        return { key: 'defaultRate', message: 'Базова ставка має бути більшою за нуль.' };
    }
    const unit = normalizeStaffRateUnit(values.rateUnit || 'hour');
    if (unit === 'month') {
        const hasPeriodRates = STAFF_PAYROLL_RATE_PERIODS.some(period => String(values[`${period.key}Rate`] || '').trim());
        return hasPeriodRates
            ? { key: 'rateUnit', message: 'Для місячного профілю ставки буднів і вихідних не застосовуються. Очистіть ці поля.' }
            : null;
    }
    for (const period of STAFF_PAYROLL_RATE_PERIODS) {
        const key = `${period.key}Rate`;
        const rate = Number(values[key]);
        if (!Number.isFinite(rate) || rate <= 0) {
            return { key, message: `Ставка "${period.label}" має бути більшою за нуль.` };
        }
    }
    return null;
}

function staffPayrollDayRatesFromPeriods(values = {}, defaultRate = Number(values.defaultRate)) {
    if (normalizeStaffRateUnit(values.rateUnit || 'hour') === 'month') return [];
    const dayRates = [];
    STAFF_PAYROLL_RATE_PERIODS.forEach(period => {
        const rate = Number(values[`${period.key}Rate`]);
        if (!Number.isFinite(rate) || rate <= 0 || rate === Number(defaultRate)) return;
        period.isoWeekdays.forEach(isoWeekday => dayRates.push({ isoWeekday, rate }));
    });
    return dayRates;
}

async function changeStaffPayrollProfileVersion(professionKey, profileId = null) {
    if (!ensureStaffPayrollProfileCanMutate()) return { success: false };
    const key = normalizeProfessionKey(professionKey);
    const profile = staffPayrollProfileById(profileId) || staffPayrollEffectiveProfileForProfession(key).profile;
    if (!profile) return { success: false, error: 'missing_profile' };
    const version = payrollProfileCurrentVersion(profile);
    const kind = profile.profileKind || profile.profile_kind;
    if (kind === 'shared') {
        const confirmed = await confirmHrAction('Це shared-профіль. Нова версія змінить базову оплату для всіх, хто його успадковує. Для персональних умов краще спочатку клонувати профіль для працівника.', {
            type: 'warning',
            okText: 'Продовжити'
        });
        if (!confirmed) return { cancelled: true };
    }
    const unit = normalizeStaffRateUnit(version?.rateUnit || version?.rate_unit || 'hour');
    const defaultRate = payrollProfileNumber(version?.defaultRate ?? version?.default_rate, 0);
    const result = await formModal(`Нова версія · ${profile.title || `Профіль #${profile.id}`}`, [
        { key: 'rateUnit', label: 'Одиниця оплати', type: 'select', defaultValue: unit, options: [
            { value: 'hour', label: 'За годину' },
            { value: 'day', label: 'За вихід' },
            { value: 'month', label: 'За місяць' }
        ] },
        { key: 'defaultRate', label: 'Базова ставка', type: 'number', required: true, defaultValue: String(defaultRate || '') },
        ...staffPayrollVersionPeriodFields(version),
        { key: 'effectiveFrom', label: 'Дата початку нової версії', type: 'date', required: true, defaultValue: payrollProfileNextEffectiveDate(profile) },
        { key: 'changeReason', label: 'Причина зміни', required: true, defaultValue: 'Зміна умов оплати з картки працівника' }
    ], {
        icon: '💸',
        okText: 'Створити версію',
        validate: validateStaffPayrollPeriodRates
    });
    if (!result) return { cancelled: true };
    const nextDefaultRate = payrollProfileNumber(result.defaultRate, NaN);
    const dayRates = staffPayrollDayRatesFromPeriods(result, nextDefaultRate);
    const response = await hrFetch(`/payroll-profiles/${Number(profile.id)}/versions`, {
        method: 'POST',
        body: {
            rateUnit: normalizeStaffRateUnit(result.rateUnit),
            defaultRate: nextDefaultRate,
            effectiveFrom: result.effectiveFrom,
            changeReason: result.changeReason,
            dayRates
        }
    });
    if (!response?.success) {
        showNotification(response?.error || 'Не вдалося створити нову версію профілю', 'error');
        return response || { success: false };
    }
    showNotification('Нову версію зарплатного профілю створено', 'success');
    await Promise.allSettled([
        loadStaffPayrollProfiles(activeEditStaffId(), { force: true }),
        loadStaffPayrollProfilePreview(activeEditStaffId(), { force: true })
    ]);
    return response;
}

async function convertLegacyStaffPayrollProfile(professionKey) {
    if (!ensureStaffPayrollProfileCanMutate()) return { success: false };
    const staffId = activeEditStaffId();
    const key = normalizeProfessionKey(professionKey);
    const staffName = document.getElementById('editStaffName')?.value?.trim() || `Staff #${staffId}`;
    const legacy = staffPayrollLegacyRateForProfession(key);
    const result = await formModal(`Персональна оплата · ${professionTitle(key) || key}`, [
        { key: 'title', label: 'Назва профілю', required: true, defaultValue: `Профіль · ${staffName}` },
        { key: 'rateUnit', label: 'Одиниця оплати', type: 'select', defaultValue: legacy.rateUnit, options: [
            { value: 'hour', label: 'За годину' },
            { value: 'day', label: 'За вихід' },
            { value: 'month', label: 'За місяць' }
        ] },
        { key: 'defaultRate', label: 'Базова ставка', type: 'number', required: true, defaultValue: legacy.rate > 0 ? String(legacy.rate) : '' },
        ...staffPayrollVersionPeriodFields({
            rateUnit: legacy.rateUnit,
            defaultRate: legacy.rate,
            dayRates: []
        }),
        { key: 'effectiveFrom', label: 'Дата початку', type: 'date', required: true, defaultValue: todayStr() },
        { key: 'reason', label: 'Причина', required: true, defaultValue: 'Індивідуальні умови оплати працівника' }
    ], { icon: '🔁', okText: 'Створити й призначити', validate: validateStaffPayrollPeriodRates });
    if (!result) return { cancelled: true };
    const dayRates = staffPayrollDayRatesFromPeriods(result, Number(result.defaultRate));
    const createResponse = await hrFetch('/payroll-profiles', {
        method: 'POST',
        body: {
            title: result.title,
            professionKey: key,
            profileKind: 'personal',
            ownerStaffId: staffId,
            isDefaultForProfession: false,
            status: 'active',
            rateUnit: normalizeStaffRateUnit(result.rateUnit),
            defaultRate: Number(result.defaultRate),
            effectiveFrom: result.effectiveFrom,
            changeReason: result.reason,
            dayRates
        }
    });
    if (!createResponse?.success) {
        showNotification(createResponse?.error || 'Не вдалося створити персональний зарплатний профіль', 'error');
        return createResponse || { success: false };
    }
    const profile = createResponse.data;
    const plan = staffPayrollPlanAssignmentReplacement(key, result.effectiveFrom);
    const assignmentResponse = await staffPayrollSaveAssignmentPatch(staffId, [
        ...plan.updates,
        {
            professionKey: key,
            profileId: Number(profile.id),
            assignmentKind: 'explicit',
            effectiveFrom: result.effectiveFrom,
            effectiveTo: null
        }
    ], plan.removeAssignmentIds, result.reason);
    if (assignmentResponse?.success) showNotification('Персональний зарплатний профіль створено й призначено', 'success');
    return assignmentResponse;
}

async function showStaffPayrollProfileHistory(professionKey = '') {
    const staffId = activeEditStaffId();
    const response = await hrFetch(`/staff/${Number(staffId)}/payroll-profile-history?limit=60`);
    if (!response?.success) {
        showNotification(response?.error || 'Не вдалося завантажити історію зарплатних профілів', 'error');
        return response || { success: false };
    }
    const key = normalizeProfessionKey(professionKey);
    const assignments = Array.isArray(response.data?.assignments) ? response.data.assignments : [];
    const audit = Array.isArray(response.data?.audit) ? response.data.audit : [];
    const assignmentLines = assignments
        .filter(item => !key || staffPayrollAssignmentProfessionKey(item) === key)
        .slice(0, 12)
        .map(item => `${professionTitle(staffPayrollAssignmentProfessionKey(item)) || staffPayrollAssignmentProfessionKey(item)} · ${item.profileTitle || item.profile_title || `Профіль #${staffPayrollAssignmentProfileId(item)}`} · ${staffPayrollAssignmentKind(item)} · ${staffPayrollAssignmentFrom(item)}${staffPayrollAssignmentTo(item) ? ` → ${staffPayrollAssignmentTo(item)}` : ''}`);
    const auditLines = audit.slice(0, 8).map(item => `${formatStaffHistoryTime(item.createdAt || item.created_at)} · ${item.action || 'audit'} · ${item.performedBy || item.performed_by || 'system'}`);
    await formModal(`Історія зарплатних профілів${key ? ` · ${professionTitle(key) || key}` : ''}`, [
        { key: 'assignments', type: 'note', text: `Призначення:\n${assignmentLines.length ? assignmentLines.join('\n') : 'Немає призначень для вибраної професії.'}` },
        { key: 'audit', type: 'note', text: `Audit:\n${auditLines.length ? auditLines.join('\n') : 'Подій ще немає.'}` }
    ], { icon: '🕘', okText: 'Закрити', cancelText: 'Закрити', type: 'info' });
    return response;
}

function staffPayrollPreviewMonthRange(month) {
    const safe = /^\d{4}-\d{2}$/.test(String(month || '')) ? month : todayStr().slice(0, 7);
    const [year, monthNumber] = safe.split('-').map(Number);
    const lastDay = new Date(year, monthNumber, 0).getDate();
    return {
        month: safe,
        from: `${safe}-01`,
        to: `${safe}-${String(lastDay).padStart(2, '0')}`
    };
}

function staffPayrollProfileApproxBaseDelta(row = {}) {
    const segments = Array.isArray(row.profession_rate_summary) ? row.profession_rate_summary : [];
    return segments.reduce((sum, segment) => {
        const key = normalizeProfessionKey(segment.profession_key || segment.professionKey || segment.key);
        const defaultProfile = staffPayrollDefaultProfileForProfession(key);
        const effective = staffPayrollEffectiveProfileForProfession(key).profile;
        if (!key || !defaultProfile || !effective || Number(defaultProfile.id) === Number(effective.id)) return sum;
        const defaultVersion = payrollProfileCurrentVersion(defaultProfile);
        if (!defaultVersion) return sum;
        const unit = normalizeStaffRateUnit(segment.rate_unit || segment.rateUnit || defaultVersion.rateUnit || defaultVersion.rate_unit || 'hour');
        const activeRate = Number(segment.rate || 0);
        const baseRate = payrollProfileNumber(defaultVersion.defaultRate ?? defaultVersion.default_rate, 0);
        const quantity = unit === 'month'
            ? 1
            : unit === 'day'
                ? Number(segment.days || row.days_worked || 0)
                : Number(segment.hours || row.hours_worked || 0);
        if (!Number.isFinite(activeRate) || !Number.isFinite(baseRate) || !Number.isFinite(quantity)) return sum;
        return sum + ((activeRate - baseRate) * quantity);
    }, 0);
}

function renderStaffPayrollProfilePreview(data = {}) {
    const root = document.getElementById('editStaffPayrollProfilePreview');
    if (!root) return;
    const staffId = Number(activeEditStaffId());
    const rows = Array.isArray(data.data) ? data.data : [];
    const row = rows.find(item => Number(item.staff_id || item.staffId) === staffId);
    if (!row) {
        root.innerHTML = '<div class="hr-payroll-profile-empty-state">За вибраний період немає payroll-даних для цього працівника.</div>';
        return;
    }
    const scheduled = row.days_scheduled ?? row.scheduled_days ?? row.planned_days ?? null;
    const actualDays = Number(row.days_worked || 0);
    const hours = Number(row.hours_worked || 0);
    const total = Number(row.total_salary || row.estimated_salary || 0);
    const base = Number(row.base_salary || 0);
    const overtime = Number(row.overtime_pay || 0);
    const delta = staffPayrollProfileApproxBaseDelta(row);
    const segments = Array.isArray(row.profession_rate_summary) ? row.profession_rate_summary : [];
    root.innerHTML = `<div class="hr-staff-payroll-preview-summary">
        <div><span>Заплановані виходи</span><strong>${scheduled == null ? '—' : Number(scheduled)}</strong></div>
        <div><span>Фактичні виходи</span><strong>${actualDays}</strong><small>${hours.toLocaleString('uk-UA')} год</small></div>
        <div><span>Очікувана сума</span><strong>${fmtMoney(total)}</strong><small>base ${fmtMoney(base)} · overtime ${fmtMoney(overtime)}</small></div>
        <div><span>Різниця від базового</span><strong class="${delta >= 0 ? 'is-positive' : 'is-negative'}">${delta ? fmtMoney(Math.round(delta)) : '0 ₴'}</strong><small>орієнтовно по rate summary</small></div>
    </div>
    <div class="hr-staff-payroll-preview-segments">
        ${segments.length ? segments.map(segment => {
            const key = normalizeProfessionKey(segment.profession_key || segment.professionKey || segment.key);
            const profileId = segment.profile_id || segment.profileId;
            const profileTitle = segment.profile_title || segment.profileTitle || (profileId ? `Профіль #${profileId}` : 'legacy/fallback');
            const unit = normalizeStaffRateUnit(segment.rate_unit || segment.rateUnit || 'hour');
            const quantity = unit === 'day' ? `${Number(segment.days || 0)} вих.` : unit === 'month' ? '1 період' : `${Number(segment.hours || 0).toLocaleString('uk-UA')} год`;
            return `<span>${escapeHtml(professionTitle(key) || key)} · ${escapeHtml(profileTitle)} · ${escapeHtml(formatStaffRate(Number(segment.rate || 0), unit))} · ${escapeHtml(quantity)}</span>`;
        }).join('') : '<span>Деталізація профілю в salary breakdown відсутня.</span>'}
    </div>`;
}

async function loadStaffPayrollProfilePreview(staffId, options = {}) {
    const root = document.getElementById('editStaffPayrollProfilePreview');
    if (!root || !staffId) return null;
    const monthInput = document.getElementById('editPayrollProfilePreviewMonth');
    if (monthInput && !monthInput.value) monthInput.value = currentSalaryMonth() || todayStr().slice(0, 7);
    const range = staffPayrollPreviewMonthRange(monthInput?.value || currentSalaryMonth());
    const seq = ++staffPayrollProfilePreviewSeq;
    root.setAttribute('aria-busy', 'true');
    root.innerHTML = '<div class="hr-payroll-profile-empty-state">Рахуємо payroll preview...</div>';
    const response = await hrFetch(`/salary?month=${encodeURIComponent(range.month)}&from=${encodeURIComponent(range.from)}&to=${encodeURIComponent(range.to)}`).catch(error => ({ success: false, error: error?.message }));
    if (seq !== staffPayrollProfilePreviewSeq || !isActiveStaffEditLoad(staffId)) return { success: false, stale: true };
    root.setAttribute('aria-busy', 'false');
    if (!response?.success) {
        root.innerHTML = renderStaffFoundationEmpty(response?.error || 'Не вдалося порахувати payroll preview.');
        return response || { success: false };
    }
    staffPayrollProfileState.preview = response;
    renderStaffPayrollProfilePreview(response);
    return response;
}

async function showStaffPayrollProfileSimulator() {
    const staffId = Number(activeEditStaffId());
    if (!staffId) return;
    const professionKeys = currentStaffPayrollProfessionKeys();
    if (!professionKeys.length) {
        showNotification('Спочатку додайте працівнику професію', 'warning');
        return;
    }
    const defaultProfession = professionKeys[0];
    const professionOptions = professionKeys.map(key => ({ value: key, label: professionTitle(key) || key }));
    const profileOptions = staffPayrollProfileState.profiles
        .filter(profile => profile.status !== 'archived')
        .map(profile => ({
            value: String(profile.id),
            label: `${profile.title || `#${profile.id}`} · ${professionTitle(staffPayrollProfileProfessionKey(profile)) || staffPayrollProfileProfessionKey(profile)}`
        }));
    const active = staffPayrollEffectiveProfileForProfession(defaultProfession).profile;
    if (!active) {
        showNotification('Для симулятора потрібен default або explicit профіль', 'warning');
        return;
    }
    const range = payrollProfileForecastRange(6);
    const result = await formModal('Симулятор зарплатного профілю', [
        { key: 'professionKey', label: 'Професія', type: 'select', options: professionOptions, defaultValue: defaultProfession, required: true },
        { key: 'profileAId', label: 'Профіль A', type: 'select', options: profileOptions, defaultValue: String(active.id), required: true },
        { key: 'profileBId', label: 'Профіль B для порівняння', type: 'select', options: [{ value: '', label: 'Не порівнювати' }, ...profileOptions] },
        { key: 'from', label: 'З дати', type: 'date', defaultValue: range.from, required: true },
        { key: 'to', label: 'До дати', type: 'date', defaultValue: range.to, required: true },
        { key: 'hoursPerDay', label: 'Годин на день', type: 'number', defaultValue: '8', required: true },
        { key: 'exits', label: 'К-сть виходів у періоді', type: 'number', placeholder: 'порожньо = усі дні' },
        { key: 'weekdays', label: 'Дні тижня 1-7 через кому', placeholder: '1,2,3,4,5 або 6,7' }
    ], { icon: '🧮', okText: 'Порахувати' });
    if (!result) return;
    const response = await hrFetch('/payroll-profiles/simulator', {
        method: 'POST',
        body: {
            staffId,
            professionKey: result.professionKey,
            profileAId: Number(result.profileAId),
            profileBId: result.profileBId ? Number(result.profileBId) : null,
            from: result.from,
            to: result.to,
            hoursPerDay: Number(result.hoursPerDay || 0),
            exits: result.exits ? Number(result.exits) : 0,
            weekdays: String(result.weekdays || '').split(',').map(item => Number(item.trim())).filter(Number.isInteger)
        }
    });
    if (!response?.success) {
        showNotification(response?.error || 'Не вдалося порахувати симуляцію', 'error');
        return;
    }
    const data = response.data || {};
    const primary = data.primary || {};
    const compare = data.compare || null;
    const breakdown = payrollProfileResultLines(primary.breakdown, row => `• ${row.date}: ${payrollProfileMoney(row.amount)} · ${row.formula}`, 10);
    const compareText = compare
        ? `\n\nПрофіль B: ${compare.profile?.title || ''}\nСума B: ${payrollProfileMoney(compare.total)}\nΔ B-A: ${payrollProfileMoney(data.delta)}`
        : '';
    await formModal('Результат симулятора', [
        { key: 'note', type: 'note', text: `Профіль A: ${primary.profile?.title || ''}\nПеріод: ${primary.period?.from || result.from} — ${primary.period?.to || result.to}\nСума A: ${payrollProfileMoney(primary.total)}${compareText}\n\nBreakdown:\n${breakdown || 'Немає робочих днів у сценарії.'}` }
    ], { icon: '🧮', okText: 'Закрити' });
}

async function handleStaffPayrollProfileAction(button) {
    const action = button?.dataset?.staffPayrollProfileAction;
    const professionKey = button?.dataset?.professionKey || '';
    const profileId = button?.dataset?.profileId || null;
    const actionMap = {
        'use-default': () => useDefaultStaffPayrollProfile(professionKey),
        choose: () => chooseStaffPayrollProfile(professionKey),
        clone: () => cloneStaffPayrollProfile(professionKey, profileId),
        temporary: () => chooseStaffPayrollProfile(professionKey, { assignmentKind: 'temporary' }),
        change: () => changeStaffPayrollProfileVersion(professionKey, profileId),
        history: () => showStaffPayrollProfileHistory(professionKey),
        'convert-legacy': () => convertLegacyStaffPayrollProfile(professionKey)
    };
    if (!actionMap[action]) return { success: false, error: 'unknown_action' };
    return runStaffProfileAction(button, {
        loadingLabel: 'Обробка…',
        successLabel: 'Готово',
        errorLabel: 'Помилка'
    }, actionMap[action]);
}

async function saveStaffPayrollScheme(button = null) {
    return runStaffProfileAction(button || 'editPayrollSchemeSave', {
        loadingLabel: 'Збереження…',
        successLabel: 'Збережено',
        errorLabel: 'Помилка'
    }, async () => {
        const staffId = activeEditStaffId();
        if (!staffId) return { success: false, error: 'missing_staff_id' };
        const dirtyScopes = new Set(staffProfileDirtyScopes());
        let savedRates = false;
        let savedScheme = false;
        let result = { success: true, noChanges: true };

        if (dirtyScopes.has('rates')) {
            result = await saveStaffRates(staffId);
            if (!result?.success) return result || { success: false };
            savedRates = true;
        }
        if (dirtyScopes.has('payroll')) {
            const schemeType = document.getElementById('editPayrollSchemeType')?.value || 'hourly';
            const amount = Number(document.getElementById('editPayrollSchemeAmount')?.value || 0);
            const config = collectPayrollSchemeConfigFromForm(schemeType, amount);
            result = await hrFetch(`/staff/${staffId}/payroll-scheme`, {
                method: 'PUT',
                body: {
                    scheme_type: schemeType,
                    amount,
                    config,
                    title: document.getElementById('editPayrollSchemeTitle')?.value || PAYROLL_SCHEME_LABELS[schemeType] || schemeType,
                    effective_from: document.getElementById('editPayrollSchemeEffectiveFrom')?.value || null,
                    effective_to: document.getElementById('editPayrollSchemeEffectiveTo')?.value || null
                }
            });
            if (!result?.success) {
                showNotification(result?.error || 'Не вдалося зберегти зарплатну схему', 'error');
                return result || { success: false };
            }
            await loadStaffPayrollScheme(staffId);
            markStaffProfileScopesClean(['payroll']);
            savedScheme = true;
        }
        if (savedRates && savedScheme) showNotification('Оплату збережено', 'success');
        else if (savedRates) showNotification('Базові fallback-ставки збережено', 'success');
        else if (savedScheme) showNotification('Зарплатну схему оновлено', 'success');
        else showNotification('Змін в оплаті немає', 'info');
        return result;
    });
}

async function loadStaffResourceOptions(kind = document.getElementById('editResourceKind')?.value || 'custom') {
    updateResourcePickerVisibility();
    const sourceSelect = document.getElementById('editResourceSourceId');
    const hint = document.getElementById('editResourceSourceHint');
    if (!sourceSelect) return { success: false, error: 'resource_picker_unavailable' };
    if (kind === 'custom') {
        sourceSelect.innerHTML = '<option value="">Ручний запис</option>';
        sourceSelect.disabled = false;
        if (hint) hint.textContent = 'Для ручного ресурсу достатньо назви.';
        setStaffResourceOptionsState();
        return { success: true, data: [] };
    }
    const seq = ++staffResourceOptionsLoadSeq;
    sourceSelect.innerHTML = '<option value="">Завантаження...</option>';
    sourceSelect.disabled = true;
    if (hint) hint.textContent = kind === 'costume' ? 'Підтягується з розділу Склад → Костюми.' : 'Підтягується з активних складських позицій.';
    setStaffResourceOptionsState('loading', 'Завантажуємо доступні позиції…');
    const data = await hrFetch(`/resource-options?kind=${encodeURIComponent(kind)}&limit=80`).catch(() => null);
    if (seq !== staffResourceOptionsLoadSeq) return { success: false, stale: true };
    if (!data?.success) {
        sourceSelect.innerHTML = '<option value="">Не вдалося завантажити</option>';
        sourceSelect.disabled = true;
        setStaffResourceOptionsState('error', data?.error || 'Не вдалося завантажити доступні позиції.');
        return data || { success: false, error: 'resource_options_failed' };
    }
    const items = data.data || [];
    sourceSelect.innerHTML = renderStaffResourceOptions(items);
    sourceSelect.disabled = !items.length;
    setStaffResourceOptionsState(items.length ? '' : 'empty', items.length ? '' : 'Немає доступних позицій для видачі.');
    syncResourceTitleFromOption();
    return data;
}

async function retryStaffResourceOptions(button = null) {
    return runStaffProfileAction(button, {
        loadingLabel: 'Оновлення…',
        successLabel: 'Оновлено',
        errorLabel: 'Помилка'
    }, () => loadStaffResourceOptions(document.getElementById('editResourceKind')?.value || 'custom'));
}

async function uploadStaffDocument(button = null) {
    return runStaffProfileAction(button || 'editDocumentUpload', {
        workspaceSection: 'documents',
        workspaceErrorMessage: 'Не вдалося завантажити документ. Спробуйте ще раз.',
        loadingLabel: 'Завантаження…',
        successLabel: 'Додано',
        errorLabel: 'Помилка'
    }, async () => {
        const staffId = activeEditStaffId();
        const fileInput = document.getElementById('editDocumentFile');
        const file = fileInput?.files?.[0];
        if (!staffId || !file) {
            setStaffWorkspaceFeedback('documents', 'error', 'Виберіть файл документа перед завантаженням.');
            showNotification('Виберіть файл документа', 'error');
            return { success: false, error: 'missing_document_file' };
        }
        const body = new FormData();
        body.append('document', file);
        body.append('document_type', document.getElementById('editDocumentType')?.value || 'other');
        body.append('title', document.getElementById('editDocumentTitle')?.value || file.name);
        body.append('notes', document.getElementById('editDocumentNotes')?.value || '');
        const data = await hrFetch(`/staff/${staffId}/documents`, { method: 'POST', body });
        if (!data?.success) {
            setStaffWorkspaceFeedback('documents', 'error', data?.error || 'Не вдалося завантажити документ.');
            showNotification(data?.error || 'Не вдалося завантажити документ', 'error');
            return data || { success: false };
        }
        ['editDocumentTitle', 'editDocumentNotes'].forEach(id => {
            const el = document.getElementById(id);
            if (el) el.value = '';
        });
        if (fileInput) fileInput.value = '';
        await loadStaffDocumentsAndResources(staffId);
        setStaffWorkspaceFeedback('documents', 'success', 'Документ додано до картки працівника.');
        markStaffProfileScopesClean(['documents']);
        showNotification('Документ додано', 'success');
        return data;
    });
}

function closeStaffDocumentPreview(options = {}) {
    document.getElementById('staffDocumentPreviewOverlay')?.remove();
    if (staffDocumentPreviewUrl) URL.revokeObjectURL(staffDocumentPreviewUrl);
    staffDocumentPreviewUrl = '';
    const restoreFocus = staffDocumentPreviewRestoreFocus;
    staffDocumentPreviewRestoreFocus = null;
    if (options.restoreFocus !== false && restoreFocus?.isConnected) {
        window.setTimeout(() => {
            if (!restoreFocus.isConnected) return;
            if (restoreFocus.dataset?.staffActionPending === 'true') resetStaffProfileActionState(restoreFocus);
            restoreFocus.focus({ preventScroll: true });
        }, 0);
    }
}

function showStaffDocumentPreview(documentMeta, blob, button = null) {
    closeStaffDocumentPreview({ restoreFocus: false });
    const mimeType = String(blob?.type || documentMeta?.mime_type || '').toLowerCase();
    const isPdf = mimeType === 'application/pdf';
    const isImage = ['image/jpeg', 'image/png', 'image/webp'].includes(mimeType);
    if (!isPdf && !isImage) return false;

    staffDocumentPreviewUrl = URL.createObjectURL(blob);
    staffDocumentPreviewRestoreFocus = button || document.activeElement || null;
    const overlay = document.createElement('div');
    overlay.id = 'staffDocumentPreviewOverlay';
    overlay.className = 'candidate-detail-overlay';
    overlay.style.zIndex = '31000';
    overlay.innerHTML = `<div class="candidate-detail-modal" role="dialog" aria-modal="true" aria-labelledby="staffDocumentPreviewTitle">
        <div class="candidate-detail-head">
            <div>
                <div class="candidate-detail-kicker">Приватний HR-документ</div>
                <h3 id="staffDocumentPreviewTitle">${escapeHtml(documentMeta?.title || documentMeta?.original_name || 'Перегляд документа')}</h3>
                <p>${escapeHtml(isPdf ? 'PDF · захищений перегляд' : 'Зображення · захищений перегляд')}</p>
            </div>
            <button type="button" class="candidate-detail-close" aria-label="Закрити перегляд">×</button>
        </div>
        <div data-staff-document-preview-host></div>
    </div>`;
    const modal = overlay.querySelector('.candidate-detail-modal');
    if (modal) {
        modal.style.width = 'min(1100px, 100%)';
        modal.style.maxHeight = 'calc(100dvh - 32px)';
    }
    const host = overlay.querySelector('[data-staff-document-preview-host]');
    if (host) {
        host.style.display = 'grid';
        host.style.placeItems = 'center';
        host.style.minHeight = 'min(72vh, 760px)';
        host.style.overflow = 'auto';
        host.style.borderRadius = '12px';
        host.style.background = '#e2e8f0';
        const viewer = document.createElement(isPdf ? 'iframe' : 'img');
        viewer.src = staffDocumentPreviewUrl;
        viewer.setAttribute('data-staff-document-preview', isPdf ? 'pdf' : 'image');
        if (isPdf) {
            viewer.title = 'Попередній перегляд HR-документа';
            viewer.style.width = '100%';
            viewer.style.height = 'min(72vh, 760px)';
            viewer.style.border = '0';
            viewer.style.background = '#fff';
        } else {
            viewer.alt = documentMeta?.title || documentMeta?.original_name || 'HR-документ';
            viewer.style.display = 'block';
            viewer.style.maxWidth = '100%';
            viewer.style.maxHeight = '72vh';
            viewer.style.objectFit = 'contain';
        }
        host.appendChild(viewer);
    }
    overlay.querySelector('.candidate-detail-close')?.addEventListener('click', () => closeStaffDocumentPreview());
    overlay.addEventListener('click', event => {
        if (event.target === overlay) closeStaffDocumentPreview();
    });
    overlay.addEventListener('keydown', event => {
        if (event.key === 'Escape') {
            event.preventDefault();
            closeStaffDocumentPreview();
        }
    });
    document.body.appendChild(overlay);
    overlay.querySelector('.candidate-detail-close')?.focus();
    return true;
}

async function previewStaffDocument(documentId, button = null) {
    return runStaffProfileAction(button, {
        workspaceSection: 'documents',
        workspaceErrorMessage: 'Не вдалося відкрити документ. Спробуйте завантаження.',
        loadingLabel: 'Відкриваємо…',
        successLabel: 'Відкрито',
        errorLabel: 'Помилка'
    }, async () => {
        const staffId = activeEditStaffId();
        const documentMeta = staffDocumentMetaById.get(Number(documentId));
        if (!staffId || !documentMeta?.preview_url) {
            setStaffWorkspaceFeedback('documents', 'error', 'Для цього документа доступне лише завантаження.');
            return { success: false, error: 'preview_unavailable' };
        }
        try {
            const resp = typeof apiFetchWithAuthRetry === 'function'
                ? await apiFetchWithAuthRetry(documentMeta.preview_url)
                : await fetch(documentMeta.preview_url);
            if (!resp?.ok) {
                const payload = await resp?.json?.().catch(() => ({}));
                const message = payload?.error || 'Не вдалося відкрити документ.';
                setStaffWorkspaceFeedback('documents', 'error', message);
                showNotification(message, 'error');
                return { success: false, error: message };
            }
            const blob = await resp.blob();
            if (!showStaffDocumentPreview(documentMeta, blob, button)) {
                setStaffWorkspaceFeedback('documents', 'error', 'Формат не підтримує безпечний перегляд. Завантажте файл.');
                return { success: false, error: 'preview_format_unsupported' };
            }
            setStaffWorkspaceFeedback('documents', 'success', 'Документ відкрито в захищеному перегляді.');
            return { success: true };
        } catch (err) {
            setStaffWorkspaceFeedback('documents', 'error', 'Не вдалося відкрити документ. Спробуйте завантаження.');
            showNotification('Не вдалося відкрити документ', 'error');
            return { success: false, error: err?.message || 'preview_failed' };
        }
    });
}

async function downloadStaffDocument(documentId, fallbackName = 'staff-document', button = null) {
    return runStaffProfileAction(button, {
        workspaceSection: 'documents',
        workspaceErrorMessage: 'Не вдалося скачати документ. Спробуйте ще раз.',
        loadingLabel: 'Підготовка…',
        successLabel: 'Готово',
        errorLabel: 'Помилка'
    }, async () => {
        const staffId = activeEditStaffId();
        if (!staffId || !documentId) {
            setStaffWorkspaceFeedback('documents', 'error', 'Не вдалося визначити документ для завантаження.');
            return { success: false, error: 'missing_document_id' };
        }
        const touchWindow = typeof openTouchDownloadWindow === 'function'
            ? openTouchDownloadWindow('Документ працівника')
            : null;
        try {
            const resp = typeof apiFetchWithAuthRetry === 'function'
                ? await apiFetchWithAuthRetry(`/api/hr/staff/${staffId}/documents/${documentId}/download`)
                : await fetch(`/api/hr/staff/${staffId}/documents/${documentId}/download`);
            if (!resp?.ok) {
                const payload = await resp?.json?.().catch(() => ({}));
                setStaffWorkspaceFeedback('documents', 'error', payload?.error || 'Не вдалося скачати документ.');
                showNotification(payload?.error || 'Не вдалося скачати документ', 'error');
                if (typeof closeTouchDownloadWindow === 'function') closeTouchDownloadWindow(touchWindow);
                return { success: false, error: payload?.error || 'download_failed' };
            }
            const blob = await resp.blob();
            const documentMeta = staffDocumentMetaById.get(Number(documentId));
            const filename = documentMeta?.original_name || documentMeta?.title || fallbackName || 'staff-document';
            if (typeof finishBlobDownload === 'function') {
                finishBlobDownload(blob, filename, { touchWindow, successMessage: 'Документ підготовлено' });
            } else {
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = filename;
                document.body.appendChild(a);
                a.click();
                a.remove();
                URL.revokeObjectURL(url);
            }
            setStaffWorkspaceFeedback('documents', 'success', 'Документ підготовлено до завантаження.');
            return { success: true };
        } catch (err) {
            if (typeof closeTouchDownloadWindow === 'function') closeTouchDownloadWindow(touchWindow);
            setStaffWorkspaceFeedback('documents', 'error', 'Не вдалося скачати документ. Спробуйте ще раз.');
            showNotification('Не вдалося скачати документ', 'error');
            return { success: false, error: err?.message || 'download_failed' };
        }
    });
}

